/// Each recorded file is owned by the host checkpoint through its prefix
/// length and digest, never by a separate replay recovery authority.
#[derive(Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeRecordedPrefix {
    bytes: u64,
    sha256: String,
}

#[derive(Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeBattleRecordingCursor {
    input_trace: NativeRecordedPrefix,
    policy_actions: Option<NativeRecordedPrefix>,
    last_physical_checkpoint_round: Option<u64>,
    recorded_physical_checkpoints: u64,
    recorded_player_inputs: u64,
    trace_checkpoint_syncs: u64,
    trace_checkpoint_sync_wall_seconds: f64,
    trace_input_syncs: u64,
    trace_input_sync_wall_seconds: f64,
    network_events: u64,
    network_syncs: u64,
    network_sync_wall_seconds: f64,
}

/// Hash each newly synced prefix ONCE, not the full growing trace after
/// every World checkpoint. On rare process recovery the complete committed
/// prefix is rehashed before any trailing uncommitted bytes are discarded.
struct NativeRecordedPrefixHasher {
    hashed_bytes: u64,
    hasher: Sha256,
}

impl NativeRecordedPrefixHasher {
    fn new() -> Self { Self { hashed_bytes: 0, hasher: Sha256::new() } }

    fn capture(&mut self, path: &Path, bytes: u64) -> io::Result<NativeRecordedPrefix> {
        if bytes < self.hashed_bytes {
            return Err(invalid("recording checkpoint moved backwards"));
        }
        let mut reader = fs::File::open(path)?;
        reader.seek(SeekFrom::Start(self.hashed_bytes))?;
        let mut remaining = bytes - self.hashed_bytes;
        let mut buf = [0_u8; 64 * 1024];
        while remaining > 0 {
            let chunk = remaining.min(buf.len() as u64) as usize;
            let n = reader.read(&mut buf[..chunk])?;
            if n == 0 {
                return Err(invalid("recording prefix was truncated before host checkpoint"));
            }
            self.hasher.update(&buf[..n]);
            remaining -= n as u64;
        }
        self.hashed_bytes = bytes;
        Ok(NativeRecordedPrefix {
            bytes, sha256: format!("{:x}", self.hasher.clone().finalize()),
        })
    }

    fn recover(path: &Path, saved: &NativeRecordedPrefix)
        -> io::Result<(fs::File, Self)>
    {
        if saved.bytes == 0 || saved.sha256.len() != 64 ||
            !saved.sha256.bytes().all(|ch|
                ch.is_ascii_digit() || (b'a'..=b'f').contains(&ch))
        {
            return Err(invalid("invalid durable replay recording boundary"));
        }
        let metadata = fs::symlink_metadata(path)?;
        if !metadata.file_type().is_file() || metadata.len() < saved.bytes {
            return Err(invalid("native recording is missing its committed prefix"));
        }
        let mut hasher = Self::new();
        let current = hasher.capture(path, saved.bytes)?;
        if current.sha256 != saved.sha256 {
            return Err(invalid("native recording differs from the committed World"));
        }
        // The original host checkpoint is already exclusively leased.
        // Discard only bytes that were written after that committed World.
        let mut file = fs::OpenOptions::new().read(true).write(true).open(path)?;
        file.set_len(saved.bytes)?;
        file.sync_data()?;
        file.seek(SeekFrom::Start(saved.bytes))?;
        Ok((file, hasher))
    }
}

/// Opt-in training recovery batches full World serialization at a coarse
/// interval; a crash replays the uncommitted tail from the last fixed tick.
const TRAINING_RECOVERY_ROUND_INTERVAL: u64 = 4096;
/// Interactive checkpointing must not serialize a large World on every
/// rendered/physics tick. Bound lost work while retaining smooth play.
const GAMEPLAY_RECOVERY_ROUND_INTERVAL: u64 = 256;

fn one_episode() -> u32 { 1 }

fn invalid(message: impl Into<String>) -> io::Error {
    io::Error::new(ErrorKind::InvalidInput, message.into())
}

fn contextual(context: &str, error: impl std::fmt::Debug) -> io::Error {
    io::Error::other(format!("{context}: {error:?}"))
}

fn nonzero(value: u32, field: &str) -> io::Result<NonZeroU32> {
    NonZeroU32::new(value).ok_or_else(|| invalid(format!("{field} must be positive")))
}

fn resolve(root: &Path, path: &Path) -> PathBuf {
    if path.is_absolute() { path.to_owned() } else { root.join(path) }
}

fn resolve_interpreter(root: &Path, path: &Path) -> PathBuf {
    // One portable authored run can move between Windows and Linux
    // without retaining the source machine's absolute venv executable.
    // The explicit "auto" selection always resolves through the
    // platform's conventional PATH command. Never rewrite model assets
    // or silently change the selected inference device.
    if path == Path::new("auto") {
        return PathBuf::from(if cfg!(windows) { "python" } else { "python3" });
    }
    // Other bare executables also resolve through PATH; explicit relative
    // script paths continue to use the owning run configuration directory.
    if !path.is_absolute() && path.components().count() == 1 {
        path.to_owned()
    } else {
        resolve(root, path)
    }
}

fn vec2(coordinates: [f32; 2]) -> Vec2 {
    Vec2::new(coordinates[0], coordinates[1])
}

/// The Stage pool remains one monotonic identity authority when independent
/// worlds retire Beacon minions concurrently on CPU workers.
fn take_stage_item_id(next_id: &AtomicI64) -> Option<i64> {
    next_id.fetch_update(Ordering::Relaxed, Ordering::Relaxed,
        |value| value.checked_add(1)).ok()
}

fn allocate_from_stage(next_id: Arc<AtomicI64>) -> MinionAllocator {
    Box::new(move |mother, _beacon| {
        let item_id = take_stage_item_id(&next_id)
            .ok_or(SquadRosterError::InvalidOwner)?;
        Ok(SquadLifetime {
            level_id: mother.level_id,
            squad_id: item_id,
            lifecycle_id: item_id as u64,
        })
    })
}


fn episode_number(group: &GroupConfig, offset: u32) -> io::Result<u32> {
    group.episode_number.checked_add(offset)
        .ok_or_else(|| invalid("group episode number exhausted"))
}

/// In Unity, the real side-to-MA-POCA team permutation alternates with
/// episode number. A reused physical scene retains ship geometry and source
/// controller identity; only that episode-owned policy routing changes.
/// An INITIAL import must already match the captured source route.
fn bind_group_routes(
    scene: &mut NativePhysicalScene,
    group: &GroupConfig,
    offset: u32,
    verify_source: bool,
    episode_seed: u64,
) -> io::Result<[i32; 2]> {
    let sides = scene.policy_group_sides()
        .map_err(|error| contextual("source policy group sides", error))?;
    let number = episode_number(group, offset)?;
    let movement_by_team = scene.source_policy_group.as_ref()
        .map(|source| source.movement_disabled_by_team);
    // Unity draws one of 12 ordered distinct quarter-turn frame pairs
    // at the beginning of EACH new self-play episode. Initial imports
    // retain the actual Unity frames; subsequent native episodes derive
    // a reproducible pair from this world's episode seed, never a global
    // process RNG. Both teams share one pair across every controlled ship.
    let frames = if verify_source { None } else {
        let mut random = RandomStream::new(
            episode_seed ^ 0x96C3_41A7_7F2D_5E19,
        );
        Some(distinct_team_frames(random.next_below(12) as u8))
    };
    for (&ship_id, binding) in &mut scene.source_policy_bindings {
        let side = scene.entities.iter().find_map(|entity| match entity {
            NativeAuthoredEntity::Ship(ship) if ship.entity_id == ship_id =>
                Some(ship.side),
            _ => None,
        }).ok_or_else(|| invalid(format!(
            "source policy ship {ship_id} has no authored side"
        )))?;
        let team = team_id_for_side(sides[0], sides[1], number, side)
            .map_err(|error| contextual("source group team", error))?;
        if verify_source && team != binding.team_id {
            return Err(invalid(format!(
                "source ship {ship_id} belongs to team {}, not configured self-play episode {number} team {team}",
                binding.team_id,
            )));
        }
        if verify_source && movement_by_team.is_some_and(|flags|
            binding.movement_disabled != flags[usize::from(team)]
        ) {
            return Err(invalid(format!(
                "source ship {ship_id} has mismatched team movement restriction",
            )));
        }
        binding.team_id = team;
        if let Some(flags) = movement_by_team {
            binding.movement_disabled = flags[usize::from(team)];
        }
        if let Some((team0, team1)) = frames {
            binding.frame = if team == 0 { team0 } else { team1 };
        }
    }
    Ok(sides)
}

fn make_setup(
    config: &RunConfig,
    level: &LevelConfig,
    assets: &NativeSceneAssets,
    period: NonZeroU32,
    next_id: Arc<AtomicI64>,
    seed: u64,
    episode_offset: u32,
    sides: [i32; 2],
    remapped_squads: &HashMap<i64, i64>,
) -> io::Result<NativeExportedPolicyLevelSetup<MinionAllocator>> {
    let groups = level.groups.as_ref().map(|group| -> io::Result<NativeAuthoredGroups> {
        let number = episode_number(group, episode_offset)?;
        let delivery = NativeGroupRewardDelivery::new(
            sides[0], sides[1], number,
        ).map_err(|error| contextual("MA-POCA group", error))?;
        Ok(NativeAuthoredGroups {
            delivery,
            participants: group.participants.iter()
                .map(|participant| (participant.side, participant.agent_id))
                .collect(),
        })
    }).transpose()?;

    Ok(NativeExportedPolicyLevelSetup {
        world_id: WorldId(level.world_id),
        level_id: level.level_id,
        seed,
        broadphase_cell_size: config.broadphase_cell_size,
        decision_period: period,
        initial_full_asteroids: 0,
        groups,
        ship_catalog: assets.shared_ship_catalog(),
        model_slots: level.model_slots.clone(),
        extraction: level.extraction.as_ref().map(|zone| bees_sim::combat_world::ExtractionZone {
            player_side: zone.player_side, center: vec2(zone.center), half_extents: vec2(zone.half_extents),
            activation_radius: zone.activation_radius, layer: zone.layer,
        }),
        survival: level.survival.map(|objective| bees_sim::episode_terminal::SurvivalObjective {
            defending_side: objective.defending_side,
            protected_ship_id: objective.protected_ship_id,
            seconds: objective.seconds,
        }),
        demolition: level.demolition.map(|objective| bees_sim::episode_terminal::DemolitionObjective {
            attacking_side: objective.attacking_side,
            target_map_object_id: objective.target_map_object_id,
            seconds: objective.seconds,
        }),
        escort: level.escort.map(|objective| bees_sim::episode_terminal::EscortObjective {
            escorting_side: objective.escorting_side,
            escorted_ship_id: objective.escorted_ship_id,
            seconds: objective.seconds,
        }),
        campaign_dialogue: level.campaign_dialogue,
        reinforcements: level.reinforcements.iter().map(|wave| {
            let activation = match (
                wave.after_seconds, wave.on_campaign_cue, wave.on_ship_destroyed,
            ) {
                (Some(seconds), None, None) =>
                    bees_host::NativeReinforcementActivation::AfterSeconds(seconds),
                (None, Some(cue), None) =>
                    bees_host::NativeReinforcementActivation::OnCampaignCue(cue),
                (None, None, Some(ship_id)) =>
                    bees_host::NativeReinforcementActivation::OnShipDestroyed(ship_id),
                _ => return Err(invalid(
                    "reinforcement needs exactly one of after_seconds, on_campaign_cue or on_ship_destroyed",
                )),
            };
            Ok(bees_host::NativeReinforcementPlan {
                activation,
                squad_item_ids: wave.squad_item_ids.iter()
                    .map(|id| remapped_squads.get(id).copied().unwrap_or(*id)).collect(),
                spawn: wave.spawn.map(vec2),
                entry: wave.entry.map(vec2),
            })
        }).collect::<io::Result<Vec<_>>>()?,
        scripted_queues: level.scripted_queues.iter().map(|queue|
            bees_host::policy_only_metadata::NativeScriptedQueuePlan {
                squad_item_id: remapped_squads.get(&queue.squad_item_id)
                    .copied().unwrap_or(queue.squad_item_id),
                repeat: queue.repeat,
                activation: match queue.activation {
                    ScriptedActivationConfig::Immediate =>
                        bees_host::policy_only_metadata::NativeScriptedActivation::Immediate,
                    ScriptedActivationConfig::AfterSeconds { seconds } =>
                        bees_host::policy_only_metadata::NativeScriptedActivation::AfterSeconds(seconds),
                    ScriptedActivationConfig::OnDeployment =>
                        bees_host::policy_only_metadata::NativeScriptedActivation::OnDeployment,
                    ScriptedActivationConfig::OnArrival =>
                        bees_host::policy_only_metadata::NativeScriptedActivation::OnArrival,
                    ScriptedActivationConfig::OnCampaignCue { cue } =>
                        bees_host::policy_only_metadata::NativeScriptedActivation::OnCampaignCue(cue),
                    ScriptedActivationConfig::OnShipDestroyed { ship_id } =>
                        bees_host::policy_only_metadata::NativeScriptedActivation::OnShipDestroyed(ship_id),
                },
                orders: queue.orders.iter().map(|order| match order.clone() {
                    ScriptedOrderConfig::MoveToPoint { destination } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::MoveToPoint {
                            destination: vec2(destination),
                        },
                    ScriptedOrderConfig::MoveToRandom { range } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::MoveToRandom { range },
                    ScriptedOrderConfig::Aggressive { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Aggressive {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::AggressiveNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::AggressiveNearest,
                    ScriptedOrderConfig::BombingNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::BombingNearest,
                    ScriptedOrderConfig::ChargeNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::ChargeNearest,
                    ScriptedOrderConfig::CircleNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::CircleNearest,
                    ScriptedOrderConfig::RightSwipeNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::RightSwipeNearest,
                    ScriptedOrderConfig::LeftSwipeNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::LeftSwipeNearest,
                    ScriptedOrderConfig::InAndOutNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::InAndOutNearest,
                    ScriptedOrderConfig::TargetEnemy { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::TargetEnemy {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::Retreat { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Retreat {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::CircleSquad { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::CircleSquad {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::RightSwipe { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::RightSwipe {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::LeftSwipe { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::LeftSwipe {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::InAndOut { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::InAndOut {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::BombingRun { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::BombingRun {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::Charge { enemy_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Charge {
                            enemy_squad_item_id: remapped_squads.get(&enemy_squad_item_id)
                                .copied().unwrap_or(enemy_squad_item_id),
                        },
                    ScriptedOrderConfig::Guard { friendly_squad_item_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Guard {
                            friendly_squad_item_id: remapped_squads.get(&friendly_squad_item_id)
                                .copied().unwrap_or(friendly_squad_item_id),
                        },
                    ScriptedOrderConfig::Patrol { top_left, bottom_right } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Patrol {
                            top_left: vec2(top_left), bottom_right: vec2(bottom_right),
                        },
                    ScriptedOrderConfig::Hold =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Hold,
                    ScriptedOrderConfig::BombardMapObject { target_map_object_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::BombardMapObject {
                            target_map_object_id,
                        },
                    ScriptedOrderConfig::ClosestFriendly =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::ClosestFriendly,
                    ScriptedOrderConfig::Scouting { max_sight, human_side } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Scouting {
                            max_sight, human_side,
                        },
                    ScriptedOrderConfig::Mining { asteroid_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Mining { asteroid_id },
                    ScriptedOrderConfig::MiningNearest =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::MiningNearest,
                    ScriptedOrderConfig::Heal { beehive_ids } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::Heal {
                            beehive_ids: beehive_ids.into(),
                        },
                    ScriptedOrderConfig::HealAvailable =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::HealAvailable,
                    ScriptedOrderConfig::FullRetreat { warp_gate_id } =>
                        bees_host::policy_only_metadata::NativeScriptedOrder::FullRetreat { warp_gate_id },
                }).collect(),
            },
        ).collect(),
        allocate_minion: allocate_from_stage(next_id),
    })
}

#[derive(Default)]
struct RolloutModel {
    resident: Option<ResidentPolicyProcess>,
    recorder: Option<PolicyActionRecorder>,
    playback: Option<(PolicyActionPlayback, String)>,
}

impl RolloutModel {
    fn model_manifest_sha256(&self) -> Option<String> {
        self.resident.as_ref().map(ResidentPolicyProcess::model_manifest_sha256)
            .or_else(|| self.playback.as_ref().map(|(_, digest)| digest.clone()))
    }

    fn reload_manifest(&mut self, manifest: &Path) -> Result<u64, PolicyProcessError> {
        self.resident.as_mut().ok_or(PolicyProcessError::Unavailable)?.reload_manifest(manifest)
    }
}

impl NativePolicyInference for RolloutModel {
    type Error = PolicyProcessError;

    fn behavior_statistics(&self) -> &[f32] {
        self.resident.as_ref().map_or(&[], ResidentPolicyProcess::behavior_statistics)
    }

    fn model_generation(&self) -> u64 {
        self.resident.as_ref().map_or(0, ResidentPolicyProcess::model_generation)
    }

    fn checkpoint_model_digest(&self) -> Option<[u8; 32]> {
        // Playback cannot be resumed with a World checkpoint. Recording
        // can: the launcher syncs its exact byte cursors into the SAME
        // authoritative host transaction before sampling this model.
        if self.playback.is_some() {
            return None;
        }
        match &self.resident {
            Some(resident) => resident.checkpoint_model_digest(),
            None => Some([0_u8; 32]),
        }
    }

    fn checkpoint_sampling_state(&mut self) -> Result<Option<Vec<u8>>, Self::Error> {
        if self.playback.is_some() {
            return Ok(None);
        }
        match &mut self.resident {
            Some(resident) => resident.checkpoint_sampling_state(),
            None => Ok(Some(Vec::new())),
        }
    }

    fn restore_sampling_state(&mut self, saved: &[u8]) -> Result<bool, Self::Error> {
        if self.playback.is_some() {
            return Ok(false);
        }
        match &mut self.resident {
            Some(resident) => resident.restore_sampling_state(saved),
            None => Ok(saved.is_empty()),
        }
    }

    fn forward(
        &mut self, keys: &[PolicyAgentKey], routes: &[NativePolicyRoute],
        observations: &[f32], masks: &[PolicyActionMask],
        continuous: &mut [f32], discrete: &mut [u8],
    ) -> Result<(), Self::Error> {
        if let Some((playback, _)) = &mut self.playback {
            return Ok(playback.apply(keys, routes, observations, masks, continuous, discrete)?);
        }
        self.resident.as_mut().ok_or(PolicyProcessError::Unavailable)?
            .forward(keys, routes, observations, masks, continuous, discrete)?;
        if let Some(recorder) = &mut self.recorder {
            recorder.record(keys, routes, observations, masks, continuous, discrete)?;
        }
        Ok(())
    }
}

type RolloutHost = NativeHostRuntime<NativePolicyOnlyMetadata, MinionAllocator,
    RolloutModel, DurableDiagnosticNotifications>;

/// One canonical capture path for periodic and final v4 checkpoints.
fn replay_world_checkpoint(host: &RolloutHost, index: usize, round: u64) -> Value {
    let world = host.simulation().world(index).expect("registered native replay World");
    json!({
        "kind": "physical_state_checkpoint",
        "round": round,
        "world_id": world.id.0,
        "episode_revision": world.episode_revision(),
        "tick": world.tick(),
        "sha256": physical_world_sha256(
            world.id, world.episode_revision(), world.tick(), &world.state.combat,
        ),
        "gameplay_sha256": gameplay_world_sha256(
            world.id, world.episode_revision(), world.tick(),
            &world.state.combat, world.state.events.roster(),
            world.state.events.commands(), &world.state.metadata,
        ),
    })
}

fn gameplay_config_sha256(
    config: &RunConfig, assets: &NativeSceneAssets, interactive: bool,
) -> String {
    let hivemind = config.hivemind.as_ref().map(|network| json!({
        "endpoint": network.endpoint,
        "user_id": network.user_id,
        "version": network.version,
        "reconnect_game_id": network.reconnect_game_id,
        // Source controller and opponent identities are part of the scene.
        "issue_source_commands": network.issue_source_commands,
        "command_poll_rounds": if interactive { 1 } else { config.rounds_per_window },
    }));
    let mut inputs = json!({
        "source_assets_sha256": assets.source_assets_sha256(),
        "fragment_spawn": config.fragment_spawn,
        "decision_period": config.decision_period,
        "broadphase_cell_size": config.broadphase_cell_size,
        "interactive": interactive,
        "hivemind": hivemind,
    });
    let survival = config.levels.iter().filter_map(|level|
        level.survival.map(|objective| (level.world_id, objective)))
        .collect::<std::collections::BTreeMap<_, _>>();
    if !survival.is_empty() { inputs["survival"] = json!(survival); }
    let demolition = config.levels.iter().filter_map(|level|
        level.demolition.map(|objective| (level.world_id, objective)))
        .collect::<Vec<_>>();
    if !demolition.is_empty() { inputs["demolition"] = json!(demolition); }
    let escort = config.levels.iter().filter_map(|level|
        level.escort.map(|objective| (level.world_id, objective)))
        .collect::<Vec<_>>();
    if !escort.is_empty() { inputs["escort"] = json!(escort); }
    let extraction = config.levels.iter().filter_map(|level|
        level.extraction.as_ref().map(|zone| (level.world_id, zone)))
        .collect::<std::collections::BTreeMap<_, _>>();
    if !extraction.is_empty() { inputs["extraction"] = json!(extraction); }
    let reinforcements = config.levels.iter().filter(|level| !level.reinforcements.is_empty())
        .map(|level| (level.world_id, &level.reinforcements)).collect::<std::collections::BTreeMap<_, _>>();
    if !reinforcements.is_empty() { inputs["reinforcements"] = json!(reinforcements); }
    let scripted_queues = config.levels.iter().filter(|level| !level.scripted_queues.is_empty())
        .map(|level| (level.world_id, &level.scripted_queues))
        .collect::<std::collections::BTreeMap<_, _>>();
    if !scripted_queues.is_empty() { inputs["scripted_queues"] = json!(scripted_queues); }
    let native_layouts = config.levels.iter().filter_map(|level|
        level.native_layout.as_ref().map(|layout| (level.world_id, layout)))
        .collect::<std::collections::BTreeMap<_, _>>();
    if !native_layouts.is_empty() { inputs["native_layouts"] = json!(native_layouts); }
    let dialogue = config.levels.iter().filter_map(|level|
        level.campaign_dialogue.map(|cue| (level.world_id, cue)))
        .collect::<std::collections::BTreeMap<_, _>>();
    if !dialogue.is_empty() { inputs["campaign_dialogue"] = json!(dialogue); }
    format!("{:x}", Sha256::digest(inputs.to_string().as_bytes()))
}

fn bind_evaluation_episode(
    host: &mut RolloutHost, index: usize, level: &LevelConfig, seed: u64, scene_sha256: &str,
    gameplay_config_sha256: &str,
    episode_offset: u32, decision_period: u32,
) -> io::Result<()> {
    let world = host.simulation().world(index).ok_or_else(|| invalid("missing evaluation Level"))?;
    let id = world.id;
    let revision = world.episode_revision();
    let [bee_side, human_side] = world.state.events.sides();
    let authored_policy_slots_by_side = world.state.metadata.authored_policy_slots_by_side();
    let group_episode_number = level.groups.as_ref().map(|group|
        episode_number(group, episode_offset)).transpose()?;
    let mut group_team_by_side = std::collections::BTreeMap::new();
    if let Some(number) = group_episode_number {
        for side in [bee_side, human_side] {
            let team = team_id_for_side(bee_side, human_side, number, side)
                .map_err(|error| contextual("evaluation group team", error))?;
            group_team_by_side.insert(side, team);
        }
    }
    // The pinned initial cohort is the actual *physically enrolled*
    // reward group. Future reinforcement reservations are absent here;
    // dynamic admissions extend this cohort through their durable journal
    // receipts, including Queen spawns and deferred squad deployment.
    let group_agents_by_team = world.state.events.group_delivery()
        .map(|group| group.participants_by_team())
        .unwrap_or_default();
    let context = EpisodeEvaluationContext {
        level_id: level.level_id,
        seed,
        scene_sha256: scene_sha256.to_owned(),
        gameplay_config_sha256: gameplay_config_sha256.to_owned(),
        bee_side,
        human_side,
        policy_generation: host.model_mut().model_generation(),
        policy_manifest_sha256: host.model_mut().model_manifest_sha256(),
        model_slots_by_team: level.model_slots.iter().map(|(&team, &slot)| (team, slot)).collect(),
        authored_policy_slots_by_side,
        group_episode_number,
        group_team_by_side,
        group_agents_by_team,
        decision_period,
    };
    host.sink_mut().bind_evaluation_episode(id, revision, context)
}

struct RunNetwork {
    worker: NativeSocketWorker,
    levels: Vec<i32>,
    next_level: usize,
    server_game_id: Option<i64>,
    user_id: u64,
    version: f32,
    auth_ticket: Option<String>,
    flush_seconds: u32,
    issue_source_commands: bool,
    scheduler: NativeSourceCommandScheduler,
    recorded_network_events: u64,
    recorded_network_syncs: u64,
    recorded_network_sync_wall_seconds: f64,
}

impl RunNetwork {
    fn start(config: &HiveMindConfig, levels: &[LevelConfig], fixed_dt_by_level: &[f32],
        connection: &mut DurableHiveMindConnection, recovered_game_id: Option<i64>,
    ) -> io::Result<Self>
    {
        if config.reconnect_game_id.is_some() && recovered_game_id.is_some() &&
            config.reconnect_game_id != recovered_game_id
        {
            return Err(invalid("recovered HiveMind Game ID conflicts with configured reconnection"));
        }
        let game_id = recovered_game_id.or(config.reconnect_game_id);
        let auth_ticket = config.auth_ticket_env.as_ref().map(|name|
            env::var(name).map_err(|_| invalid("configured HiveMind auth ticket environment variable is unavailable")))
            .transpose()?;
        let levels = levels.iter().map(|level| i32::try_from(level.level_id)
            .map_err(|_| invalid("HiveMind server LevelId must fit int32"))).collect::<Result<Vec<_>,_>>()?;
        if fixed_dt_by_level.len() != levels.len() {
            return Err(invalid("HiveMind command clock has mismatched Level timesteps"));
        }
        let scheduler = NativeSourceCommandScheduler::new(&levels, fixed_dt_by_level)?;
        let mut network = Self {
            worker: NativeSocketWorker::start(config.endpoint.clone(), config.allow_insecure_loopback)
                .map_err(|error| contextual("HiveMind network startup", error))?,
            levels, next_level: 0, server_game_id: game_id,
            user_id: config.user_id, version: config.version,
            auth_ticket, flush_seconds: config.shutdown_flush_seconds,
            issue_source_commands: config.issue_source_commands,
            scheduler, recorded_network_events: 0,
            recorded_network_syncs: 0,
            recorded_network_sync_wall_seconds: 0.0,
        };
        let (kind, server_game_id) = game_id
            .map_or((SetupKind::Initial, 0), |game| (SetupKind::Reconnect, game));
        network.setup_next(connection, kind, server_game_id)?;
        Ok(network)
    }

    fn setup_next(&mut self, connection: &mut DurableHiveMindConnection, kind: SetupKind, server_game_id: i64)
        -> io::Result<()>
    {
        self.worker.send_setup(connection, SetupLevelIdentity {
            kind, level_id: self.levels[self.next_level], server_game_id,
            user_id: self.user_id, auth_ticket: self.auth_ticket.as_deref(), version: self.version,
        }).map_err(|error| contextual("HiveMind Level setup", error))
    }

    // The shared scheduler is also available to other native host adapters.
    // The launcher remains only the source of socket/setup readiness.
    fn issue_due_source_commands(&mut self, host: &mut RolloutHost) -> io::Result<()> {
        if !self.issue_source_commands { return Ok(()); }
        self.scheduler.issue_due(host, &self.worker,
            self.next_level == self.levels.len())
    }

    fn rounds_until_next_source_pulse(&mut self, host: &RolloutHost) -> io::Result<u64> {
        if !self.issue_source_commands || !self.worker.ready() {
            return Ok(u64::MAX);
        }
        self.scheduler.rounds_until_next_pulse(host,
            self.next_level == self.levels.len())
    }

    fn poll(&mut self, host: &mut RolloutHost,
        mut recording: Option<(&mut fs::File, u64)>,
    ) -> io::Result<()> {
        let mut recorded_this_poll = false;
        for _ in 0..16 {
            let event = if self.issue_source_commands {
                host.poll_network_and_continue_source_commands(&mut self.worker)
            } else {
                host.poll_network(&mut self.worker)
            };
            let Some(event) = event
                .map_err(|error| contextual("HiveMind network", error))? else { break; };
            // Snapshot the authenticated ingress after the canonical host
            // accepted it but before consuming this event's setup/command
            // continuation. No second response decoder or game ledger.
            let record = if recording.is_some() {
                Some(match &event {
                    NativeHostSocketEvent::SetupAccepted {
                        request_hash, server_game_id,
                    } => json!({
                        "kind": "hivemind_setup", "request_hash": request_hash,
                        "server_game_id": server_game_id,
                    }),
                    NativeHostSocketEvent::ServerFrame {
                        request_hash, raw_frame, ..
                    } => json!({
                        "kind": "hivemind_frame", "request_hash": request_hash,
                        "frame": std::str::from_utf8(raw_frame)
                            .map_err(|error| contextual("HiveMind frame UTF-8", error))?,
                    }),
                })
            } else { None };
            match event {
                NativeHostSocketEvent::SetupAccepted { request_hash, server_game_id } => {
                    if self.server_game_id.is_some_and(|old| old != server_game_id) {
                        return Err(invalid("HiveMind reconnect acknowledged a different server Game"));
                    }
                    self.server_game_id = Some(server_game_id);
                    println!("{}", json!({"kind": "hivemind_setup", "request_hash": request_hash,
                        "game_id": server_game_id, "level_id": self.levels[self.next_level]}));
                    self.next_level += 1;
                    if self.next_level < self.levels.len() {
                        self.setup_next(host.connection_mut(), SetupKind::Initial, 0)?;
                    }
                }
                NativeHostSocketEvent::ServerFrame { request_hash,
                    delivery: Some(bees_gameplay::level_host::NativeHiveMindFrameDelivery::StoreCommands(ack)), .. } => {
                    // 200 and 409 have already changed the durable retry
                    // ledger. A transient rejection leaves its ORIGINAL
                    // payload/hash owned by the connection. Give it one
                    // bounded retry, not a new StoreCommands reservation or
                    // an unbounded resend loop on each poll.
                    let transient = matches!(
                        &ack,
                        bees_hivemind::outcomes::StoreAcknowledgement::Rejected { status, .. }
                            if *status == 408 || *status == 429 || *status >= 500
                    );
                    let retry_scheduled = transient &&
                        self.worker.retry_transient_store_once(request_hash);
                    println!("{}", json!({"kind": "hivemind_store_ack", "request_hash": request_hash,
                        "acknowledgement": format!("{ack:?}"),
                        "retry_scheduled": retry_scheduled}));
                }
                NativeHostSocketEvent::ServerFrame {
                    delivery: Some(
                        bees_gameplay::level_host::NativeHiveMindFrameDelivery::Strategy(_) |
                        bees_gameplay::level_host::NativeHiveMindFrameDelivery::Targeting(_)
                    ), ..
                } if self.issue_source_commands => {
                    // The SAME authoritative Level driver has already
                    // installed the selection and retained learning credit.
                }
                // Reject every other message rather than losing a setting,
                // unowned response or unresolved server reservation.
                NativeHostSocketEvent::ServerFrame { request_hash, delivery, .. } =>
                    return Err(invalid(format!("unowned HiveMind feature reply {request_hash}: {delivery:?}"))),
            }
            if let (Some(record), Some((trace, round))) = (record, recording.as_mut()) {
                let mut record = record;
                record["round"] = json!(*round);
                writeln!(*trace, "{record}")?;
                self.recorded_network_events += 1;
                recorded_this_poll = true;
            }
        }
        // A single sync amortizes disk barriers across up to sixteen
        // authenticated HiveMind ingress events at this fixed boundary.
        // The actual Level and durable request ledger already own their
        // effects; the replay record must be committed before the next
        // physical tick can depend on these server decisions.
        if recorded_this_poll {
            if let Some((trace, _)) = recording {
                let started = Instant::now();
                let synced = trace.sync_data();
                self.recorded_network_sync_wall_seconds += started.elapsed().as_secs_f64();
                self.recorded_network_syncs += 1;
                synced?;
            }
        }
        Ok(())
    }
}

/// Offline playback uses the SAME source timer, connection allocator and
/// Level-owned server reply dispatcher. A recorded setup event substitutes
/// only for socket readiness; no live HiveMind session or new command path
/// is instantiated. Original request hashes are reconstructed from the
/// battle-start checkpoint before applying any recorded server response.
struct RecordedNetwork {
    scheduler: NativeSourceCommandScheduler,
    levels: usize,
    next_level: usize,
    pending_setup_hash: Option<i64>,
    /// The live socket pins the reconnect target and requires every
    /// subsequently added Level to share exactly that server Game.
    server_game_id: Option<i64>,
    issue_source_commands: bool,
}

impl RecordedNetwork {
    fn start(config: &HiveMindConfig, levels: &[LevelConfig],
        fixed_dt: &[f32], host: &mut RolloutHost,
    ) -> io::Result<Self> {
        let identities = levels.iter().map(|level| i32::try_from(level.level_id)
            .map_err(|_| invalid("recorded HiveMind LevelId is outside int32")))
            .collect::<io::Result<Vec<_>>>()?;
        let scheduler = NativeSourceCommandScheduler::new(&identities, fixed_dt)?;
        let pending_setup_hash = Some(host.connection_mut().next_hash()
            .map_err(|error| contextual("recorded HiveMind first setup", error))?);
        Ok(Self {
            scheduler, levels: identities.len(), next_level: 0,
            pending_setup_hash, server_game_id: config.reconnect_game_id,
            issue_source_commands: config.issue_source_commands,
        })
    }

    fn accept(&mut self, host: &mut RolloutHost,
        event: NativeTraceNetworkEvent,
    ) -> io::Result<()> {
        match event {
            NativeTraceNetworkEvent::Setup {
                request_hash, server_game_id, ..
            } => {
                if server_game_id <= 0 || self.pending_setup_hash != Some(request_hash) ||
                    self.server_game_id.is_some_and(|game| game != server_game_id)
                {
                    return Err(invalid(
                        "recorded HiveMind setup did not match the original connection or shared server Game",
                    ));
                }
                self.server_game_id = Some(server_game_id);
                self.next_level += 1;
                self.pending_setup_hash = if self.next_level < self.levels {
                    Some(host.connection_mut().next_hash()
                        .map_err(|error| contextual("recorded HiveMind setup", error))?)
                } else { None };
            }
            NativeTraceNetworkEvent::Frame { request_hash, frame, .. } => {
                // StoreCommands acknowledgements from a previously
                // established Level may arrive while another Level is
                // still setting up. The canonical connection validates
                // their hashes; do not impose a new transport order.
                let body: Value = serde_json::from_str(&frame)?;
                if body["Hash"].as_i64() != Some(request_hash) {
                    return Err(invalid("recorded HiveMind response hash disagrees with its frame"));
                }
                let delivery = host.receive_frame(frame.as_bytes())
                    .map_err(|error| contextual("recorded HiveMind delivery", error))?;
                match delivery {
                    Some(bees_gameplay::level_host::NativeHiveMindFrameDelivery::Targeting(
                        targeting,
                    )) if self.issue_source_commands => {
                        if let bees_hivemind::session::TargetingReceipt::Accepted {
                            owner, ..
                        } = targeting.receipt {
                            host.request_live_strategy(owner, targeting.opponent_id)
                                .map_err(|error| contextual(
                                    "recorded HiveMind strategy continuation", error,
                                ))?;
                        }
                    }
                    Some(bees_gameplay::level_host::NativeHiveMindFrameDelivery::Strategy(_))
                        if self.issue_source_commands => {}
                    Some(bees_gameplay::level_host::NativeHiveMindFrameDelivery::StoreCommands(_)) => {}
                    _ => return Err(invalid("unowned recorded HiveMind response")),
                }
            }
        }
        Ok(())
    }

    fn issue_due(&mut self, host: &mut RolloutHost) -> io::Result<u64> {
        if !self.issue_source_commands { return Ok(u64::MAX); }
        let ready = self.pending_setup_hash.is_none();
        self.scheduler.issue_due_with_readiness(host, ready, ready)?;
        if ready {
            self.scheduler.rounds_until_next_pulse(host, true)
        } else { Ok(u64::MAX) }
    }
}

/// Human-readable acknowledgement plus whether the authoritative Level
/// actually accepted the command. A routine user rejection must not abort
/// multiplayer, but must not be reported as a successful weapon gesture.
#[derive(Clone, Copy)]
struct PlayerInputFeedback {
    message: &'static str,
    accepted: bool,
}

fn apply_player_input(host: &mut RolloutHost, action: NativePlayerInput)
    -> Result<PlayerInputFeedback, String>
{
    use bees_host::runtime::{HostPlayerInputError, NativePlayerInputOutcome as Outcome};
    use bees_gameplay::player_inputs::{NativePlayerSupportAction, NativePlayerShipSpecialKind};
    // Live window and offline playback use precisely the same host-level
    // authority dispatch. Only human-readable feedback belongs here.
    let outcome = match host.apply_player_input(&action) {
        Ok(outcome) => outcome,
        Err(HostPlayerInputError::Gameplay(error)) if error.is_rejection() =>
            return Ok(PlayerInputFeedback { accepted: false, message: match action {
                NativePlayerInput::Move(_) => "Squad cannot accept that move",
                NativePlayerInput::Support(_) => "Squad cannot accept that command",
                NativePlayerInput::Fire(_) | NativePlayerInput::HeldFire(_) =>
                    "Squad cannot accept manual fire",
                NativePlayerInput::CeaseFire(_) => "Cannot change firing mode",
                NativePlayerInput::Special(_) => "Squad cannot accept that special",
                NativePlayerInput::MatchSpeed(_) => "Squad cannot change speed",
                NativePlayerInput::Shooting(_) => "Squad cannot change shooting priority",
                NativePlayerInput::LockOn(_) => "Squad cannot change Lock On",
                NativePlayerInput::Chase(_) => "Squad cannot change Chase",
            }}),
        Err(error) => return Err(format!("native player input: {error:?}")),
    };
    // All these typed outcomes are produced by the same host dispatcher.
    // Distinguish a valid-but-ineligible selection from a successfully
    // applied command without inferring success from display text alone.
    let accepted = match outcome {
        Outcome::Move(counts) => counts.accepted_squads > 0,
        Outcome::Support(counts) => counts.accepted_squads > 0 ||
            counts.stopped_chases > 0,
        Outcome::Fire(counts) | Outcome::CeaseFire(counts) |
        Outcome::Special(counts) | Outcome::MatchSpeed(counts) |
        Outcome::Shooting(counts) | Outcome::LockOn(counts) |
        Outcome::Chase(counts) => counts.accepted_squads > 0,
        Outcome::HeldFire(message) =>
            message != "No selected weapons accepted held fire",
    };
    let feedback = match (action, outcome) {
        (NativePlayerInput::Move(_), Outcome::Move(counts)) => {
            if counts.accepted_squads == 0 { "Selected squads cannot accept that destination" }
            else if counts.rejected_squads == 0 && counts.unreachable_squads == 0 { "Moves accepted" }
            else { "Eligible squads moved; some unavailable" }
        }
        (NativePlayerInput::Support(input), Outcome::Support(counts)) => {
            if input.action == NativePlayerSupportAction::Hold {
                if counts.stopped_chases > 0 { "Chase stopped" }
                else if counts.accepted_squads > 0 { "No active chase" }
                else { "Selected squads cannot stop chase" }
            } else if counts.accepted_squads == 0 { "Selected squads cannot accept that command" }
            else if counts.rejected_squads == 0 && counts.unavailable_squads == 0 { "Commands accepted" }
            else { "Eligible squads commanded; some unavailable" }
        }
        (NativePlayerInput::Fire(input), Outcome::Fire(counts)) => {
            if counts.accepted_squads == 0 { "Selected squads have no eligible manual weapons" }
            else if input.target.is_some() { "Point fire set" }
            else { "Point fire stopped" }
        }
        (NativePlayerInput::HeldFire(_), Outcome::HeldFire(message)) => message,
        (NativePlayerInput::Chase(input), Outcome::Chase(counts)) => {
            if counts.accepted_squads == 0 { "No selected squads can change Chase" }
            else if counts.rejected_squads > 0 { "Chase updated; some squads unavailable" }
            else if input.chasing { "Chase enabled" }
            else { "Chase disabled" }
        }
        (NativePlayerInput::LockOn(input), Outcome::LockOn(counts)) => {
            if counts.accepted_squads == 0 { "No selected enemy command can change lock" }
            else if counts.rejected_squads > 0 { "Lock On changed; some squads unavailable" }
            else if input.locked { "Locked on to current enemy" }
            else { "Lock On released" }
        }
        (NativePlayerInput::Shooting(_), Outcome::Shooting(counts)) => {
            if counts.accepted_squads == 0 { "No selected squads can change targeting" }
            else if counts.rejected_squads > 0 || counts.unavailable_squads > 0 {
                "Shooting priority changed; some squads unavailable"
            } else { "Shooting priority updated" }
        }
        (NativePlayerInput::MatchSpeed(input), Outcome::MatchSpeed(counts)) => {
            if counts.accepted_squads == 0 { "No selected squads can change speed" }
            else if counts.rejected_squads > 0 || counts.unavailable_squads > 0 {
                "Squad speeds updated; some unavailable"
            } else if input.match_speed { "Squad speeds matched" }
            else { "Original ship speeds restored" }
        }
        (NativePlayerInput::Special(input), Outcome::Special(counts)) => {
            if counts.accepted_squads == 0 { "No selected ships have a ready special" }
            else if counts.rejected_squads > 0 || counts.unavailable_squads > 0 {
                "Ready specials queued; some squads unavailable"
            } else {
                match input.kind {
                    NativePlayerShipSpecialKind::DropBeacon => "Beacon deployment queued",
                    NativePlayerShipSpecialKind::Detonate => "Detonation queued",
                    NativePlayerShipSpecialKind::Charge => "Barge charge queued",
                }
            }
        }
        (NativePlayerInput::CeaseFire(input), Outcome::CeaseFire(counts)) => {
            if counts.accepted_squads == 0 { "Selected squads cannot change firing mode" }
            else if counts.rejected_squads != 0 { "Firing mode updated; some squads unavailable" }
            else if input.cease_fire { "Cease fire enabled" }
            else { "Attack on sight enabled" }
        }
        _ => return Err("native host returned an input outcome for a different action".to_owned()),
    };
    Ok(PlayerInputFeedback { message: feedback, accepted })
}

/// Reject a remote input before touching any Level or HiveMind reservation.
 /// The source scene must explicitly mark every submitted squad on this
 /// authenticated side as player controlled. A peer cannot borrow the local
 /// UI's side or take an AI/policy squad by choosing its lifetime ID.
fn remote_side_owns_input(host: &RolloutHost, action: &NativePlayerInput, side: i32) -> bool {
    if !(1..=2).contains(&side) { return false; }
    let Some(world) = host.simulation().world(0) else { return false };
    let (id, revision) = action.episode();
    if world.id != id || world.episode_revision() != revision ||
        world.is_failed() || world.state.events.completed() ||
        world.state.events.is_failed() { return false; }
    // Transport admission owns Aim/End's peer-specific gesture lease.
    // This dispatcher remains the shared local/remote combat authority.
    // Only Begin supplies new squad lifetimes requiring individual checks.
    let owners = match action {
        NativePlayerInput::HeldFire(input) => {
            use bees_gameplay::player_inputs::NativeHeldFireAction;
            match &input.action {
                NativeHeldFireAction::Begin { squads, .. } => {
                    // Multiple controllers may fire independent squads.
                    // Runtime preflight rejects overlapping live weapons;
                    // a single peer cannot start a second active gesture.
                    if world.state.has_held_fire_for(input.controller_id) {
                        return false;
                    }
                    squads.as_slice()
                },
                NativeHeldFireAction::Aim { .. } | NativeHeldFireAction::End => {
                    return true;
                },
            }
        },
        _ => match action.squad_owners() {
            Some(owners) => owners, None => return false,
        },
    };
    if owners.is_empty() { return false; }
    owners.iter().all(|&owner| {
        world.state.events.roster().get(owner).is_some_and(|squad|
            squad.side == side &&
            bees_gameplay::player_inputs::NativePlayerAuthority::player_permissions(
                &world.state.metadata, owner
            ).is_some_and(|permission|
                permission.user_controlled && permission.can_accept_input))
    })
}

/// Temporarily bind the authenticated peer's viewer/command side only
/// around the SAME synchronous host input dispatcher as the local client.
/// Clearing the scope is mandatory on rejection as well as on success.
fn apply_remote_side_input(
    host: &mut RolloutHost, action: NativePlayerInput, side: i32,
) -> Result<PlayerInputFeedback, String> {
    if !remote_side_owns_input(host, &action, side) {
        return Err("remote player does not own every requested live squad".to_owned());
    }
    host.edit_level(0, |state, _| state.metadata.set_remote_player_side(Some(side)))
        .map_err(|error| format!("remote player authority setup: {error:?}"))?;
    let result = apply_player_input(host, action);
    host.edit_level(0, |state, _| state.metadata.set_remote_player_side(None))
        .map_err(|error| format!("remote player authority cleanup: {error:?}"))?;
    result
}

const USAGE: &str = "Usage: bees [play|run|serve] <run.json> [--output-dir <new-dir>] [--capture <frame.ppm>]
       bees hivemind-reconcile <connection-checkpoint.json> --list
       bees hivemind-reconcile <connection-checkpoint.json> --review <review.json>
       bees menu <catalog.json> --output-dir <battle-runs>
       bees library <library.json> --output-dir <player-save-root>
       bees connect <host:port> --token-file <private-file> --side <1|2>
       bees status <catalog.json> --output-dir <battle-runs>
       bees campaign <catalog.json> --output-dir <battle-runs> --mission <mission-id>
       bees campaign <catalog.json> --output-dir <battle-runs> --all
       bees campaign <catalog.json> --output-dir <battle-runs> --mission <mission-id> --serve
       bees replay-campaign <campaign-replay-setup.json> --output-dir <new-dir> --replay-inputs <player-inputs.jsonl>
       bees build <catalog.json> --output-dir <battle-runs> --side <n> --ship-type <n> --squad <saved-id>
       bees transfer <catalog.json> --output-dir <battle-runs> --ship <fleet-id> --squad <saved-id>
       bees reassign <catalog.json> --output-dir <battle-runs> --side <n> --ship <fleet-id> --from <saved-id> --squad <saved-id>
       bees squad-create <catalog.json> --output-dir <battle-runs> --side <n> --template <saved-id>
       bees tactics <catalog.json> --output-dir <battle-runs> --side <n> --squad <saved-id> --shooting <1-40> --chase <true|false> --cease-fire <true|false> [--match-speed <true|false>] [--color <inherit|clear|RRGGBB>]
  play  Open the native battle window (requires the client feature)
  serve  Host headless authenticated multiplayer with deterministic input recording
         (requires --output-dir, BEES_NATIVE_REMOTE_LISTEN and remote token)
  library  Open packaged native campaigns and quick battles
  connect  Join authoritative native multiplayer without Python
  run   Run the battle headlessly (default)
  --replay-inputs <player-inputs.jsonl>  Play back a recorded offline battle";

struct BattleRestart {
    replay_inputs: Option<PathBuf>,
}

#[derive(Clone, Copy)]
struct CampaignMission<'a> {
    campaign_id: &'a str,
    mission_id: &'a str,
    player_side: i32,
    record_fleet_stats: bool,
    bank_player_minerals: bool,
    lost_fleet_ids: Option<&'a HashSet<i64>>,
    purchased_ships: Option<&'a [NativePurchasedShip]>,
    created_squads: Option<&'a [NativeCreatedSquad]>,
    tactics: Option<&'a [NativeSavedSquadTactics]>,
    authored_roster: Option<&'a [(i64, i64, i64)]>,
    /// Exactly the unclaimed, source-priced hulls to award on the
    /// first winning completed battle, never on recorded playback.
    victory_grants: &'a [NativePurchasedShip],
    victory_squads: &'a [NativeCreatedSquad],
}

/// The immutable battle-start career projection required to reproduce a
/// recorded campaign fight after later purchases, losses, and transfers.
/// This is saved outside the run directory before gameplay writes its
/// original replay stream. It never replaces the career's transaction log.
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct CampaignReplaySetup {
    schema_version: u32,
    kind: String,
    source_config: PathBuf,
    source_config_sha256: String,
    // A recovered World must bind to the exact career projection that
    // purchased, lost and awarded its original physical FleetShips.
    // Historical replay-only setups intentionally have no such digest.
    #[serde(default)]
    career_sha256: Option<String>,
    campaign_id: String,
    mission_id: String,
    player_side: i32,
    record_fleet_stats: bool,
    bank_player_minerals: bool,
    lost_fleet_ids: Option<HashSet<i64>>,
    purchased_ships: Option<Vec<NativePurchasedShip>>,
    created_squads: Option<Vec<NativeCreatedSquad>>,
    tactics: Option<Vec<NativeSavedSquadTactics>>,
    authored_roster: Option<Vec<(i64, i64, i64)>>,
    // A live recovered battle must award exactly the rewards authorized
    // when its original career snapshot was frozen. Older replay-only
    // setups have no reward projection and remain valid for playback.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    victory_grants: Option<Vec<NativePurchasedShip>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    victory_squads: Option<Vec<NativeCreatedSquad>>,
}

impl CampaignReplaySetup {
    fn capture(source: &Path, mission: CampaignMission<'_>)
        -> Result<Self, Box<dyn Error>>
    {
        let source = source.canonicalize()?;
        Ok(Self {
            schema_version: 1,
            kind: "native_campaign_replay_setup".to_owned(),
            source_config_sha256: format!("{:x}", Sha256::digest(fs::read(&source)?)),
            source_config: source,
            career_sha256: None,
            campaign_id: mission.campaign_id.to_owned(),
            mission_id: mission.mission_id.to_owned(),
            player_side: mission.player_side,
            record_fleet_stats: mission.record_fleet_stats,
            bank_player_minerals: mission.bank_player_minerals,
            lost_fleet_ids: mission.lost_fleet_ids.cloned(),
            purchased_ships: mission.purchased_ships.map(|ships| ships.to_vec()),
            created_squads: mission.created_squads.map(|squads| squads.to_vec()),
            tactics: mission.tactics.map(|tactics| tactics.to_vec()),
            authored_roster: mission.authored_roster.map(|roster| roster.to_vec()),
            victory_grants: Some(mission.victory_grants.to_vec()),
            victory_squads: Some(mission.victory_squads.to_vec()),
        })
    }

    fn load(path: &Path) -> Result<Self, Box<dyn Error>> {
        let setup: Self = serde_json::from_slice(&fs::read(path)?)?;
        if setup.schema_version != 1 ||
            setup.kind != "native_campaign_replay_setup" ||
            setup.campaign_id.is_empty() || setup.mission_id.is_empty() ||
            !(1..=2).contains(&setup.player_side) ||
            !setup.source_config.is_absolute()
        {
            return Err(invalid("invalid recorded campaign battle configuration").into());
        }
        let source = setup.source_config.canonicalize()?;
        if format!("{:x}", Sha256::digest(fs::read(&source)?)) != setup.source_config_sha256 {
            return Err(invalid("recorded campaign source configuration changed").into());
        }
        Ok(setup)
    }

    fn matches_recovery_start(&self, original: &Self) -> Result<bool, Box<dyn Error>> {
        if self.career_sha256.as_ref().is_none_or(|digest|
            digest.len() != 64 || !digest.bytes().all(|byte|
                byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)))
        {
            return Ok(false);
        }
        let mut current = serde_json::to_value(self)?;
        let mut earlier = serde_json::to_value(original)?;
        // HashSet serialization does not preserve loss-ID iteration
        // order. These are unordered original FleetShip identities, so
        // compare sorted numeric IDs without relaxing any other field.
        for document in [&mut current, &mut earlier] {
            if let Some(ids) = document.get_mut("lost_fleet_ids")
                .and_then(Value::as_array_mut)
            {
                ids.sort_unstable_by_key(|value| value.as_i64().unwrap_or(i64::MIN));
            }
        }
        Ok(current == earlier)
    }

    // Offline replay never mutates the current career, even when its
    // saved setup contains the original run's frozen victory rewards.
    fn mission(&self) -> CampaignMission<'_> {
        CampaignMission {
            campaign_id: &self.campaign_id,
            mission_id: &self.mission_id,
            player_side: self.player_side,
            record_fleet_stats: self.record_fleet_stats,
            bank_player_minerals: self.bank_player_minerals,
            lost_fleet_ids: self.lost_fleet_ids.as_ref(),
            purchased_ships: self.purchased_ships.as_deref(),
            created_squads: self.created_squads.as_deref(),
            tactics: self.tactics.as_deref(),
            authored_roster: self.authored_roster.as_deref(),
            victory_grants: &[],
            victory_squads: &[],
        }
    }

    // Restore the ORIGINAL live career contract. No freshly computed
    // prizes or squad grants may enter a resumed World after a crash.
    fn recovery_mission(&self) -> Result<CampaignMission<'_>, Box<dyn Error>> {
        let grants = self.victory_grants.as_deref()
            .ok_or_else(|| invalid("recovered campaign lacks frozen victory grants"))?;
        let squads = self.victory_squads.as_deref()
            .ok_or_else(|| invalid("recovered campaign lacks frozen victory squads"))?;
        let mut mission = self.mission();
        mission.victory_grants = grants;
        mission.victory_squads = squads;
        Ok(mission)
    }
}

#[derive(Serialize, Deserialize)]
struct CampaignOutcome {
    campaign_id: String,
    mission_id: String,
    player_side: i32,
    winner_side: i32,
    /// Physical objective result, distinct from an ordinary faction win.
    /// Historical receipts did not record this and retain their original
    /// winner-based interpretation; new native mission receipts always do.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    mission_success: Option<bool>,
    /// Original durable result owns these one-time rewards. A replay or
    /// incomplete/defeated mission never mints a FleetShip.
    #[serde(default)]
    awarded_ships: Vec<NativePurchasedShip>,
    #[serde(default)]
    awarded_squads: Vec<NativeCreatedSquad>,
}

impl CampaignOutcome {
    fn mission_victory(&self) -> bool {
        self.mission_success.unwrap_or(self.winner_side == self.player_side)
    }
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct CampaignFleetShipOutcome {
    fleet_ship_id: i64,
    side: i32,
    minerals_mined_this_level: i32,
    /// None only for summaries written before native loss persistence.
    /// A safe extraction or WarpGate return does not set this flag.
    #[serde(default)]
    is_dead: Option<bool>,
    #[serde(default)]
    combat: Option<NativeFleetCombatStats>,
}

/// An authored saved squad is not a transient Stage squad ItemId. Ship IDs
/// are mapped to persistent FleetShip identities before world construction.
struct CampaignSquadSource {
    saved_squad_id: i64,
    side: i32,
    fleet_ship_ids: Vec<i64>,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct CampaignSquadOutcome {
    saved_squad_id: i64,
    side: i32,
    ships_deployed: u64,
    ships_lost: u64,
    damage_done: u64,
    damage_received: u64,
    kills: u64,
}

pub fn run() -> Result<(), Box<dyn Error>> {
    let mut args = env::args_os().skip(1);
    let first = match args.next() {
        Some(value) => value,
        None => {
            #[cfg(feature = "client")]
            {
                // A packaged desktop binary launches its library directly.
                // Explicit CLI run/play commands retain their original cwd.
                let executable = env::current_exe()?.canonicalize()?;
                if let Some(folder) = executable.parent() {
                    let library = folder.join("examples").join("native-library.json");
                    if library.is_file() {
                        let saves = {
                            #[cfg(windows)]
                            {
                                env::var_os("LOCALAPPDATA").or_else(|| env::var_os("USERPROFILE"))
                                    .map(PathBuf::from).unwrap_or_else(|| folder.to_path_buf())
                                    .join("BeesNative")
                            }
                            #[cfg(not(windows))]
                            {
                                let xdg = env::var_os("XDG_DATA_HOME")
                                    .map(PathBuf::from).filter(|path| path.is_absolute());
                                xdg.or_else(|| env::var_os("HOME")
                                    .map(|home| PathBuf::from(home).join(".local").join("share")))
                                    .unwrap_or_else(|| folder.to_path_buf())
                                    .join("bees-native")
                            }
                        };
                        env::set_current_dir(folder)?;
                        return run_library(&library, &saves);
                    }
                }
            }
            return Err(invalid(USAGE).into());
        }
    };
    if first == "--help" || first == "-h" {
        println!("{USAGE}");
        return Ok(());
    }
    if first == "hivemind-reconcile" {
        // This command is an OFFLINE checkpoint writer. The game/server
        // using the same connection must be stopped before the operator
        // resolves a 409. It never sends a StoreCommands request itself.
        let checkpoint = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        let operation = args.next().ok_or_else(|| invalid(USAGE))?;
        if operation == "--list" {
            if args.next().is_some() { return Err(invalid(USAGE).into()); }
            // Reuse the same checkpoint owner as a review. This command
            // cannot observe a moving allocator or half-written 409 ledger.
            let connection = DurableHiveMindConnection::open_existing(checkpoint)?;
            let mut unresolved = Vec::new();
            for hash in connection.reconciliation_hashes()
                .map_err(|error| invalid(format!("read HiveMind 409 ledger: {error:?}")))?
            {
                let ids = connection.stale_reconciliation_ids(hash)
                    .map_err(|error| invalid(format!("read stale outcome IDs: {error:?}")))?
                    .ok_or_else(|| invalid("409 reconciliation lost its original IDs"))?;
                unresolved.push(json!({
                    "request_hash": hash,
                    "stale_outcome_ids": ids,
                }));
            }
            println!("{}", json!({
                "kind": "hivemind_reconciliations",
                "unresolved": unresolved,
            }));
            return Ok(());
        }
        if operation != "--review" { return Err(invalid(USAGE).into()); }
        let review_path = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        let review: bees_hivemind::outcomes::ReconciliationReview =
            serde_json::from_slice(&fs::read(review_path)?)?;
        let mut connection = DurableHiveMindConnection::open_existing(checkpoint)?;
        let newly_reviewed = connection.review_reconciliation(review.clone())
            .map_err(|error| invalid(format!(
                "HiveMind 409 review does not match its durable reservation ledger: {error:?}"
            )))?;
        println!("{}", json!({
            "kind": "hivemind_reconciliation_review",
            "request_hash": review.request_hash,
            "stale_outcome_ids": review.stale_outcome_ids,
            "disposition": review.disposition,
            "review_reference": review.review_reference,
            "newly_reviewed": newly_reviewed,
        }));
        return Ok(());
    }
    if first == "status" {
        let catalog = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output_root = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        let catalog: battle_catalog::BattleCatalog = serde_json::from_slice(&fs::read(catalog)?)?;
        catalog.validate()?;
        let progress = catalog.load_progress(&output_root)?;
        println!("{}", catalog.status(&progress));
        return Ok(());
    }
    if first == "squad-create" {
        let catalog = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--side") {
            return Err(invalid(USAGE).into());
        }
        let side: i32 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--template") {
            return Err(invalid(USAGE).into());
        }
        let template: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        return run_create_saved_squad(&catalog, &output, side, template);
    }
    if first == "tactics" {
        let catalog = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--side") { return Err(invalid(USAGE).into()); }
        let side: i32 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--squad") { return Err(invalid(USAGE).into()); }
        let saved_squad_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--shooting") { return Err(invalid(USAGE).into()); }
        let shooting_strategy_id: u8 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--chase") { return Err(invalid(USAGE).into()); }
        let should_chase: bool = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--cease-fire") { return Err(invalid(USAGE).into()); }
        let cease_fire: bool = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        let mut match_speed = None;
        let mut color_setting = None;
        while let Some(flag) = args.next() {
            if flag == "--match-speed" && match_speed.is_none() {
                match_speed = Some(args.next().ok_or_else(|| invalid(USAGE))?
                    .to_string_lossy().parse::<bool>()?);
            } else if flag == "--color" && color_setting.is_none() {
                let value = args.next().ok_or_else(|| invalid(USAGE))?;
                color_setting = Some(parse_squad_color_setting(
                    &value.to_string_lossy(),
                )?);
            } else {
                return Err(invalid(USAGE).into());
            }
        }
        return run_set_saved_squad_tactics(&catalog, &output, NativeSavedSquadTactics {
            side, saved_squad_id, shooting_strategy_id, should_chase, cease_fire,
            match_speed, color_setting,
        });
    }
    if first == "reassign" {
        let catalog = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--side") {
            return Err(invalid(USAGE).into());
        }
        let side: i32 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--ship") {
            return Err(invalid(USAGE).into());
        }
        let fleet_ship_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--from") {
            return Err(invalid(USAGE).into());
        }
        let from_saved_squad_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--squad") {
            return Err(invalid(USAGE).into());
        }
        let to_saved_squad_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        return run_reassign_authored_ship(&catalog, &output, side,
            fleet_ship_id, from_saved_squad_id, to_saved_squad_id);
    }
    if first == "transfer" {
        let catalog = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--ship") {
            return Err(invalid(USAGE).into());
        }
        let fleet_ship_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--squad") {
            return Err(invalid(USAGE).into());
        }
        let to_saved_squad_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        return run_transfer_ship(&catalog, &output, fleet_ship_id, to_saved_squad_id);
    }
    if first == "build" {
        let catalog_path = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output_root = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--side") {
            return Err(invalid(USAGE).into());
        }
        let side: i32 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--ship-type") {
            return Err(invalid(USAGE).into());
        }
        let ship_type: u8 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_none_or(|flag| flag != "--squad") {
            return Err(invalid(USAGE).into());
        }
        let saved_squad_id: i64 = args.next().ok_or_else(|| invalid(USAGE))?
            .to_string_lossy().parse()?;
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        return run_build_ship(&catalog_path, &output_root, side, ship_type, saved_squad_id);
    }
    if first == "replay-campaign" {
        let setup_path = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--replay-inputs") {
            return Err(invalid(USAGE).into());
        }
        let input_trace = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_some() || env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_some() {
            return Err(invalid(
                "replay-campaign requires a saved source setup, trace, and a non-listening host",
            ).into());
        }
        // Preserve the original career fleet, but never post its recorded
        // outcome back to the active campaign ledger. The same replay
        // reader checks the original config/model identities and both
        // physical and gameplay signatures for each recorded boundary.
        let setup = CampaignReplaySetup::load(&setup_path)?;
        return run_session(&setup.source_config, false, false,
            Some(output), None, Some(input_trace), Some(setup.mission()));
    }
    if first == "campaign" {
        let catalog_path = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        if args.next().is_none_or(|flag| flag != "--output-dir") {
            return Err(invalid(USAGE).into());
        }
        let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
        let selector = args.next().ok_or_else(|| invalid(USAGE))?;
        if selector == "--all" {
            if args.next().is_some() { return Err(invalid(USAGE).into()); }
            return run_all_campaign_missions(&catalog_path, &output);
        }
        if selector != "--mission" { return Err(invalid(USAGE).into()); }
        let mission_id = args.next().ok_or_else(|| invalid(USAGE))?;
        let serve = match args.next() {
            None => false,
            Some(flag) if flag == "--serve" => true,
            _ => return Err(invalid(USAGE).into()),
        };
        if args.next().is_some() { return Err(invalid(USAGE).into()); }
        return run_campaign_mission(&catalog_path, &output,
            &mission_id.to_string_lossy(), serve);
    }
    if first == "connect" {
        #[cfg(feature = "client")]
        {
            let address = args.next().ok_or_else(|| invalid(USAGE))?;
            if args.next().is_none_or(|flag| flag != "--token-file") {
                return Err(invalid(USAGE).into());
            }
            let token_file = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
            if args.next().is_none_or(|flag| flag != "--side") {
                return Err(invalid(USAGE).into());
            }
            let side: i32 = args.next().ok_or_else(|| invalid(USAGE))?
                .to_string_lossy().parse()?;
            if args.next().is_some() { return Err(invalid(USAGE).into()); }
            return bees_host::presentation::connect_remote(
                &address.to_string_lossy(), &token_file, side,
            );
        }
        #[cfg(not(feature = "client"))]
        return Err(invalid("Native multiplayer client requires --features client").into());
    }
    if first == "library" {
        #[cfg(feature = "client")]
        {
            let library = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
            if args.next().is_none_or(|flag| flag != "--output-dir") {
                return Err(invalid(USAGE).into());
            }
            let save_root = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
            if args.next().is_some() { return Err(invalid(USAGE).into()); }
            return run_library(&library, &save_root);
        }
        #[cfg(not(feature = "client"))]
        return Err(invalid("The native game library requires building with --features client").into());
    }
    if first == "menu" {
        #[cfg(feature = "client")]
        {
            let catalog = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
            if args.next().is_none_or(|flag| flag != "--output-dir") {
                return Err(invalid(USAGE).into());
            }
            let output = PathBuf::from(args.next().ok_or_else(|| invalid(USAGE))?);
            if args.next().is_some() { return Err(invalid(USAGE).into()); }
            return run_menu(&catalog, &output);
        }
        #[cfg(not(feature = "client"))]
        return Err(invalid("The battle menu requires building with --features client").into());
    }
    let serve = first == "serve";
    let play = first == "play" || serve;
    let mut view = first == "play";
    let config_path = PathBuf::from(if play || first == "run" {
        args.next().ok_or_else(|| invalid(USAGE))?
    } else { first });
    let mut capture = None;
    let mut output = None;
    let mut replay_inputs = None;
    while let Some(flag) = args.next() {
        if flag == "--view" && !view {
            view = true;
        } else if flag == "--capture" && capture.is_none() {
            capture = Some(PathBuf::from(args.next()
                .ok_or_else(|| invalid("--capture requires an output .ppm path"))?));
        } else if flag == "--output-dir" && output.is_none() {
            output = Some(PathBuf::from(args.next()
                .ok_or_else(|| invalid("--output-dir requires a new or recoverable directory path"))?));
        } else if flag == "--replay-inputs" && replay_inputs.is_none() {
            replay_inputs = Some(PathBuf::from(args.next()
                .ok_or_else(|| invalid("--replay-inputs requires a trace path"))?));
        } else {
            return Err(invalid(USAGE).into());
        }
    }
    #[cfg(not(feature = "client"))]
    if view { return Err(invalid("Windowed play requires building with --features client").into()); }
    if replay_inputs.is_some() && output.is_none() {
        return Err(invalid("--replay-inputs requires --output-dir").into());
    }
    if serve {
        if view || replay_inputs.is_some() || output.is_none() ||
            env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_none()
        {
            return Err(invalid(
                "serve requires --output-dir, BEES_NATIVE_REMOTE_LISTEN, and no --view or --replay-inputs",
            ).into());
        }
        // Remote co-op can use the same durable HiveMind command source
        // and network-event trace as live campaign hosting. Mid-session
        // model reloads and asynchronous navigation still lack replayable
        // scheduling, so reject those before creating durable outputs.
        let config: RunConfig = serde_json::from_slice(&fs::read(&config_path)?)?;
        if config.levels.len() != 1 || config.episodes_per_world != 1 ||
            !config.model_updates.is_empty() || config.navigation_workers.is_some()
        {
            return Err(invalid(
                "serve requires one Level/episode with a fixed model manifest and no background navigation",
            ).into());
        }
    }
    run_session(&config_path, play, view, output, capture, replay_inputs, None)
}

fn run_session(
    config_path: &Path, play: bool, view: bool, output: Option<PathBuf>,
    capture: Option<PathBuf>, mut replay_inputs: Option<PathBuf>,
    mission: Option<CampaignMission<'_>>,
) -> Result<(), Box<dyn Error>> {
    let config_path = config_path.canonicalize()?;
    let mut replay_number = 0_u64;
    let mut battle_output = output.clone();
    let mut battle_capture = capture.clone();
    let mut grants_awarded = false;
    while let Some(restart) = run_battle(&config_path, play, view, battle_output.as_deref(), battle_capture.as_deref(),
        replay_number, replay_inputs.as_deref(), mission.map(|mut active| {
            if grants_awarded {
                active.victory_grants = &[];
                active.victory_squads = &[];
            }
            active
        }))? {
        // The result screen may launch a rematch without returning to the
        // campaign menu. The initial career projection is still pinned in
        // this session, so do not issue an already-committed reward twice.
        if !grants_awarded && mission.is_some_and(|active|
            !active.victory_grants.is_empty() || !active.victory_squads.is_empty()
        ) {
            if let Some(directory) = &battle_output {
                let receipt: Value = serde_json::from_slice(
                    &fs::read(directory.join("rollout-summary.json"))?,
                )?;
                grants_awarded = ["awarded_ships", "awarded_squads"]
                    .iter().any(|field| receipt["campaign_outcome"][field]
                        .as_array().is_some_and(|rows| !rows.is_empty()));
            }
        }
        replay_number = replay_number.checked_add(1).ok_or_else(|| invalid("replay count exhausted"))?;
        let next = output.as_ref().ok_or_else(|| invalid("replay requires --output-dir"))?
            .join(format!("replay-{replay_number:04}"));
        battle_capture = capture.as_ref().map(|_| next.join("final.ppm"));
        battle_output = Some(next);
        replay_inputs = restart.replay_inputs;
    }
    Ok(())
}

/// Immutable source identity for an interrupted non-campaign World.
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct QuickBattleStart {
    schema_version: u32,
    kind: String,
    source_config: PathBuf,
    source_sha256: String,
    #[serde(default)]
    remote_host: bool,
}

impl QuickBattleStart {
    fn capture(source: &Path, remote_host: bool) -> Result<Option<Self>, Box<dyn Error>> {
        let source = source.canonicalize()?;
        let bytes = fs::read(&source)?;
        let run: RunConfig = serde_json::from_slice(&bytes)?;
        // Replay-only games retain their input trace. Only sessions that
        // already opted into the host's authoritative World checkpoint
        // may resume a prior output directory.
        if run.host_recovery_checkpoint.is_none() { return Ok(None); }
        Ok(Some(Self {
            schema_version: 1,
            kind: "native_quick_battle_start".to_owned(),
            source_config: source,
            source_sha256: format!("{:x}", Sha256::digest(bytes)),
            remote_host,
        }))
    }

    fn load(path: &Path) -> Result<Self, Box<dyn Error>> {
        let start: Self = serde_json::from_slice(&fs::read(path)?)?;
        if start.schema_version != 1 ||
            start.kind != "native_quick_battle_start" ||
            !start.source_config.is_absolute() ||
            start.source_sha256.len() != 64 ||
            !start.source_sha256.bytes().all(|ch|
                ch.is_ascii_digit() || (b'a'..=b'f').contains(&ch))
        {
            return Err(invalid("invalid native quick battle start identity").into());
        }
        Ok(start)
    }
}

/// Only resume the original World when its exact source and committed
/// host checkpoint both survive. Never revive a battle with a changed
/// source or let a replay-only game silently inherit checkpoint semantics.
/// Callers own a writer lease across this selection and the entire battle.
fn recover_native_quick_battle(
    output_root: &Path, start: &QuickBattleStart,
) -> Result<Option<PathBuf>, Box<dyn Error>> {
    let mut original: Option<PathBuf> = None;
    if !output_root.exists() { return Ok(None); }
    for entry in fs::read_dir(output_root)? {
        let entry = entry?;
        if !entry.file_type()?.is_dir() { continue; }
        let name = entry.file_name();
        let Some(number) = name.to_str().and_then(|value|
            value.strip_prefix("battle-")).filter(|value|
                !value.is_empty() && value.bytes().all(|ch| ch.is_ascii_digit()))
        else { continue };
        if number.parse::<u64>().is_err() { continue; }
        let root = entry.path();
        let run = root.join("run");
        if !run.join("native-host-checkpoint.json").is_file() { continue; }
        let saved_path = root.join("native-quick-battle-start.json");
        if !saved_path.exists() { continue; }
        if run.is_symlink() ||
            saved_path.is_symlink() ||
            run.join("native-host-checkpoint.json").is_symlink()
        {
            return Err(invalid("native quick battle recovery path is a symlink").into());
        }
        let saved = QuickBattleStart::load(&saved_path)?;
        if saved.source_config != start.source_config ||
            saved.remote_host != start.remote_host { continue; }
        // Completed or failed prior games belong to their original immutable
        // receipts, not the current package configuration. A later game
        // update may legitimately change the static source file. Complete
        // any interrupted terminal replay footer without resimulating,
        // then skip that old run BEFORE comparing it to today's source.
        if terminal_recording::complete_committed_recording(&run)? { continue; }
        if saved.source_sha256 != start.source_sha256 {
            return Err(invalid(
                "interrupted native battle cannot resume after its source configuration changed",
            ).into());
        }
        if original.replace(run).is_some() {
            return Err(invalid("multiple interrupted Worlds claim one quick battle").into());
        }
    }
    Ok(original)
}

fn save_native_quick_battle_start(
    output: &Path, start: &QuickBattleStart,
) -> Result<(), Box<dyn Error>> {
    let parent = output.parent().ok_or_else(||
        invalid("native quick battle has no archive parent"))?;
    persist_new_json(&parent.join("native-quick-battle-start.json"), start)?;
    Ok(())
}

fn launch_catalog_battle(
    catalog: &battle_catalog::BattleCatalog,
    entry: &battle_catalog::BattleEntry,
    catalog_root: &Path,
    output_root: &Path,
    next_number: &mut u64,
    interactive: bool,
) -> Result<PathBuf, Box<dyn Error>> {
    let _writer = battle_catalog::CampaignWriterLease::acquire(output_root)?;
    // Reconstruct progress after obtaining exclusive ownership so a menu
    // cannot launch a stale roster if another client edited the account.
    let progress = catalog.load_progress(output_root)?;
    if entry.mission.as_ref().is_some_and(|mission|
        mission.requires.iter().any(|id| !progress.completed(id)))
    {
        return Err(invalid("the chosen campaign mission is no longer unlocked").into());
    }
    let config = resolve(catalog_root, entry.config_for(&progress));
    if entry.mission.is_some() &&
        env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_some()
    {
        // The original career writer lock owns the selected mission route.
        // A prior read of an unlocked/alternate campaign Level could
        // preflight a different configuration than the one we actually
        // launch after another player's persistent fleet edit.
        let selected: RunConfig = serde_json::from_slice(&fs::read(&config)?)?;
        if selected.levels.len() != 1 || selected.episodes_per_world != 1 ||
            !selected.model_updates.is_empty()
        {
            return Err(invalid(
                "campaign --serve requires one Level/episode with a fixed model manifest",
            ).into());
        }
    }
    let quick_start = if entry.mission.is_none() {
        QuickBattleStart::capture(&config,
            env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_some())?
    } else { None };
    if let Some(start) = &quick_start {
        if let Some(output) = recover_native_quick_battle(output_root, start)? {
            println!("{}", json!({
                "kind": "native_quick_battle_recovered",
                "source": start.source_config,
                "run": output,
            }));
            run_session(&start.source_config, interactive, interactive,
                Some(output.clone()), None, None, None)?;
            return Ok(output);
        }
    }
    let mut purchased = entry.mission.as_ref()
        .map(|mission| progress.purchases_for_side(mission.player_side));
    let created = entry.mission.as_ref()
        .map(|mission| progress.created_squads_for_side(mission.player_side));
    let tactics = entry.mission.as_ref()
        .map(|mission| progress.tactics_for_side(mission.player_side));
    let mut authored = entry.mission.as_ref()
        .map(|mission| progress.authored_roster_for_side(mission.player_side));
    let lost = entry.mission.as_ref()
        .filter(|mission| mission.persist_fleet_losses)
        .map(|mission| progress.lost_player_fleet_ids(mission.player_side))
        .transpose()?;
    if let Some(purchased) = purchased.as_mut() {
        // Reserve hulls always stay in the career ledger, never in the
        // physical Level. Permanent casualties are excluded only when
        // the authored mission enables their persistence, exactly as in
        // the native fleet preflight.
        purchased.retain(|ship| ship.saved_squad_id > 0 &&
            lost.as_ref().is_none_or(|dead| !dead.contains(&ship.fleet_ship_id)));
    }
    if let (Some(authored), Some(lost)) = (authored.as_mut(), lost.as_ref()) {
        // A historical saved-squad transfer remains in the audit ledger
        // after its FleetShip dies. Do not attempt to move that dead
        // original hull before applying the canonical casualty filter.
        authored.retain(|(fleet_id, _, _)| !lost.contains(fleet_id));
    }
    // One winning mission can create new persistent player squads and
    // award hulls directly into those squads. Both use the existing
    // scene editor at the next Level, not a parallel gameplay roster.
    let grant_squads = entry.mission.as_ref()
        .filter(|mission| !progress.grants_claimed(&mission.id))
        .map(|mission| mission.victory_squads.iter().map(|award|
            NativeCreatedSquad {
                saved_squad_id: award.saved_squad_id,
                template_saved_squad_id: award.template_saved_squad_id,
                side: mission.player_side,
            }).collect::<Vec<_>>()
        ).unwrap_or_default();
    // Check one complete reward batch against every eligible native
    // mission before mutating progress or opening the physical battle.
    let grants = entry.mission.as_ref()
        .filter(|mission| !progress.grants_claimed(&mission.id) &&
            !mission.victory_grants.is_empty())
        .map(|mission| plan_native_victory_grants(
            catalog, catalog_root, &progress, mission, &grant_squads,
        )).transpose()?.unwrap_or_default();
    if !grant_squads.is_empty() && grants.is_empty() {
        preflight_native_fleet_edit_with_squads(
            catalog, catalog_root, &progress, entry.mission.as_ref()
                .expect("awarded squads require a campaign").player_side,
            &progress.purchases_for_side(entry.mission.as_ref()
                .expect("awarded squads require a campaign").player_side),
            &progress.authored_roster_for_side(entry.mission.as_ref()
                .expect("awarded squads require a campaign").player_side),
            0, &grant_squads,
        )?;
    }
    let mission = catalog.campaign_id.as_deref().zip(entry.mission.as_ref())
        .map(|(campaign_id, mission)| CampaignMission {
            campaign_id, mission_id: &mission.id, player_side: mission.player_side,
            record_fleet_stats: mission.record_fleet_stats,
            bank_player_minerals: mission.bank_player_minerals,
            lost_fleet_ids: lost.as_ref(),
            purchased_ships: purchased.as_deref(),
            created_squads: created.as_deref(),
            tactics: tactics.as_deref(),
            authored_roster: authored.as_deref(),
            victory_grants: &grants,
            victory_squads: &grant_squads,
        });
    // The original career snapshot is already needed for replay. Reuse
    // that SAME frozen input projection for live campaign continuation,
    // rather than rebuilding purchases/grants from a changed save ledger.
    let (recoverable, save_setup) = if mission.is_some() {
        let run_config: RunConfig = serde_json::from_slice(&fs::read(&config)?)?;
        let replayable = run_config.navigation_workers.is_none() &&
            run_config.model_updates.is_empty();
        (run_config.host_recovery_checkpoint.is_some(),
         run_config.host_recovery_checkpoint.is_some() ||
            replayable && (interactive ||
                env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_some()))
    } else { (false, false) };
    let setup = if save_setup {
        let mut setup = CampaignReplaySetup::capture(
            &config, mission.expect("saved campaign setup has an authored mission"),
        )?;
        let status = catalog.status(&progress);
        setup.career_sha256 = Some(format!("{:x}", Sha256::digest(
            serde_json::to_vec(&status)?,
        )));
        Some(setup)
    } else { None };

    // Inspect checkpointed Worlds for this mission even if today's source
    // configuration stopped enabling checkpoint recovery. Otherwise a
    // changed project setting can bypass an unfinished original campaign
    // and allocate a second battle with the same persistent fleet grants.
    if let (Some(campaign_id), Some(authored_mission)) =
        (catalog.campaign_id.as_deref(), entry.mission.as_ref())
    {
        let mut original_run: Option<(PathBuf, CampaignReplaySetup)> = None;
        for entry in fs::read_dir(output_root)? {
            let entry = entry?;
            if !entry.file_type()?.is_dir() { continue; }
            let name = entry.file_name();
            let Some(number) = name.to_str()
                .and_then(|value| value.strip_prefix("battle-"))
                .filter(|value| !value.is_empty() &&
                    value.bytes().all(|ch| ch.is_ascii_digit()))
            else { continue };
            if number.parse::<u64>().is_err() { continue; }
            let root = entry.path();
            let run = root.join("run");
            let saved = root.join("campaign-replay-setup.json");
            let checkpoint = run.join("native-host-checkpoint.json");
            if !checkpoint.is_file() { continue; }
            if run.is_symlink() || checkpoint.is_symlink() ||
                saved.is_symlink() || !saved.is_file()
            {
                return Err(invalid(
                    "interrupted campaign World has no owned immutable start snapshot",
                ).into());
            }
            // First identify the mission using its immutable start
            // metadata, without opening the original source scene. That
            // scene may have been legitimately updated after the mission
            // already committed its final campaign result.
            let prior: CampaignReplaySetup = serde_json::from_slice(&fs::read(&saved)?)?;
            if prior.campaign_id != campaign_id ||
                prior.mission_id != authored_mission.id { continue; }
            // A completed mission belongs to its committed battle receipt.
            // Recover its unfinished replay footer without reopening the
            // source or reconsidering its one-time career rewards.
            if terminal_recording::complete_committed_recording(&run)? { continue; }
            // Only an interrupted, still-recoverable World requires its
            // exact original source, career and grant projection. Removing
            // the recovery flag from a new source cannot waive that owner.
            if !recoverable {
                return Err(invalid(
                    "unfinished campaign World requires its original checkpoint-enabled source configuration",
                ).into());
            }
            let prior = CampaignReplaySetup::load(&saved)?;
            if !setup.as_ref().expect("checkpointed campaign has a frozen start")
                .matches_recovery_start(&prior)?
            {
                return Err(invalid(
                    "interrupted campaign cannot resume after its source, saved career, or victory rewards changed",
                ).into());
            }
            if original_run.replace((run, prior)).is_some() {
                return Err(invalid(
                    "multiple interrupted campaigns claim the same native mission",
                ).into());
            }
        }
        if let Some((output, prior)) = original_run {
            println!("{}", json!({
                "kind": "native_campaign_battle_recovered",
                "campaign_id": campaign_id,
                "mission_id": authored_mission.id,
                "run": output,
            }));
            run_session(&prior.source_config, interactive, interactive,
                Some(output.clone()), None, None, Some(prior.recovery_mission()?))?;
            return Ok(output);
        }
    }
    // No existing original World was recoverable: allocate a fresh,
    // unique battle and persist its career inputs BEFORE gameplay begins.
    let output = loop {
        *next_number = next_number.checked_add(1)
            .ok_or_else(|| invalid("battle count exhausted"))?;
        let directory = output_root.join(format!("battle-{:04}", *next_number));
        match fs::create_dir(&directory) {
            Ok(()) => break directory.join("run"),
            Err(error) if error.kind() == ErrorKind::AlreadyExists => continue,
            Err(error) => return Err(error.into()),
        }
    };
    if let Some(start) = &quick_start {
        save_native_quick_battle_start(&output, start)?;
    }
    if let Some(setup) = setup {
        let path = output.parent().expect("created campaign battle directory")
            .join("campaign-replay-setup.json");
        let file = fs::OpenOptions::new().write(true).create_new(true).open(&path)?;
        serde_json::to_writer(&file, &setup)?;
        file.sync_all()?;
        #[cfg(unix)]
        fs::File::open(path.parent().expect("campaign battle parent"))?.sync_all()?;
    }
    run_session(&config, interactive, interactive, Some(output.clone()), None, None, mission)?;
    Ok(output)
}

/// Allocate one-time victory rewards from the SAME native scene prototypes,
/// fleet-ID authority and saved-squad cap as ordinary ship purchases.
/// Probe with reserved high FleetShip IDs; the probes never persist and
/// real IDs are allocated only above all authored and career identities.
fn plan_native_victory_grants(
    catalog: &battle_catalog::BattleCatalog, root: &Path,
    progress: &battle_catalog::CampaignProgress<'_>,
    mission: &battle_catalog::Mission,
    earned_squads: &[NativeCreatedSquad],
) -> Result<Vec<NativePurchasedShip>, Box<dyn Error>> {
    // Project the entire career roster. The preflight chooses casualties
    // per authored mission rather than inheriting this battle's loss mode.
    let mut projected = progress.purchases_for_side(mission.player_side);
    let mut grants = Vec::new();
    let reward_count: usize = mission.victory_grants.iter()
        .map(|grant| grant.count as usize).sum();
    for grant in &mission.victory_grants {
        let shop = catalog.buildable_ships.iter().find(|shop|
            shop.player_side == mission.player_side &&
            shop.ship_type == grant.ship_type
        ).ok_or_else(|| invalid("victory grant lacks a source-priced ship type"))?;
        for _ in 0..grant.count {
            let offset = i64::try_from(grants.len() + 1)
                .map_err(|_| invalid("victory reward count overflow"))?;
            let ship = NativePurchasedShip {
                fleet_ship_id: i64::MAX - offset,
                saved_squad_id: grant.saved_squad_id,
                ship_type: grant.ship_type,
                price_tsv: shop.price_tsv,
            };
            grants.push(ship);
            projected.push(ship);
        }
    }
    if grants.len() != reward_count {
        return Err(invalid("incomplete campaign victory ship allocation").into());
    }
    let highest_authored = preflight_native_fleet_edit_with_squads(
        catalog, root, progress, mission.player_side,
        &projected, &progress.authored_roster_for_side(mission.player_side),
        0, earned_squads,
    )?;
    let first_id = highest_authored.max(progress.highest_fleet_id())
        .checked_add(1).ok_or_else(|| invalid("victory FleetShip identities exhausted"))?;
    for (index, grant) in grants.iter_mut().enumerate() {
        grant.fleet_ship_id = first_id.checked_add(index as i64)
            .ok_or_else(|| invalid("victory FleetShip identities exhausted"))?;
    }
    Ok(grants)
}

/// Verify that every authored route for the player's campaign can
/// actually instantiate the purchased class and SavedSquad. The ship's
/// source MaxTSV is its authoritative Unity purchase price. No invented
/// cost table, type collider or silent missing-route purchase is allowed.
fn preflight_native_ship_purchase(
    catalog: &battle_catalog::BattleCatalog, root: &Path,
    progress: &battle_catalog::CampaignProgress<'_>,
    side: i32, ship_type: u8, saved_squad_id: i64, price_tsv: u64,
) -> Result<i64, Box<dyn Error>> {
    let mut projected = progress.purchases_for_side(side);
    projected.push(NativePurchasedShip {
        // Probe with a fleet identity outside any authored/native account
        // range. This preview is discarded before an atomic purchase commit.
        fleet_ship_id: i64::MAX, saved_squad_id, ship_type, price_tsv,
    });
    preflight_native_fleet_edit(catalog, root, progress, side, &projected,
        &progress.authored_roster_for_side(side), saved_squad_id)
}

/// This is the same source-scene preflight for both ship construction
/// and between-mission squad reassignment. It does not create a separate
/// set of combat/formation/policy rules.
/// Read precisely the same authored Stage and native layout for
/// campaign fleet editing that run_battle loads for gameplay. Shared by
/// full fleet preflight and the read-only squad picker.
fn load_native_fleet_edit_scene(run_path: &Path) -> Result<NativePhysicalScene, Box<dyn Error>> {
    let run: RunConfig = serde_json::from_slice(&fs::read(&run_path)?)?;
    if run.levels.len() != 1 || run.episodes_per_world != 1 {
        return Err(invalid("native shop requires one physical episode per campaign Level").into());
    }
    let level = &run.levels[0];
    let bounds = &run.fragment_spawn.map_bounds;
    let fragments = FragmentSpawnSettings {
        map_bounds: Aabb {
            min: vec2(bounds.min), max: vec2(bounds.max),
        },
        half_map_extents: vec2(run.fragment_spawn.half_map_extents),
        asteroid_max_speed_exclusive:
            run.fragment_spawn.asteroid_max_speed_exclusive,
        training_health_ratio: run.fragment_spawn.training_health_ratio,
    };
    if !fragments.valid() {
        return Err(invalid("invalid native purchased Level fragmentation settings").into());
    }
    let config_root = run_path.parent().ok_or_else(||
        invalid("missing native shop run directory"))?;
    let assets = match (
        run.native_stage.as_ref(),
        run.collision_matrix.as_ref(),
        run.stage_palette.as_ref(),
    ) {
        (Some(native), None, None) => NativeSceneAssets::from_native_stage(
            native.collision_matrix_rows,
            &native.asteroid_prefab_numbers,
            &run.stage_name, fragments,
        ),
        (None, Some(matrix), Some(palette)) => NativeSceneAssets::load(
            &resolve(config_root, matrix), &resolve(config_root, palette),
            &run.stage_name, fragments,
        ),
        _ => return Err(invalid(
            "shop Level needs the same source Stage assets as ordinary native gameplay",
        ).into()),
    }.map_err(|error| contextual("shop Stage assets", error))?;
    let scene_path = resolve(config_root, &level.scene).canonicalize()?;
    let scene_json = fs::read_to_string(&scene_path)?;
    let mut source = NativePhysicalScene::parse_scene_with_assets(
        &scene_json, &assets,
    ).map_err(|error| contextual("shop authored Level", error))?;
    if let Some(layout) = &level.native_layout {
        source.apply_native_layout(
            layout, assets.box_catalog(), assets.polygon_catalog(),
        ).map_err(|error| contextual("shop native Level layout", error))?;
    }

    Ok(source)
}

fn preflight_native_fleet_edit(
    catalog: &battle_catalog::BattleCatalog, root: &Path,
    progress: &battle_catalog::CampaignProgress<'_>, side: i32,
    projected: &[NativePurchasedShip],
    authored_roster: &[(i64, i64, i64)], target_saved_squad_id: i64,
) -> Result<i64, Box<dyn Error>> {
    preflight_native_fleet_edit_with_squads(
        catalog, root, progress, side, projected, authored_roster,
        target_saved_squad_id, &[],
    )
}

fn preflight_native_fleet_edit_with_squads(
    catalog: &battle_catalog::BattleCatalog, root: &Path,
    progress: &battle_catalog::CampaignProgress<'_>, side: i32,
    projected: &[NativePurchasedShip],
    authored_roster: &[(i64, i64, i64)], target_saved_squad_id: i64,
    new_squads: &[NativeCreatedSquad],
) -> Result<i64, Box<dyn Error>> {
    let max_size = catalog.max_squad_ships.ok_or_else(||
        invalid("native shop needs the source's maximum squad size"))? as usize;
    let dead = progress.lost_player_fleet_ids(side)?;
    let no_casualties = HashSet::new();
    let active = projected.iter().copied()
        .filter(|ship| ship.saved_squad_id > 0).collect::<Vec<_>>();
    let surviving_purchases = active.iter().copied()
        .filter(|ship| !dead.contains(&ship.fleet_ship_id))
        .collect::<Vec<_>>();
    let surviving_authored = authored_roster.iter().copied()
        .filter(|(fleet_id, _, _)| !dead.contains(fleet_id))
        .collect::<Vec<_>>();
    let mut highest_fleet_id = 0_i64;
    let mut checked = 0_u64;
    // Completed missions remain replayable with the current career fleet.
    // Preflight every authored configuration, not only unfinished missions;
    // otherwise a purchase or victory reward could make an older Stage
    // unloadable despite having passed its original account transaction.
    for entry in &catalog.battles {
        let Some(mission) = entry.mission.as_ref().filter(|mission|
            mission.player_side == side) else { continue };
        // Mirror launch_catalog_battle: a mission without persistent
        // fleet losses deploys the entire career roster, including hulls
        // lost in other missions. All scene variants share this contract.
        let deployed = if mission.persist_fleet_losses {
            surviving_purchases.as_slice()
        } else { active.as_slice() };
        let roster = if mission.persist_fleet_losses {
            surviving_authored.as_slice()
        } else { authored_roster };
        let casualties = if mission.persist_fleet_losses {
            &dead
        } else { &no_casualties };
        for config in entry.configurations() {
            let run_path = resolve(root, config).canonicalize()?;
            let mut source = load_native_fleet_edit_scene(&run_path)?;
            // Purchase and victory-grant FleetShip IDs remain unique across
            // replayable completed missions and alternate victory routes.
            for entity in &source.entities {
                if let NativeAuthoredEntity::Ship(ship) = entity {
                    if let Some(id) = ship.fleet_ship_id {
                        highest_fleet_id = highest_fleet_id.max(id);
                    }
                }
            }
            // The authoritative scene installer checks both SavedSquad
            // identity collisions and actual source template availability.
            let mut projected_squads = progress.created_squads_for_side(side);
            projected_squads.extend_from_slice(new_squads);
            source.install_created_squads(
                side, &projected_squads,
            ).map_err(|error| contextual("shop created SavedSquads", error))?;
            source.apply_saved_squad_tactics(side, &progress.tactics_for_side(side))
                .map_err(|error| contextual("shop saved squad tactics", error))?;
            source.apply_authored_fleet_roster(side, roster)
                .map_err(|error| contextual("shop original FleetShip reassignment", error))?;
            source.install_purchased_ships(side, deployed, casualties)
                .map_err(|error| contextual("shop purchased FleetShip placement", error))?;
            source.omit_killed_fleet_ships(side, casualties)
                .map_err(|error| contextual("shop saved-fleet casualties", error))?;
            source.apply_saved_squad_matching_speeds(
                side, &progress.tactics_for_side(side),
            ).map_err(|error| contextual("shop saved matching speed", error))?;
            if target_saved_squad_id > 0 {
                let squad = source.source_squads.iter().find(|squad|
                    squad.saved_squad_id == Some(target_saved_squad_id) &&
                    squad.side == side && squad.player_permissions.user_controlled
                ).ok_or_else(|| invalid("target saved squad is missing"))?;
                if squad.members.len() > max_size {
                    return Err(invalid(
                        "purchased hull exceeds the source's maximum saved-squad size",
                    ).into());
                }
            } else if source.source_squads.iter().any(|squad|
                squad.side == side && squad.player_permissions.user_controlled &&
                squad.members.len() > max_size
            ) {
                return Err(invalid(
                    "awarded fleet exceeds the source's maximum saved-squad size",
                ).into());
            }
            checked += 1;
        }
    }
    if checked == 0 {
        return Err(invalid("no native campaign Levels can deploy the purchased hull").into());
    }
    Ok(highest_fleet_id)
}

fn run_build_ship(
    catalog_path: &Path, output_root: &Path, player_side: i32,
    ship_type: u8, saved_squad_id: i64,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    let _writer = battle_catalog::CampaignWriterLease::acquire(output_root)?;
    let progress = catalog.load_progress(output_root)?;
    let shop = catalog.buildable_ships.iter().find(|shop|
        shop.player_side == player_side && shop.ship_type == ship_type &&
        shop.purchasable
    ).ok_or_else(|| invalid("requested ship type is not purchasable in the player's authored shop"))?;
    if !progress.bank_history_complete() {
        return Err(invalid("cannot buy ships with incomplete historical campaign income").into());
    }
    if !progress.is_ship_unlocked(shop) {
        return Err(invalid("this ship class is not yet unlocked by campaign progression").into());
    }
    if progress.unspent_minerals()? < shop.price_tsv {
        return Err(invalid(format!(
            "insufficient mined TSV: available {}, ship costs {}",
            progress.unspent_minerals()?, shop.price_tsv,
        )).into());
    }
    let root = catalog_path.parent().ok_or_else(||
        invalid("missing shop catalog parent"))?;
    let highest_authored = preflight_native_ship_purchase(
        &catalog, root, &progress,
        player_side, ship_type, saved_squad_id, shop.price_tsv,
    )?;
    let new_fleet_id = highest_authored.max(progress.highest_fleet_id())
        .checked_add(1).ok_or_else(|| invalid("native purchase FleetShip IDs exhausted"))?;
    let purchased = catalog.buy_ship(
        &progress, output_root, player_side, ship_type, saved_squad_id, new_fleet_id,
    )?;
    println!("{}", json!({
        "kind": "native_campaign_ship_purchased",
        "campaign_id": catalog.campaign_id,
        "player_side": player_side,
        "fleet_ship_id": purchased.fleet_ship_id,
        "saved_squad_id": purchased.saved_squad_id,
        "ship_type": purchased.ship_type,
        "cost_tsv": purchased.price_tsv,
        "remaining_mined_tsv": progress.unspent_minerals()? - purchased.price_tsv,
    }));
    Ok(())
}

fn run_transfer_ship(
    catalog_path: &Path, output_root: &Path,
    fleet_ship_id: i64, destination_squad_id: i64,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    let _writer = battle_catalog::CampaignWriterLease::acquire(output_root)?;
    let progress = catalog.load_progress(output_root)?;
    let (side, ship) = progress.purchased_ship(fleet_ship_id)
        .ok_or_else(|| invalid("only purchased FleetShips can be reassigned"))?;
    if destination_squad_id == ship.saved_squad_id || destination_squad_id < 0 {
        return Err(invalid("destination must be the reserve or another owned SavedSquad").into());
    }
    // The account's career rows exclude authored SavedSquads which have
    // not deployed a ship yet. Physical scene preflight below is the
    // authoritative ownership and destination-capacity check for both
    // those squads and previously used saved squads.
    let dead = progress.lost_player_fleet_ids(side)?;
    if dead.contains(&fleet_ship_id) {
        return Err(invalid("a lost FleetShip cannot be moved to another squad").into());
    }
    let mut projected = progress.purchases_for_side(side);
    let owned = projected.iter_mut().find(|ship| ship.fleet_ship_id == fleet_ship_id)
        .ok_or_else(|| invalid("the purchased FleetShip is not available"))?;
    owned.saved_squad_id = destination_squad_id;
    let root = catalog_path.parent().ok_or_else(||
        invalid("missing native campaign parent"))?;
    preflight_native_fleet_edit(
        &catalog, root, &progress, side, &projected,
        &progress.authored_roster_for_side(side), destination_squad_id,
    )?;
    let moved = catalog.transfer_purchased_ship(
        &progress, output_root, fleet_ship_id, destination_squad_id,
    )?;
    println!("{}", json!({
        "kind": "native_campaign_fleet_transferred",
        "campaign_id": catalog.campaign_id,
        "fleet_ship_id": fleet_ship_id,
        "player_side": side,
        "from_saved_squad_id": ship.saved_squad_id,
        "to_saved_squad_id": moved.saved_squad_id,
        "ship_type": ship.ship_type,
        "cost_tsv": 0,
    }));
    Ok(())
}

fn run_reassign_authored_ship(
    catalog_path: &Path, output_root: &Path, side: i32,
    fleet_ship_id: i64, from_squad: i64, to_squad: i64,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    let _writer = battle_catalog::CampaignWriterLease::acquire(output_root)?;
    let progress = catalog.load_progress(output_root)?;
    if progress.purchased_ship(fleet_ship_id).is_some() {
        return Err(invalid("use bees transfer for purchased FleetShips").into());
    }
    if from_squad == to_squad || from_squad < 0 || to_squad < 0 ||
        progress.lost_player_fleet_ids(side)?.contains(&fleet_ship_id)
    {
        return Err(invalid("original FleetShip must be a living hull moving to a different assignment").into());
    }
    if progress.authored_current_squad(fleet_ship_id)
        .is_some_and(|current| current != from_squad)
    {
        return Err(invalid("original FleetShip ownership has changed since the requested move").into());
    }
    let root = catalog_path.parent().ok_or_else(||
        invalid("missing campaign catalog directory"))?;
    if progress.authored_current_squad(fleet_ship_id).is_none() {
        // The first edit establishes a durable provenance in the campaign
        // ledger. Verify it against the currently selected authored scene;
        // after that, FleetShip ID and the saved destination govern every
        // route variant, even when its initial source squad differs.
        let has_upcoming = catalog.battles.iter().filter_map(|battle|
            battle.mission.as_ref()).any(|mission|
                mission.player_side == side && !progress.completed(&mission.id));
        let mut source_proven = false;
        for battle in &catalog.battles {
            let Some(mission) = battle.mission.as_ref().filter(|mission|
                mission.player_side == side &&
                (!has_upcoming || !progress.completed(&mission.id))
            ) else { continue };
            let scene = load_native_fleet_edit_scene(
                &resolve(root, battle.config_for(&progress)))?;
            let Some(parent) = scene.entities.iter().find_map(|entity| match entity {
                NativeAuthoredEntity::Ship(ship) if ship.side == mission.player_side &&
                    ship.fleet_ship_id == Some(fleet_ship_id) => Some(ship.entity_id),
                _ => None,
            }) else { continue };
            if scene.source_squads.iter().any(|squad|
                squad.side == side && squad.saved_squad_id == Some(from_squad) &&
                squad.player_permissions.user_controlled &&
                squad.members.contains(&parent))
            {
                source_proven = true;
                break;
            }
        }
        if !source_proven {
            return Err(invalid("original FleetShip source squad differs from every active authored mission assignment").into());
        }
    }
    let mut projected = progress.authored_roster_for_side(side);
    if let Some(row) = projected.iter_mut().find(|row| row.0 == fleet_ship_id) {
        row.2 = to_squad;
    } else {
        if from_squad == 0 {
            return Err(invalid("original hull's first edit must identify its original SavedSquad").into());
        }
        projected.push((fleet_ship_id, from_squad, to_squad));
    }
    let purchased = progress.purchases_for_side(side);
    preflight_native_fleet_edit(
        &catalog, root, &progress, side, &purchased,
        &projected, to_squad,
    )?;
    catalog.reassign_authored_ship(
        &progress, output_root, side, fleet_ship_id, from_squad, to_squad,
    )?;
    println!("{}", json!({
        "kind": "native_campaign_original_ship_reassigned",
        "campaign_id": catalog.campaign_id,
        "player_side": side,
        "fleet_ship_id": fleet_ship_id,
        "from_saved_squad_id": from_squad,
        "to_saved_squad_id": to_squad,
        "cost_tsv": 0,
    }));
    Ok(())
}

fn run_create_saved_squad(
    catalog_path: &Path, output_root: &Path,
    side: i32, template_id: i64,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    let _writer = battle_catalog::CampaignWriterLease::acquire(output_root)?;
    let progress = catalog.load_progress(output_root)?;
    if !matches!(side, 1 | 2) || template_id <= 0 {
        return Err(invalid("new squad requires a valid player side and saved template ID").into());
    }
    let root = catalog_path.parent()
        .ok_or_else(|| invalid("missing native campaign root"))?;
    let mut highest_saved_id = progress.highest_saved_squad_id()
        .max(catalog.reserved_saved_squad_id_ceiling());
    let mut sources = Vec::new();
    // A new squad must be usable with the same authenticated player
    // settings on every authored mission variant, not just the first
    // currently unlocked battle. Stage squad ItemIds are per-Level.
    for entry in &catalog.battles {
        if !entry.mission.as_ref()
            .is_some_and(|mission| mission.player_side == side) {
            continue;
        }
        for config in entry.configurations() {
            let run_path = resolve(root, config).canonicalize()?;
            let source = load_native_fleet_edit_scene(&run_path)?;
            for squad in &source.source_squads {
                if let Some(id) = squad.saved_squad_id {
                    highest_saved_id = highest_saved_id.max(id);
                }
            }
            sources.push(source);
        }
    }
    if sources.is_empty() {
        return Err(invalid("new squad requires a native-authored player campaign").into());
    }
    let new_id = highest_saved_id.checked_add(1)
        .ok_or_else(|| invalid("persistent SavedSquad ID space exhausted"))?;
    let created = NativeCreatedSquad {
        side, saved_squad_id: new_id, template_saved_squad_id: template_id,
    };
    let mut projected = progress.created_squads_for_side(side);
    projected.push(created);
    for mut scene in sources {
        scene.install_created_squads(side, &projected)
            .map_err(|error| contextual("new native SavedSquad preflight", error))?;
    }
    let committed = catalog.create_saved_squad(
        &progress, output_root, side, template_id, new_id,
    )?;
    println!("{}", json!({
        "kind": "native_campaign_saved_squad_created",
        "campaign_id": catalog.campaign_id,
        "player_side": side,
        "saved_squad_id": committed.saved_squad_id,
        "template_saved_squad_id": committed.template_saved_squad_id,
        "ships_deployed": 0,
        "cost_tsv": 0,
    }));
    Ok(())
}

/// Accept all user RGB colors (rather than constraining persisted fleets to
/// a renderer/UI preset). `inherit` restores each mission's source color;
/// `clear` explicitly disables sprite recoloring.
fn parse_squad_color_setting(value: &str) -> io::Result<NativeSquadColorSetting> {
    match value {
        "inherit" => return Ok(NativeSquadColorSetting::Inherit),
        "clear" => return Ok(NativeSquadColorSetting::Clear),
        _ => (),
    }
    let hex = value.strip_prefix('#').unwrap_or(value);
    if hex.len() != 6 || !hex.bytes().all(|b| b.is_ascii_hexdigit()) {
        return Err(invalid("squad color must be inherit, clear or six hexadecimal RGB digits"));
    }
    let channels = [0, 2, 4].map(|start|
        u8::from_str_radix(&hex[start..start + 2], 16)
            .expect("prevalidated hexadecimal RGB value")
    );
    Ok(NativeSquadColorSetting::Custom(channels))
}

fn run_set_saved_squad_tactics(
    catalog_path: &Path, output_root: &Path, entry: NativeSavedSquadTactics,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    let _writer = battle_catalog::CampaignWriterLease::acquire(output_root)?;
    let progress = catalog.load_progress(output_root)?;
    let mut entry = entry;
    // Old CLI invocations and historical receipts do not contain this
    // option. Preserve the last explicit preference rather than clearing
    // it whenever the user changes a shooting or chase setting.
    if entry.match_speed.is_none() {
        entry.match_speed = progress.tactics_for_squad(entry.side, entry.saved_squad_id)
            .and_then(|saved| saved.match_speed);
    }
    if entry.color_setting.is_none() {
        entry.color_setting = progress.tactics_for_squad(entry.side, entry.saved_squad_id)
            .and_then(|saved| saved.color_setting);
    }
    let root = catalog_path.parent().ok_or_else(|| invalid("missing campaign directory"))?;
    // Qualify the entire authored campaign, including its alternate
    // victory route and newly created vacant squads, before publishing.
    let mut effective = progress.tactics_for_side(entry.side);
    effective.retain(|tactic| tactic.saved_squad_id != entry.saved_squad_id);
    effective.push(entry);
    let mut checked = 0usize;
    let created = progress.created_squads_for_side(entry.side);
    let purchases = progress.purchases_for_side(entry.side);
    let authored = progress.authored_roster_for_side(entry.side);
    for battle in &catalog.battles {
        let Some(mission) = battle.mission.as_ref().filter(|mission|
            mission.player_side == entry.side) else { continue };
        let lost = if mission.persist_fleet_losses {
            progress.lost_player_fleet_ids(entry.side)?
        } else { HashSet::new() };
        let deployed = purchases.iter().copied()
            .filter(|ship| !lost.contains(&ship.fleet_ship_id) &&
                ship.saved_squad_id > 0).collect::<Vec<_>>();
        let surviving_authored = authored.iter().copied()
            .filter(|(id, _, _)| !lost.contains(id)).collect::<Vec<_>>();
        for config in battle.configurations() {
            let scene_path = resolve(root, config).canonicalize()?;
            let mut scene = load_native_fleet_edit_scene(&scene_path)?;
            // Use the exact order of run_battle: a changed SavedSquad
            // preference must be valid for the final route-specific fleet,
            // including transferred hulls, purchases and prior casualties.
            scene.install_created_squads(entry.side, &created)
                .map_err(|error| contextual("tactics created squad preflight", error))?;
            scene.apply_saved_squad_tactics(entry.side, &effective)
                .map_err(|error| contextual("tactics native scene preflight", error))?;
            scene.apply_authored_fleet_roster(entry.side, &surviving_authored)
                .map_err(|error| contextual("tactics authored fleet preflight", error))?;
            scene.install_purchased_ships(entry.side, &deployed, &lost)
                .map_err(|error| contextual("tactics purchased fleet preflight", error))?;
            scene.omit_killed_fleet_ships(entry.side, &lost)
                .map_err(|error| contextual("tactics saved casualties preflight", error))?;
            scene.apply_saved_squad_matching_speeds(entry.side, &effective)
                .map_err(|error| contextual("tactics matching-speed preflight", error))?;
            checked += 1;
        }
    }
    if checked == 0 {
        return Err(invalid("saved tactics require at least one authored player mission").into());
    }
    catalog.set_saved_squad_tactics(&progress, output_root, entry)?;
    println!("{}", json!({
        "kind": "native_campaign_saved_squad_tactics_updated",
        "campaign_id": catalog.campaign_id,
        "side": entry.side,
        "saved_squad_id": entry.saved_squad_id,
        "shooting_strategy_id": entry.shooting_strategy_id,
        "shooting_strategy": bees_hivemind::protocol::SHOOTING_STRATEGIES[
            usize::from(entry.shooting_strategy_id - 1)
        ],
        "should_chase": entry.should_chase,
        "cease_fire": entry.cease_fire,
        "match_speed": entry.match_speed,
        "color_setting": entry.color_setting,
        "validated_configs": checked,
    }));
    Ok(())
}

fn run_all_campaign_missions(
    catalog_path: &Path, output_root: &Path,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    if catalog.campaign_id.is_none() {
        return Err(invalid("campaign batch requires a campaign catalog").into());
    }
    let root = catalog_path.parent().ok_or_else(|| invalid("missing catalog directory"))?;
    fs::create_dir_all(output_root)?;
    let started = Instant::now();
    let mut number = 0_u64;
    let mut played = 0_u64;
    let mut world_steps = 0_u64;
    let mut episode_count = 0_u64;
    let mut completed = Vec::new();
    // The original catalog defines mission order, dependencies and route
    // selection. Keep that one source of truth; never simulate or advance
    // a campaign through an alternate training-only state machine.
    for entry in &catalog.battles {
        let Some(mission) = &entry.mission else { continue };
        let progress = catalog.load_progress(output_root)?;
        if progress.completed(&mission.id) { continue; }
        if !mission.requires.iter().all(|id| progress.completed(id)) {
            return Err(invalid(format!(
                "campaign batch cannot unlock mission {}: an earlier prerequisite is incomplete",
                mission.id,
            )).into());
        }
        let run = launch_catalog_battle(
            &catalog, entry, root, output_root, &mut number, false,
        )?;
        let summary: Value = serde_json::from_slice(
            &fs::read(run.join("rollout-summary.json"))?,
        )?;
        let steps = summary["throughput"]["successful_world_steps"].as_u64()
            .ok_or_else(|| invalid("completed campaign has no measured world steps"))?;
        let episodes = summary["completed_episodes"].as_u64()
            .ok_or_else(|| invalid("completed campaign has no episode receipt"))?;
        world_steps = world_steps.checked_add(steps)
            .ok_or_else(|| invalid("campaign total steps overflow"))?;
        episode_count = episode_count.checked_add(episodes)
            .ok_or_else(|| invalid("campaign episode count overflow"))?;
        played += 1;
        let latest = catalog.load_progress(output_root)?;
        let advanced = latest.completed(&mission.id);
        print_campaign_batch_progress(&mission.id, advanced, steps, episodes, &run);
        if !advanced {
            println!("{}", json!({
                "kind": "native_campaign_batch_stalled",
                "mission_id": mission.id,
                "played_missions": played,
                "successful_world_steps": world_steps,
                "completed_episodes": episode_count,
                "wall_seconds": started.elapsed().as_secs_f64(),
            }));
            return Err(invalid("native campaign mission did not meet its authored advancement condition").into());
        }
        completed.push(mission.id.as_str());
    }
    let seconds = started.elapsed().as_secs_f64();
    println!("{}", json!({
        "kind": "native_campaign_batch_complete",
        "campaign_id": catalog.campaign_id,
        "newly_completed_missions": completed,
        "played_missions": played,
        "successful_world_steps": world_steps,
        "completed_episodes": episode_count,
        "wall_seconds": seconds,
        "world_steps_per_wall_second": (seconds > 0.0)
            .then_some(world_steps as f64 / seconds),
    }));
    Ok(())
}

fn print_campaign_batch_progress(
    mission_id: &str, completed: bool, world_steps: u64, episodes: u64,
    run: &Path,
) {
    println!("{}", json!({
        "kind": "native_campaign_batch_mission",
        "mission_id": mission_id,
        "advanced": completed,
        "successful_world_steps": world_steps,
        "completed_episodes": episodes,
        "run": run,
    }));
}

fn run_campaign_mission(
    catalog_path: &Path, output_root: &Path, mission_id: &str, serve: bool,
) -> Result<(), Box<dyn Error>> {
    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog =
        serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    if catalog.campaign_id.is_none() {
        return Err(invalid("headless campaign launch needs a campaign catalog").into());
    }
    let root = catalog_path.parent().ok_or_else(|| invalid("missing catalog directory"))?;
    fs::create_dir_all(output_root)?;
    let entry = catalog.battles.iter().find(|entry| entry.mission.as_ref()
        .is_some_and(|mission| mission.id == mission_id))
        .ok_or_else(|| invalid("unknown campaign mission ID"))?;
    // Launch performs the only unlock check after acquiring the career
    // writer lease. No unlocked-state snapshot from before that lease may
    // reject a newly unlocked mission or select stale fleet/source routes.
    if serve && env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_none() {
        return Err(invalid(
            "campaign --serve requires BEES_NATIVE_REMOTE_LISTEN and authentication tokens",
        ).into());
    }
    // The selected Level and episode/model requirements are checked under
    // the career writer lease by launch_catalog_battle, not against this
    // unlocked preflight's possibly stale campaign progression.

    let mut number = 0_u64;
    launch_catalog_battle(&catalog, entry, root,
        output_root, &mut number, false).map(|_| ())
}

/// Offer original editable FleetShips from the selected upcoming routes,
/// but collect purchase, transfer, and squad-creation destinations from
/// EVERY replayable authored route. A campaign edit is checked against all
/// configurations, so the picker must not advertise a route-only squad.
/// Invalid legacy scenes still leave the ordinary battle menu accessible;
/// they contribute no unverified fleet-edit destinations.
#[cfg(feature = "client")]
fn authored_menu_fleet(
    catalog: &battle_catalog::BattleCatalog, root: &Path,
    progress: &battle_catalog::CampaignProgress<'_>,
) -> (Vec<(i32, i64, i64)>, Vec<(i32, i64)>, Vec<(i32, i64)>, Vec<(i32, i64)>) {
    let mut listed = Vec::new();
    let mut seen_fleet = HashSet::new();
    let mut common_destinations = HashMap::<i32, HashSet<i64>>::new();
    let mut common_templates = HashMap::<i32, HashSet<i64>>::new();
    let mut common_tactics = HashMap::<i32, HashSet<i64>>::new();
    let upcoming_sides = catalog.battles.iter().filter_map(|entry|
        entry.mission.as_ref().filter(|mission|
            !progress.completed(&mission.id)).map(|mission| mission.player_side))
        .collect::<HashSet<_>>();
    for entry in &catalog.battles {
        let Some(mission) = entry.mission.as_ref() else { continue };
        let side = mission.player_side;
        let selected = entry.config_for(progress);
        let active = !upcoming_sides.contains(&side) || !progress.completed(&mission.id);
        let created = progress.created_squads_for_side(side);
        for config in entry.configurations() {
            let mut destinations = HashSet::new();
            let mut templates = HashSet::new();
            let mut tactics = HashSet::new();
            // Keep this read-only probe on the same source scene and
            // installer used by campaign preflight and actual gameplay.
            if let Ok(path) = resolve(root, config).canonicalize() {
                if let Ok(mut scene) = load_native_fleet_edit_scene(&path) {
                    if scene.install_created_squads(side, &created).is_ok() {
                        for squad in &scene.source_squads {
                            let Some(saved_id) = squad.saved_squad_id else { continue };
                            if squad.side != side ||
                                !squad.player_permissions.user_controlled
                            { continue; }
                            // Empty authored and user-created squads are
                            // physical destinations even before a battle
                            // contributes a career squad record.
                            destinations.insert(saved_id);
                            if squad.hivemind.is_none() {
                                templates.insert(saved_id);
                            }
                            if !squad.hivemind.as_ref()
                                .is_some_and(|hivemind| hivemind.hivemind_controlled)
                            {
                                tactics.insert(saved_id);
                            }
                            if !active || config != selected { continue; }
                            for &entity_id in &squad.members {
                                let Some(ship) = scene.entities.iter().find_map(|entity| match entity {
                                    NativeAuthoredEntity::Ship(ship) if ship.entity_id == entity_id =>
                                        Some(ship),
                                    _ => None,
                                }) else { continue };
                                let Some(fleet_id) = ship.fleet_ship_id else { continue };
                                if progress.original_fleet_is_editable(side, fleet_id) &&
                                    scene.can_reassign_authored_ship(side, entity_id) &&
                                    seen_fleet.insert((side, fleet_id))
                                {
                                    listed.push((side, fleet_id, saved_id));
                                }
                            }
                        }
                    }
                }
            }
            // Intersection, not union: edits are durable across completed
            // missions and both possible on-victory physical layouts.
            common_destinations.entry(side)
                .and_modify(|ids| ids.retain(|id| destinations.contains(id)))
                .or_insert(destinations);
            common_templates.entry(side)
                .and_modify(|ids| ids.retain(|id| templates.contains(id)))
                .or_insert(templates);
            common_tactics.entry(side)
                .and_modify(|ids| ids.retain(|id| tactics.contains(id)))
                .or_insert(tactics);
        }
    }
    listed.sort_unstable();
    let mut destinations = common_destinations.into_iter()
        .flat_map(|(side, ids)| ids.into_iter().map(move |id| (side, id)))
        .collect::<Vec<_>>();
    destinations.sort_unstable();
    let mut templates = common_templates.into_iter()
        .flat_map(|(side, ids)| ids.into_iter().map(move |id| (side, id)))
        .collect::<Vec<_>>();
    templates.sort_unstable();
    let mut tactics = common_tactics.into_iter()
        .flat_map(|(side, ids)| ids.into_iter().map(move |id| (side, id)))
        .collect::<Vec<_>>();
    tactics.sort_unstable();
    (listed, destinations, templates, tactics)
}

#[cfg(feature = "client")]
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeLibrary {
    library_schema: u32,
    games: Vec<NativeLibraryGame>,
}

#[cfg(feature = "client")]
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeLibraryGame {
    id: String,
    title: String,
    kind: String,
    config: PathBuf,
}

/// Local player settings contain only the server endpoint and a path to a
/// separately protected token file; no credentials belong to the shared
/// package or library JSON.
#[cfg(feature = "client")]
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeSavedNetwork {
    address: String,
    side: i32,
    token_file: PathBuf,
}

#[cfg(feature = "client")]
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct NativeSavedHost {
    game_id: String,
    listen: String,
    tokens_file: PathBuf,
}

#[cfg(feature = "client")]
fn new_library_battle_output(save_root: &Path, game_id: &str)
    -> Result<PathBuf, Box<dyn Error>> {
    let root=save_root.join("battles").join(game_id);
    fs::create_dir_all(&root)?;
    let mut number=0_u64;
    loop {
        number=number.checked_add(1)
            .ok_or_else(|| invalid("quick battle count exhausted"))?;
        let dir=root.join(format!("battle-{number:06}"));
        match fs::create_dir(&dir) {
            Ok(())=>return Ok(dir.join("run")),
            Err(error) if error.kind()==ErrorKind::AlreadyExists=>continue,
            Err(error)=>return Err(error.into()),
        }
    }
}

/// The library and LAN host both pick a checkpointed quick battle under
/// the same exclusive per-game save owner. A new output remains create-only.
#[cfg(feature = "client")]
fn select_library_quick_battle_output(
    save_root: &Path, game_id: &str, config: &Path, remote_host: bool,
) -> Result<PathBuf, Box<dyn Error>> {
    if let Some(start) = QuickBattleStart::capture(config, remote_host)? {
        let root = save_root.join("battles").join(game_id);
        if let Some(output) = recover_native_quick_battle(&root, &start)? {
            println!("{}", json!({
                "kind": "native_quick_battle_recovered",
                "source": start.source_config,
                "run": output,
            }));
            return Ok(output);
        }
        let output = new_library_battle_output(save_root, game_id)?;
        save_native_quick_battle_start(&output, &start)?;
        Ok(output)
    } else {
        new_library_battle_output(save_root, game_id)
    }
}

#[cfg(feature = "client")]
fn run_library_quick_battle(
    save_root: &Path, game_id: &str, config: &Path,
) -> Result<(), Box<dyn Error>> {
    let root = save_root.join("battles").join(game_id);
    // Non-checkpointed quick battles remain independent: they can launch
    // in parallel and keep their original replay-recording behavior.
    let _writer = if QuickBattleStart::capture(config, false)?.is_some() {
        Some(battle_catalog::CampaignWriterLease::acquire(&root)?)
    } else { None };
    let output = select_library_quick_battle_output(save_root, game_id, config, false)?;
    run_session(config, true, true, Some(output), None, None, None)
}

/// Generated fleet/policy matches cannot be recreated by a new menu
/// choice: that would generate different source ships, controller routes
/// and model identities. Resume only the archived run physically owned by
/// this same numbered battle and the matching local/LAN launch mode.
#[cfg(feature = "client")]
fn recover_generated_library_battle(
    save_root: &Path, game_id: &str, remote_host: bool,
) -> Result<Option<(PathBuf, PathBuf)>, Box<dyn Error>> {
    let directory = save_root.join("battles").join(game_id);
    let mut pending = None;
    for entry in fs::read_dir(&directory)? {
        let entry = entry?;
        if !entry.file_type()?.is_dir() { continue; }
        let name = entry.file_name();
        let Some(number) = name.to_str().and_then(|value|
            value.strip_prefix("battle-")).filter(|value|
                !value.is_empty() && value.bytes().all(|ch| ch.is_ascii_digit()))
        else { continue };
        if number.parse::<u64>().is_err() { continue; }
        let root = entry.path();
        let run = root.join("run");
        let checkpoint = run.join("native-host-checkpoint.json");
        if !checkpoint.is_file() { continue; }
        let source = root.join("replay-source-run.json");
        let saved_path = root.join("native-quick-battle-start.json");
        if run.is_symlink() || checkpoint.is_symlink() ||
            source.is_symlink() || saved_path.is_symlink()
        {
            return Err(invalid(
                "generated battle recovery path is a symlink",
            ).into());
        }
        // The saved launch mode is independent of its old scene file.
        // Do not reconcile the opposite (local/LAN) mode's recordings
        // while selecting a new battle for this mode.
        let saved = if saved_path.is_file() {
            let saved = QuickBattleStart::load(&saved_path)?;
            if saved.remote_host != remote_host { continue; }
            Some(saved)
        } else { None };
        // A committed battle no longer needs its generated source. If
        // its original file is missing or its archived contents changed,
        // the terminal receipt still owns the completed game's outcome.
        if terminal_recording::complete_committed_recording(&run)? { continue; }
        // An unfinished checkpoint must NEVER be silently skipped because
        // the archived source disappeared: that would start a new game
        // instead of recovering the original physical World.
        let saved = saved.ok_or_else(|| invalid(
            "interrupted generated battle has no owned immutable start archive",
        ))?;
        if !source.is_file() {
            return Err(invalid(
                "interrupted generated battle lost its original source archive",
            ).into());
        }
        let current = QuickBattleStart::capture(&source, remote_host)?
            .ok_or_else(|| invalid(
                "interrupted generated game no longer enables native World recovery",
            ))?;
        if current.source_config != saved.source_config ||
            current.source_sha256 != saved.source_sha256
        {
            return Err(invalid(
                "interrupted generated battle cannot resume after its archived source changed",
            ).into());
        }
        if pending.replace((source, run)).is_some() {
            return Err(invalid(
                "multiple interrupted generated games require explicit completion before a new match",
            ).into());
        }
    }
    Ok(pending)
}

#[cfg(feature = "client")]
fn run_library_host(settings_path: &Path, save_root: &Path,
    library: &NativeLibrary, games: &[PathBuf],
    trained: &[trained_library::TrainedGame]) -> Result<(), Box<dyn Error>> {
    let settings:NativeSavedHost=serde_json::from_slice(&fs::read(settings_path)?)?;
    if settings.listen.is_empty() || settings.listen.len()>255 ||
        settings.listen.chars().any(char::is_control) {
        return Err(invalid("native multiplayer host requires a private-network listen address").into());
    }
    let custom_fleet = settings.game_id == fleet_builder::GAME_ID;
    let campaign_index = library.games.iter().position(|entry|
        entry.id == settings.game_id && entry.kind == "campaign");
    let static_battle = library.games.iter().position(|entry|
        entry.id == settings.game_id && entry.kind == "battle");
    let trained_model = if custom_fleet || campaign_index.is_some() ||
        static_battle.is_some()
    {
        None
    } else {
        Some(trained.iter().find(|model| model.id == settings.game_id)
            .ok_or_else(|| invalid(
                "multiplayer host game ID is not a native campaign, battle or registered checkpoint",
            ))?)
    };
    // Static game sources can be launched directly. A trained publication
    // must FIRST be projected to the original physical single-Level human
    // challenge, exactly as the existing local trained-game picker does.
    let game_source = static_battle.map(|index| games[index].clone());
    let token_file=if settings.tokens_file.is_absolute(){
        settings.tokens_file
    }else{save_root.join(settings.tokens_file)};
    let metadata=fs::symlink_metadata(&token_file)?;
    if !metadata.is_file() || metadata.file_type().is_symlink() ||
        metadata.len()<2 || metadata.len()>2048 {
        return Err(invalid("multiplayer host token map must be a private regular file").into());
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        if metadata.permissions().mode() & 0o077 != 0 {
            return Err(invalid("multiplayer host token map must have owner-only permissions").into());
        }
    }
    let token_map=fs::read_to_string(&token_file)?;
    let tokens:std::collections::HashMap<String,String>=serde_json::from_str(&token_map)?;
    if tokens.is_empty() || tokens.len()>2 ||
        tokens.iter().any(|(side, token)|
            !matches!(side.as_str(),"1"|"2") ||
            !(24..=256).contains(&token.len()) ||
            token.chars().any(char::is_control)) ||
        tokens.values().collect::<HashSet<_>>().len()!=tokens.len() {
        return Err(invalid("host must provide unique side 1/2 native multiplayer tokens").into());
    }
    // A saved campaign game ID opens its original mission catalog and
    // career ledger. The same mission command used by headless multiplayer
    // applies unlocks, persistent fleet edits and durable battle receipts.
    // Do not turn a campaign into a stateless quick battle.
    let campaign = if let Some(index) = campaign_index {
        use bees_host::presentation::{BattleMenuRow, select_library};
        let catalog: battle_catalog::BattleCatalog =
            serde_json::from_slice(&fs::read(&games[index])?)?;
        catalog.validate()?;
        let career_root = save_root.join("campaigns").join(&settings.game_id);
        let progress = catalog.load_progress(&career_root)?;
        let available = catalog.battles.iter().filter_map(|entry| {
            let mission = entry.mission.as_ref()?;
            mission.requires.iter().all(|id| progress.completed(id))
                .then_some((entry, mission))
        }).collect::<Vec<_>>();
        if available.is_empty() {
            return Err(invalid("no unlocked native campaign mission can be hosted").into());
        }
        let rows = available.iter().map(|(entry, mission)| BattleMenuRow {
            title: entry.title.trim(),
            status: if progress.completed(&mission.id) { "  [Complete]" } else { "" },
            unlocked: true,
        }).collect::<Vec<_>>();
        let mut selected = 0_usize;
        let Some(choice) = select_library(&rows, &mut selected, false)?
            else { return Ok(()) };
        let mission = available[choice].1;
        if !tokens.contains_key(&mission.player_side.to_string()) {
            return Err(invalid("multiplayer host has no token for the campaign player side").into());
        }
        Some((games[index].clone(), career_root, mission.id.clone()))
    } else { None };
    // The authoritative host reads its existing protected environment
    // configuration. A child avoids process-global env mutations in the
    // parent UI and keeps one battle runtime / one source physics engine.
    // In custom-fleet mode both source sides retain genuine player
    // permissions; the existing per-side token map authorizes their remote
    // orders, without inventing a scripted AI or a second lobby protocol.
    let generated_game = custom_fleet || trained_model.is_some();
    let _generated_writer = if generated_game {
        Some(battle_catalog::CampaignWriterLease::acquire(
            &save_root.join("battles").join(&settings.game_id),
        )?)
    } else { None };
    let generated_recovery = if generated_game {
        recover_generated_library_battle(save_root, &settings.game_id, true)?
    } else { None };
    // A reconnect restores the same frozen fleet without asking the
    // human to recreate it or replacing the original archived scenario.
    let fleet = if custom_fleet && generated_recovery.is_none() {
        fleet_builder::choose_multiplayer()?
    } else { None };
    if custom_fleet && generated_recovery.is_none() && fleet.is_none() {
        return Ok(());
    }
    // Keep one save writer for the entire child-host lifetime. The parent
    // selects an original checkpoint before launching the only gameplay
    // runtime; no second host may race its World or replay its inputs.
    let quick_source = if campaign.is_none() && !generated_game {
        game_source.as_ref()
    } else { None };
    let _quick_writer = if quick_source.map(|source|
        QuickBattleStart::capture(source, true)
    ).transpose()?.flatten().is_some() {
        Some(battle_catalog::CampaignWriterLease::acquire(
            &save_root.join("battles").join(&settings.game_id),
        )?)
    } else { None };
    let mut launch = std::process::Command::new(env::current_exe()?);
    if let Some((catalog, career_root, mission_id)) = campaign {
        // campaign --serve enforces its own single-Level/model requirements,
        // reloads the ledger under the writer lease and publishes receipts.
        launch.arg("campaign").arg(catalog)
            .arg("--output-dir").arg(career_root)
            .arg("--mission").arg(mission_id).arg("--serve");
    } else {
        let (source, output) = if let Some((source, output)) = generated_recovery {
            println!("{}", json!({
                "kind": "native_generated_battle_recovered",
                "source": source, "run": output, "remote_host": true,
            }));
            (source, output)
        } else if let Some(choice) = fleet {
            let output = new_library_battle_output(save_root, &settings.game_id)?;
            let parent = output.parent().ok_or_else(||
                invalid("custom multiplayer fleet has no archive directory"))?;
            let source = fleet_builder::archive(parent, choice)?;
            let start = QuickBattleStart::capture(&source, true)?
                .ok_or_else(|| invalid("generated multiplayer fleet has no native recovery"))?;
            save_native_quick_battle_start(&output, &start)?;
            (source, output)
        } else if let Some(model) = trained_model {
            use bees_host::presentation::{BattleMenuRow, select_library};
            if tokens.len() != 1 {
                return Err(invalid(
                    "trained-policy multiplayer challenge requires one authenticated player side",
                ).into());
            }
            let side: i32 = tokens.keys().next()
                .expect("verified nonempty side token map").parse()?;
            let levels = model.playable_levels()?;
            if levels.is_empty() {
                return Err(invalid("trained multiplayer challenge has no playable Levels").into());
            }
            let level_index = if levels.len() > 1 {
                let titles = levels.iter().enumerate().map(|(index, (world, level))|
                    format!("Scenario {}  |  Level {}  |  World {}",
                        index + 1, level, world)
                ).collect::<Vec<_>>();
                let rows = titles.iter().map(|title| BattleMenuRow {
                    title, status: "  [Trained source Level]", unlocked: true,
                }).collect::<Vec<_>>();
                let mut selected = 0_usize;
                let Some(level) = select_library(&rows, &mut selected, false)?
                    else { return Ok(()) };
                level
            } else { 0 };
            let output = new_library_battle_output(save_root, &settings.game_id)?;
            let parent = output.parent().ok_or_else(||
                invalid("hosted trained game has no archive directory"))?;
            let source = model.archive_challenge(parent, side, level_index)?;
            let start = QuickBattleStart::capture(&source, true)?
                .ok_or_else(|| invalid("hosted trained game has no native recovery"))?;
            save_native_quick_battle_start(&output, &start)?;
            (source, output)
        } else {
            let source = game_source.expect("validated static multiplayer source");
            let output = select_library_quick_battle_output(
                save_root, &settings.game_id, &source, true,
            )?;
            (source, output)
        };
        launch.arg("play").arg(source).arg("--output-dir").arg(output);
    }
    let outcome = launch
        .env("BEES_NATIVE_REMOTE_LISTEN",&settings.listen)
        .env("BEES_NATIVE_REMOTE_SIDE_TOKENS",&token_map)
        .env_remove("BEES_NATIVE_REMOTE_TOKEN")
        .status()?;
    if !outcome.success() {
        return Err(invalid("native multiplayer host exited without completing its battle").into());
    }
    Ok(())
}

/// A single Unity-free home screen, not another simulation/campaign mode.
/// Each selected campaign uses the existing verified career ledger, shop,
/// mission unlocks and battle picker; quick battles use run_session directly.
#[cfg(feature = "client")]
fn run_library(library_path: &Path, save_root: &Path) -> Result<(), Box<dyn Error>> {
    use bees_host::presentation::{BattleMenuRow, select_library};
    use std::path::Component;

    let library_path = library_path.canonicalize()?;
    let base = library_path.parent().ok_or_else(|| invalid("missing native game library directory"))?;
    let library: NativeLibrary = serde_json::from_slice(&fs::read(&library_path)?)?;
    if library.library_schema != 1 || library.games.is_empty() ||
        library.games.len() > 100 {
        return Err(invalid("native game library requires 1..100 entries and schema 1").into());
    }
    let mut games = Vec::new();
    let mut seen = HashSet::new();
    for entry in &library.games {
        if entry.id.is_empty() || entry.id.len() > 48 ||
            !entry.id.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_') ||
            !seen.insert(entry.id.as_str()) ||
            entry.title.trim().is_empty() || entry.title.len() > 120 ||
            !matches!(entry.kind.as_str(), "campaign" | "battle") ||
            entry.config.extension().and_then(|ext| ext.to_str()) != Some("json") ||
            (entry.config.to_string_lossy().contains('\\') ||
             entry.config.to_string_lossy().contains(':')) ||
            !entry.config.components().all(|part| matches!(part, Component::Normal(_)))
        {
            return Err(invalid("invalid or duplicate native game library item").into());
        }
        let config = base.join(&entry.config).canonicalize()?;
        if !config.starts_with(base) || !config.is_file() {
            return Err(invalid("native library content must reside within the library directory").into());
        }
        // Fail before showing the window, not halfway through a menu choice.
        if entry.kind == "campaign" {
            let catalog: battle_catalog::BattleCatalog = serde_json::from_slice(&fs::read(&config)?)?;
            catalog.validate()?;
        } else {
            let _: RunConfig = serde_json::from_slice(&fs::read(&config)?)?;
        }
        games.push(config);
    }
    fs::create_dir_all(save_root)?;
    let mut trained = trained_library::load(save_root)?;
    println!("{}", json!({
        "kind": "native_game_library_ready",
        "games": library.games.len(),
        "trained_models": trained.len(),
        "campaigns": library.games.iter().filter(|entry| entry.kind == "campaign").count(),
        "battles": library.games.iter().filter(|entry| entry.kind == "battle").count(),
    }));
    let mut selected = 0_usize;
    let mut launch_failed = false;
    let saved_network = save_root.join("multiplayer.json");
    let saved_host = save_root.join("multiplayer-host.json");
    loop {
        // The session controller can publish a new verified checkpoint or
        // register a second independent learner while this game is open.
        // Refresh only between menu selections, never in the render loop.
        trained = trained_library::load(save_root)?;
        let status = library.games.iter().zip(&games).map(|(item, config)| {
            if item.kind != "campaign" {
                return Ok("  [Battle]".to_string());
            }
            let catalog: battle_catalog::BattleCatalog = serde_json::from_slice(&fs::read(config)?)?;
            let career_root = save_root.join("campaigns").join(&item.id);
            let progress = catalog.load_progress(&career_root)?;
            let total = catalog.battles.iter().filter_map(|b| b.mission.as_ref()).count();
            let complete = catalog.battles.iter().filter_map(|b| b.mission.as_ref())
                .filter(|mission| progress.completed(&mission.id)).count();
            Ok::<String, Box<dyn Error>>(format!("  [Career {complete}/{total}]"))
        }).collect::<Result<Vec<_>,_>>()?;
        let mut rows = library.games.iter().enumerate().map(|(index, item)| {
            BattleMenuRow {
                title: item.title.as_str(), status: status[index].as_str(),
                unlocked: true,
            }
        }).collect::<Vec<_>>();
        for model in &trained {
            rows.push(BattleMenuRow {
                title: &model.title, status: &model.status, unlocked: true,
            });
        }
        // Multiplayer configuration belongs to the player's save directory.
        // It is discovered on each return to the library, so a user can
        // change servers without rebuilding or editing the game package.
        let mut recordings = recorded_library::list(
            save_root,
            library.games.iter().enumerate()
                .filter(|(_, item)| item.kind == "battle")
                .map(|(index, item)|
                    (item.id.clone(), item.title.clone(), games[index].clone())),
        )?;
        recordings.extend(recorded_library::list_campaigns(
            save_root,
            library.games.iter().filter(|item| item.kind == "campaign")
                .map(|item| (item.id.clone(), item.title.clone())),
        )?);
        recordings.extend(recorded_library::list_trained(
            save_root, trained.iter().map(|model|
                (model.id.clone(), model.title.clone())),
        )?);
        recordings.extend(recorded_library::list_fleet_builds(save_root)?);
        recorded_library::sort_recent(&mut recordings);
        let join_available=saved_network.is_file();
        let host_available=saved_host.is_file();
        if join_available {
            rows.push(BattleMenuRow {
                title: "Join Multiplayer", status: "  [Saved server]",
                unlocked: true,
            });
        }
        if host_available {
            rows.push(BattleMenuRow {
                title: "Host Multiplayer", status: "  [Private lobby]",
                unlocked: true,
            });
        }
        if !recordings.is_empty() {
            rows.push(BattleMenuRow {
                title: "Watch Recorded Battles",
                status: "  [Saved replays]", unlocked: true,
            });
        }
        let fleet_builder_index = rows.len();
        rows.push(BattleMenuRow {
            title: "Build Fleet Skirmish",
            status: "  [Custom native fleets]", unlocked: true,
        });
        let fleet_train_index = rows.len();
        let training_available = fleet_training::training_available();
        rows.push(BattleMenuRow {
            title: "Train Saved Fleet",
            status: if training_available {
                "  [MA-POCA native training]"
            } else {
                "  [Install native training runtime]"
            },
            unlocked: training_available,
        });
        let fleet_training_jobs_index = rows.len();
        rows.push(BattleMenuRow {
            title: "Fleet Training Progress",
            status: "  [Rounds, SPS, checkpoint]", unlocked: true,
        });
        let fleet_benchmark_index = rows.len();
        rows.push(BattleMenuRow {
            title: "Benchmark Fleet Simulation",
            status: "  [Measured headless SPS]", unlocked: true,
        });
        let Some(index) = select_library(&rows, &mut selected, launch_failed)?
            else { break };
        let creating_fleet = index == fleet_builder_index;
        let training_fleet = index == fleet_train_index;
        let inspecting_fleet_training = index == fleet_training_jobs_index;
        let benchmarking_fleet = index == fleet_benchmark_index;
        let trained_index = (index >= library.games.len() &&
            index < library.games.len() + trained.len())
            .then_some(index.saturating_sub(library.games.len()));
        let remote = join_available && index == library.games.len() + trained.len();
        let hosting = host_available &&
            index == library.games.len() + trained.len() + usize::from(join_available);
        let watching = !recordings.is_empty() &&
            index == library.games.len() + trained.len() +
                usize::from(join_available) + usize::from(host_available);
        let (game_id, game_kind, game_title) = if creating_fleet {
            (fleet_builder::GAME_ID, "custom_fleet", "Build Fleet Skirmish")
        } else if training_fleet {
            ("fleet-training", "train", "Train Saved Fleet")
        } else if inspecting_fleet_training {
            ("fleet-training-progress", "training_progress", "Fleet Training Progress")
        } else if benchmarking_fleet {
            ("fleet-benchmark", "benchmark", "Benchmark Fleet Simulation")
        } else if watching {
            ("recordings", "recording_library", "Watch Recorded Battles")
        } else if remote {
            ("multiplayer", "remote", "Join Multiplayer")
        } else if hosting {
            ("multiplayer-host", "host", "Host Multiplayer")
        } else if let Some(trained_index) = trained_index {
            let model = &trained[trained_index];
            (model.id.as_str(), "trained", model.title.as_str())
        } else {
            let item = &library.games[index];
            (item.id.as_str(), item.kind.as_str(), item.title.as_str())
        };
        let launch_started = Instant::now();
        println!("{}", json!({
            "kind": "native_game_library_launch",
            "game_id": game_id,
            "game_kind": game_kind,
        }));
        let result: Result<(), Box<dyn Error>> = if creating_fleet {
            (|| {
                let _writer = battle_catalog::CampaignWriterLease::acquire(
                    &save_root.join("battles").join(fleet_builder::GAME_ID),
                )?;
                if let Some((source, output)) = recover_generated_library_battle(
                    save_root, fleet_builder::GAME_ID, false,
                )? {
                    println!("{}", json!({
                        "kind": "native_generated_battle_recovered",
                        "source": source, "run": output, "remote_host": false,
                    }));
                    return run_session(&source, true, true,
                        Some(output), None, None, None);
                }
                let Some(choice) = fleet_builder::choose()? else {
                    return Ok::<(), Box<dyn Error>>(());
                };
                let output = new_library_battle_output(save_root, fleet_builder::GAME_ID)?;
                let parent = output.parent().ok_or_else(||
                    invalid("custom skirmish has no archive directory"))?;
                let source = fleet_builder::archive(parent, choice)?;
                let start = QuickBattleStart::capture(&source, false)?
                    .ok_or_else(|| invalid("generated playable fleet has no native recovery"))?;
                save_native_quick_battle_start(&output, &start)?;
                println!("{}", json!({
                    "kind": "native_fleet_skirmish_ready",
                    "source": source,
                    "game_id": fleet_builder::GAME_ID,
                }));
                run_session(&source, true, true, Some(output), None, None, None)
            })()
        } else if training_fleet {
            fleet_training::choose_and_train(save_root)
        } else if inspecting_fleet_training {
            fleet_training::inspect_training_jobs(save_root)
        } else if benchmarking_fleet {
            (|| {
                let Some(choice) = fleet_builder::choose_benchmark()? else {
                    return Ok::<(), Box<dyn Error>>(());
                };
                let output = new_library_battle_output(save_root, "fleet-benchmark")?;
                let parent = output.parent().ok_or_else(||
                    invalid("native benchmark has no archive directory"))?;
                let source = fleet_builder::archive(parent, choice)?;
                // The same physical RunConfig enters the headless path.
                // No window, model worker, invented result or independent
                // training simulator is involved in this measurement.
                run_session(&source, false, false, Some(output.clone()),
                    None, None, None)?;
                fleet_builder::show_benchmark_result(&output)
            })()
        } else if watching {
            (|| {
                let rows = recordings.iter().map(|recording| BattleMenuRow {
                    title: &recording.title, status: &recording.status, unlocked: true,
                }).collect::<Vec<_>>();
                let mut replay_selected = 0;
                if let Some(chosen) = select_library(&rows, &mut replay_selected, false)? {
                    let recording = &recordings[chosen];
                    println!("{}", json!({
                        "kind": "native_game_recording_selected",
                        "source_game_id": recording.game_id,
                        "source_kind": match &recording.source {
                            recorded_library::RecordedSource::QuickBattle(_) => "quick_battle",
                            recorded_library::RecordedSource::TrainedBattle(_) => "trained_policy",
                            recorded_library::RecordedSource::CampaignSetup(_) => "campaign",
                        },
                        "recording": recording.trace,
                    }));
                    let output = new_library_battle_output(save_root, &recording.game_id)?;
                    match &recording.source {
                        recorded_library::RecordedSource::QuickBattle(config) |
                        recorded_library::RecordedSource::TrainedBattle(config) =>
                            run_session(config, true, true, Some(output),
                                None, Some(recording.trace.clone()), None)?,
                        recorded_library::RecordedSource::CampaignSetup(path) => {
                            let setup = CampaignReplaySetup::load(path)?;
                            // Watching a prior campaign is not a new career
                            // outcome. run_battle filters receipts whenever
                            // replay_inputs is supplied; this saved setup
                            // restores only the original physical fleet.
                            run_session(&setup.source_config, true, true,
                                Some(output), None, Some(recording.trace.clone()),
                                Some(setup.mission()))?;
                        },
                    }
                }
                Ok::<(), Box<dyn Error>>(())
            })()
        } else if remote {
            (|| {
                let connection: NativeSavedNetwork =
                    serde_json::from_slice(&fs::read(&saved_network)?)?;
                if connection.address.is_empty() || connection.address.len() > 255 {
                    return Err(invalid("invalid saved native multiplayer endpoint").into());
                }
                let token_file = if connection.token_file.is_absolute() {
                    connection.token_file
                } else {
                    save_root.join(connection.token_file)
                };
                bees_host::presentation::connect_remote(
                    &connection.address, &token_file, connection.side,
                )
            })()
        } else if hosting {
            run_library_host(&saved_host,save_root,&library,&games,&trained)
        } else if let Some(trained_index) = trained_index {
            // A selected trained model can still run the exact original
            // AI-vs-AI rollout, or become a human opponent on either
            // physical side without a training-only alternative game.
            (|| {
                let _writer = battle_catalog::CampaignWriterLease::acquire(
                    &save_root.join("battles").join(game_id),
                )?;
                if let Some((source, output)) = recover_generated_library_battle(
                    save_root, game_id, false,
                )? {
                    println!("{}", json!({
                        "kind": "native_generated_battle_recovered",
                        "source": source, "run": output, "remote_host": false,
                    }));
                    return run_session(&source, true, true,
                        Some(output), None, None, None);
                }
                let choices = [
                    BattleMenuRow {
                        title: "Fight trained policy as Bees (side 1)",
                        status: "  [Human vs trained]",
                        unlocked: true,
                    },
                    BattleMenuRow {
                        title: "Fight trained policy as Humans (side 2)",
                        status: "  [Human vs trained]",
                        unlocked: true,
                    },
                    BattleMenuRow {
                        title: "Watch original trained-policy battle",
                        status: "  [Original AI teams]",
                        unlocked: true,
                    },
                ];
                let mut choice = 0_usize;
                let Some(mode) = select_library(&choices, &mut choice, false)?
                    else { return Ok::<(), Box<dyn Error>>(()); };
                // One trained session can contain many independent
                // physical arenas. Let the player choose the actual
                // source Level rather than silently rejecting multi-world
                // sessions or launching every training world at once.
                let levels = trained[trained_index].playable_levels()?;
                let level_index = if levels.len() > 1 {
                    let titles = levels.iter().enumerate().map(|(index, (world, level))|
                        format!("Scenario {}  |  Level {}  |  World {}",
                            index + 1, level, world)
                    ).collect::<Vec<_>>();
                    let rows = titles.iter().map(|title| BattleMenuRow {
                        title, status: "  [Trained source Level]", unlocked: true,
                    }).collect::<Vec<_>>();
                    let mut selected_level = 0_usize;
                    let Some(index) = select_library(&rows, &mut selected_level, false)?
                        else { return Ok::<(), Box<dyn Error>>(()); };
                    index
                } else { 0 };
                let output = new_library_battle_output(save_root, game_id)?;
                let parent = output.parent()
                    .ok_or_else(|| invalid("missing trained battle archive"))?;
                let source = if mode < 2 {
                    trained[trained_index].archive_challenge(
                        parent, if mode == 0 { 1 } else { 2 }, level_index,
                    )?
                } else {
                    // Freeze the selected source Level and its first
                    // original episode, not a whole trainer world pool.
                    trained[trained_index].archive_playable(parent, level_index)?
                };
                let start = QuickBattleStart::capture(&source, false)?
                    .ok_or_else(|| invalid("archived trained game has no native recovery"))?;
                save_native_quick_battle_start(&output, &start)?;
                println!("{}", json!({
                    "kind": "native_trained_game_mode",
                    "game_id": game_id,
                    "mode": if mode == 2 { "original_ai" } else { "human_challenge" },
                    "human_side": if mode < 2 { Some(if mode == 0 { 1 } else { 2 }) } else { None },
                    "source_level_index": level_index,
                    "source_world_id": levels[level_index].0,
                    "source_level_id": levels[level_index].1,
                    "archived_run": source,
                }));
                run_session(&source, true, true, Some(output), None, None, None)
            })()
        } else if game_kind == "campaign" {
            run_menu(&games[index], &save_root.join("campaigns").join(game_id))
        } else {
            run_library_quick_battle(save_root, game_id, &games[index])
        };
        launch_failed = result.is_err();
        println!("{}", json!({
            "kind": "native_game_library_return",
            "game_id": game_id,
            "game_kind": game_kind,
            "success": !launch_failed,
            "session_wall_seconds": launch_started.elapsed().as_secs_f64(),
        }));
        if let Err(error) = result {
            eprintln!("Could not open {game_title}: {error}");
        }
    }
    Ok(())
}

#[cfg(feature = "client")]
fn run_menu(catalog_path: &Path, output_root: &Path) -> Result<(), Box<dyn Error>> {
    use bees_host::presentation::{
        BattleMenuRow, NativeBattleMenuAction, NativeShopMenuRow,
        NativeTransferMenuRow, NativeCreateSquadMenuRow,
        NativeTacticsMenuRow, select_battle,
    };

    let catalog_path = catalog_path.canonicalize()?;
    let catalog: battle_catalog::BattleCatalog = serde_json::from_slice(&fs::read(&catalog_path)?)?;
    catalog.validate()?;
    let root = catalog_path.parent().ok_or_else(|| invalid("missing catalog directory"))?;
    fs::create_dir_all(output_root)?;
    let mut progress = catalog.load_progress(output_root)?;
    let mut selected = 0;
    let mut number = 0_u64;
    let mut launch_failed = false;
    // These defaults come from the active authored mission configurations.
    // A victory route can change those source squads without creating any
    // new SavedSquad. Keep the parsed menu cache until either the player's
    // squad roster or the selected mission routes actually change.
    let mut tactic_source_cache: Option<(usize, Vec<bool>, Vec<NativeSavedSquadTactics>)> = None;
    loop {
        let rows = catalog.battles.iter().map(|entry| {
            let unlocked = entry.mission.as_ref().is_none_or(|mission|
                mission.requires.iter().all(|id| progress.completed(id)));
            let status = if !unlocked { "  [Locked]" }
                else if entry.mission.as_ref().is_some_and(|mission| progress.completed(&mission.id)) {
                    "  [Complete]"
                } else { "" };
            BattleMenuRow { title: entry.title.trim(), status, unlocked }
        }).collect::<Vec<_>>();
        let fleet_rows = progress.fleet_rows();
        let squad_rows = progress.squad_rows();
        let available = progress.unspent_minerals()?;
        let (original_choices, authored_squads, squad_templates, editable_tactics) =
            authored_menu_fleet(&catalog, root, &progress);
        // The same set of persistent player SavedSquads must exist in
        // every replayable physical mission configuration, not only the
        // currently selected mission or the career history.
        let mut squad_destinations = HashMap::<i32, Vec<i64>>::new();
        for side in [1, 2] {
            squad_destinations.insert(side, authored_squads.iter()
                .filter_map(|&(owner, id)| (owner == side).then_some(id))
                .collect());
        }
        let mut shop_rows = Vec::new();
        for ship in catalog.buildable_ships.iter().filter(|ship| ship.purchasable) {
            for &squad_id in squad_destinations.get(&ship.player_side)
                .into_iter().flatten()
            {
                let unlocked = progress.is_ship_unlocked(ship);
                shop_rows.push(NativeShopMenuRow {
                    title: format!(
                        "Type {}  ->  Squad #{}   TSV {}{}",
                        ship.ship_type, squad_id, ship.price_tsv,
                        if !unlocked { "  [Locked]" }
                        else if available < ship.price_tsv { "  [Insufficient]" }
                        else { "" },
                    ),
                    unlocked: unlocked && progress.bank_history_complete() &&
                        available >= ship.price_tsv,
                    side: ship.player_side,
                    ship_type: ship.ship_type,
                    saved_squad_id: squad_id,
                });
            }
        }
        let mut transfer_rows = Vec::new();
        // The shop can contain classes from both player sides. Build the
        // transfer picker once per side rather than taking only the first
        // class's side or repeating its purchased FleetShips.
        for side in [1, 2] {
            let squads = squad_destinations.get(&side)
                .expect("populated authorized squad destinations");
            // A legacy receipt with unknown loss evidence does not qualify
            // for reassignment. The existing career screens remain readable.
            let Ok(lost) = progress.lost_player_fleet_ids(side) else { continue };
            for purchased in progress.purchases_for_side(side) {
                if lost.contains(&purchased.fleet_ship_id) { continue; }
                if purchased.saved_squad_id != 0 {
                    transfer_rows.push(NativeTransferMenuRow {
                        title: format!(
                            "Fleet #{} (Type {})  Squad #{} -> Reserve",
                            purchased.fleet_ship_id, purchased.ship_type,
                            purchased.saved_squad_id,
                        ),
                        fleet_ship_id: purchased.fleet_ship_id,
                        to_saved_squad_id: 0,
                        authored_from: None,
                    });
                }
                for &destination in squads {
                    if purchased.saved_squad_id == destination { continue; }
                    transfer_rows.push(NativeTransferMenuRow {
                        title: format!(
                            "Fleet #{} (Type {})  {} -> Squad #{}",
                            purchased.fleet_ship_id, purchased.ship_type,
                            if purchased.saved_squad_id == 0 {
                                "Reserve".to_string()
                            } else {
                                format!("Squad #{}", purchased.saved_squad_id)
                            },
                            destination,
                        ),
                        fleet_ship_id: purchased.fleet_ship_id,
                        to_saved_squad_id: destination,
                        authored_from: None,
                    });
                }
            }
        }
        for &(side, fleet_id, original_squad) in &original_choices {
            let current_squad = progress.authored_current_squad(fleet_id)
                .unwrap_or(original_squad);
            if current_squad != 0 {
                transfer_rows.push(NativeTransferMenuRow {
                    title: format!(
                        "Original Fleet #{}  Squad #{} -> Reserve",
                        fleet_id, current_squad,
                    ),
                    fleet_ship_id: fleet_id,
                    to_saved_squad_id: 0,
                    authored_from: Some((side, current_squad)),
                });
            }
            for &destination in squad_destinations.get(&side)
                .expect("populated authorized squad destinations")
            {
                if current_squad == destination { continue; }
                transfer_rows.push(NativeTransferMenuRow {
                    title: format!(
                        "Original Fleet #{}  {} -> Squad #{}",
                        fleet_id,
                        if current_squad == 0 {
                            "Reserve".to_string()
                        } else {
                            format!("Squad #{}", current_squad)
                        },
                        destination,
                    ),
                    fleet_ship_id: fleet_id,
                    to_saved_squad_id: destination,
                    authored_from: Some((side, current_squad)),
                });
            }
        }
        let create_rows = squad_templates.into_iter().map(|(side, template)| {
            NativeCreateSquadMenuRow {
                title: format!("New player Squad (Side {}) from SavedSquad #{}",
                    side, template),
                side,
                template_saved_squad_id: template,
            }
        }).collect::<Vec<_>>();
        // Read actual source squad preferences rather than inventing
        // defaults for a campaign that has not yet recorded a battle.
        // The saved edit, when present, supersedes the scene default.
        let created_count = progress.created_squads_for_side(1).len() +
            progress.created_squads_for_side(2).len();
        let selected_routes = catalog.battles.iter().filter_map(|entry|
            entry.mission.as_ref()?.on_victory.as_ref().map(|route|
                progress.latest_victory(&route.mission))
        ).collect::<Vec<_>>();
        if tactic_source_cache.as_ref()
            .is_none_or(|(count, routes, _)|
                *count != created_count || *routes != selected_routes)
        {
            let mut tactic_defaults = HashMap::new();
            for entry in &catalog.battles {
                let Some(mission) = entry.mission.as_ref() else { continue };
                let run_path = resolve(root, entry.config_for(&progress));
                let mut source = load_native_fleet_edit_scene(&run_path)?;
                source.install_created_squads(
                    mission.player_side, &progress.created_squads_for_side(mission.player_side),
                ).map_err(|error| contextual("menu created squad tactics", error))?;
                for squad in &source.source_squads {
                    if let (Some(saved_id), Some(cease_fire)) =
                        (squad.saved_squad_id, squad.cease_fire)
                    {
                        if squad.side == mission.player_side &&
                            squad.player_permissions.user_controlled &&
                            !squad.hivemind.as_ref()
                                .is_some_and(|hivemind| hivemind.hivemind_controlled)
                        {
                            tactic_defaults.entry((squad.side, saved_id))
                                .or_insert(NativeSavedSquadTactics {
                                    side: squad.side, saved_squad_id: saved_id,
                                    shooting_strategy_id: squad.shooting.id,
                                    should_chase: squad.should_chase, cease_fire,
                                    match_speed: Some(squad.matching_speed.is_some()),
                                    color_setting: None,
                                });
                        }
                    }
                }
            }
            let mut tactic_defaults = tactic_defaults.into_values().collect::<Vec<_>>();
            tactic_defaults.sort_unstable_by_key(|row| (row.side, row.saved_squad_id));
            tactic_source_cache = Some((created_count, selected_routes, tactic_defaults));
        }
        let tactics_rows = tactic_source_cache.as_ref()
            .expect("saved tactics source cache initialized").2
            .iter().copied()
            .filter(|original| editable_tactics.binary_search(
                &(original.side, original.saved_squad_id)).is_ok())
            .map(|original| {
            let tactics = progress.tactics_for_squad(original.side, original.saved_squad_id)
                .unwrap_or(original);
            NativeTacticsMenuRow {
                title: format!("Side {} Squad #{}", tactics.side, tactics.saved_squad_id),
                side: tactics.side,
                saved_squad_id: tactics.saved_squad_id,
                shooting_strategy_id: tactics.shooting_strategy_id,
                should_chase: tactics.should_chase,
                cease_fire: tactics.cease_fire,
                match_speed: tactics.match_speed
                    .unwrap_or(original.match_speed.unwrap_or(false)),
                color_setting: tactics.color_setting
                    .unwrap_or(NativeSquadColorSetting::Inherit),
            }
        }).collect::<Vec<_>>();
        let Some(action) = select_battle(&rows, &mut selected, launch_failed,
            &fleet_rows, &squad_rows, &shop_rows, available, &transfer_rows,
            &create_rows, &tactics_rows)?
            else { break };
        let index = match action {
            NativeBattleMenuAction::Play(index) => index,
            NativeBattleMenuAction::CreateSquad { side, template_saved_squad_id } => {
                let result = run_create_saved_squad(
                    &catalog_path, output_root, side, template_saved_squad_id,
                );
                progress = catalog.load_progress(output_root)?;
                launch_failed = result.is_err();
                if let Err(error) = result {
                    eprintln!("Could not create SavedSquad from #{template_saved_squad_id}: {error}");
                }
                continue;
            }
            NativeBattleMenuAction::Tactics {
                side, saved_squad_id, shooting_strategy_id, should_chase, cease_fire,
                match_speed, color_setting,
            } => {
                let result = run_set_saved_squad_tactics(
                    &catalog_path, output_root, NativeSavedSquadTactics {
                        side, saved_squad_id, shooting_strategy_id, should_chase, cease_fire,
                        match_speed: Some(match_speed),
                        color_setting: Some(color_setting),
                    },
                );
                progress = catalog.load_progress(output_root)?;
                launch_failed = result.is_err();
                if let Err(error) = result {
                    eprintln!("Could not save tactics for Squad #{saved_squad_id}: {error}");
                }
                continue;
            }
            NativeBattleMenuAction::Buy { side, ship_type, saved_squad_id } => {
                let result = run_build_ship(
                    &catalog_path, output_root, side, ship_type, saved_squad_id,
                );
                progress = catalog.load_progress(output_root)?;
                launch_failed = result.is_err();
                if let Err(error) = result {
                    eprintln!("Could not build ship type {ship_type}: {error}");
                }
                continue;
            }
            NativeBattleMenuAction::Transfer {
                fleet_ship_id, to_saved_squad_id,
            } => {
                let result = run_transfer_ship(
                    &catalog_path, output_root, fleet_ship_id, to_saved_squad_id,
                );
                progress = catalog.load_progress(output_root)?;
                launch_failed = result.is_err();
                if let Err(error) = result {
                    eprintln!("Could not transfer FleetShip #{fleet_ship_id}: {error}");
                }
                continue;
            }
            NativeBattleMenuAction::Reassign {
                side, fleet_ship_id, from_saved_squad_id, to_saved_squad_id,
            } => {
                let result = run_reassign_authored_ship(
                    &catalog_path, output_root, side,
                    fleet_ship_id, from_saved_squad_id, to_saved_squad_id,
                );
                progress = catalog.load_progress(output_root)?;
                launch_failed = result.is_err();
                if let Err(error) = result {
                    eprintln!("Could not reassign original FleetShip #{fleet_ship_id}: {error}");
                }
                continue;
            }
        };
        let entry = &catalog.battles[index];
        let result = launch_catalog_battle(
            &catalog, entry, root, output_root, &mut number, true,
        );
        if entry.mission.is_some() { progress = catalog.load_progress(output_root)?; }
        launch_failed = result.is_err();
        if let Err(error) = result {
            eprintln!("Could not play {}: {error}", entry.title);
        }
    }
    Ok(())
}

/// Inform authenticated peers that finalization failed. No terminal
/// victory, campaign receipt or replay eligibility is implied.
fn publish_failed_multiplayer_delivery(
    remote: &mut Option<bees_host::remote_play::NativeRemotePlay>,
    run_id: &str,
) {
    if let Some(server) = remote {
        server.publish_interrupted_battle();
        server.drain_terminal_output(Duration::from_millis(350));
        println!("{}", json!({
            "kind": "native_remote_terminal_delivery",
            "run_id": run_id,
            "measurements": server.measurements(),
        }));
    }
}

fn run_battle(
    config_path: &Path, play: bool, view: bool, output: Option<&Path>,
    capture: Option<&Path>, replay_number: u64, replay_inputs: Option<&Path>,
    mission: Option<CampaignMission<'_>>,
) -> Result<Option<BattleRestart>, Box<dyn Error>> {
    let run_start = Instant::now();
    let root = config_path.parent().ok_or_else(|| invalid("missing config directory"))?;
    let config_bytes = fs::read(config_path)?;
    let mut config: RunConfig = serde_json::from_slice(&config_bytes)?;
    if mission.is_some() && (config.levels.len() != 1 || config.episodes_per_world != 1) {
        return Err(invalid("A campaign mission requires one Level and one episode").into());
    }
    if replay_inputs.is_some() && !config.model_updates.is_empty() {
        return Err(invalid("player input playback requires one policy manifest for the whole battle").into());
    }
    if config.status_every_rounds == Some(0) {
        return Err(invalid("status_every_rounds must be positive").into());
    }

    let period = nonzero(config.decision_period, "decision_period")?;
    let window = nonzero(config.rounds_per_window, "rounds_per_window")?;
    let delivery = nonzero(config.delivery_every, "delivery_every")?;
    let physical_workers = NonZeroUsize::new(config.physics_workers.unwrap_or(1))
        .ok_or_else(|| invalid("physics_workers must be positive"))?;
    if physical_workers.get() > 128 {
        return Err(invalid("physics_workers must be at most 128").into());
    }
    let navigation_workers = config.navigation_workers;
    if let Some(workers) = navigation_workers {
        let live_remote = env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_some();
        if !(1..=128).contains(&workers) || (!view && !live_remote) ||
            replay_inputs.is_some()
        {
            return Err(invalid(
                "navigation_workers must be 1..128 and requires live local or remote gameplay, not offline training or input playback",
            ).into());
        }
    }
    let timing = config.timing_sample_period
        .map(|value| nonzero(value, "timing_sample_period"))
        .transpose()?;
    if config.run_id.trim().is_empty() || config.stage_name.trim().is_empty() ||
        config.levels.is_empty() || config.max_rounds == 0 ||
        config.episodes_per_world == 0 ||
        !config.broadphase_cell_size.is_finite() ||
        config.broadphase_cell_size <= 0.0 ||
        config.next_squad_item_id <= 0 ||
        config.next_squad_item_id == i64::MAX
    {
        return Err(invalid("invalid run identity, bounds, allocator or round budget").into());
    }
    if replay_number > 0 {
        config.run_id.push_str(&format!("-replay-{replay_number}"));
    }
    for level in &config.levels {
        level.validate_seeds(config.episodes_per_world)?;
    }
    let mut previous_update = 0_u64;
    for update in &config.model_updates {
        if update.at_round <= previous_update ||
            update.at_round >= config.max_rounds ||
            update.manifest.as_os_str().is_empty()
        {
            return Err(invalid(
                "model_updates must be strictly increasing rounds below max_rounds with nonempty manifest paths",
            ).into());
        }
        previous_update = update.at_round;
    }
    if output.is_some() && (!config.recover_notifications.is_empty() ||
        !config.recover_outcome_journals.is_empty() ||
        config.hivemind.as_ref().is_some_and(|network| network.reconnect_game_id.is_some()))
    {
        return Err(invalid("HiveMind recovery and reconnection require the original configured checkpoint and journal paths").into());
    }
    let checkpoint = output.as_ref().map_or_else(
        || resolve(root, &config.connection_checkpoint), |dir| dir.join("connection-checkpoint.json"),
    );
    let notifications = output.as_ref().map_or_else(
        || resolve(root, &config.notifications), |dir| dir.join("events.jsonl"),
    );
    let policy_capture = config.policy_capture.as_ref().filter(|_| replay_inputs.is_none()).map(|path| output.as_ref().map_or_else(
        || resolve(root, path), |dir| dir.join("decisions.bin"),
    ));
    let summary = output.as_ref().map(|dir| dir.join("rollout-summary.json"))
        .or_else(|| config.rollout_summary.as_ref().map(|path| resolve(root, path)));
    if checkpoint == notifications {
        return Err(invalid("checkpoint and notification log must be distinct").into());
    }
    if policy_capture.as_ref().is_some_and(|path| path == &checkpoint || path == &notifications) {
        return Err(invalid("policy capture, checkpoint and notification log must be distinct").into());
    }
    let bounds = &config.fragment_spawn.map_bounds;
    let fragment_settings = FragmentSpawnSettings {
        map_bounds: Aabb {
            min: vec2(bounds.min), max: vec2(bounds.max),
        },
        half_map_extents: vec2(config.fragment_spawn.half_map_extents),
        asteroid_max_speed_exclusive:
            config.fragment_spawn.asteroid_max_speed_exclusive,
        training_health_ratio: config.fragment_spawn.training_health_ratio,
    };
    if !fragment_settings.valid() {
        return Err(invalid("fragment_spawn must contain real valid Stage settings").into());
    }

    // Preflight source assets, every Level identity and the requested model
    // routes before touching an output file or opening the policy process.
    let assets = match (
        config.native_stage.as_ref(),
        config.collision_matrix.as_ref(),
        config.stage_palette.as_ref(),
    ) {
        (Some(native), None, None) => NativeSceneAssets::from_native_stage(
            native.collision_matrix_rows,
            &native.asteroid_prefab_numbers,
            &config.stage_name, fragment_settings,
        ),
        (None, Some(matrix), Some(palette)) => NativeSceneAssets::load(
            &resolve(root, matrix),
            &resolve(root, palette),
            &config.stage_name, fragment_settings,
        ),
        _ => return Err(invalid(
            "supply either native_stage or both legacy collision_matrix and stage_palette, not both",
        ).into()),
    }.map_err(|error| contextual("stage assets", error))?;
    let mut declared = HashSet::new();
    let model_source = match (&config.python, &config.policy_worker, &config.model_manifest) {
        (Some(python), Some(worker), Some(manifest)) => {
            let manifest_path = resolve(root, manifest);
            let bytes = fs::read(&manifest_path)?;
            let manifest: Value = serde_json::from_slice(&bytes)?;
            for item in manifest.get("models").and_then(Value::as_array)
                .ok_or_else(|| invalid("manifest has no models array"))?
            {
                let slot = item.get("slot").and_then(Value::as_u64)
                    .and_then(|slot| u32::try_from(slot).ok())
                    .ok_or_else(|| invalid("manifest model slot is not uint32"))?;
                declared.insert(slot);
            }
            Some((resolve_interpreter(root, python), resolve(root, worker), manifest_path,
                format!("{:x}", Sha256::digest(bytes))))
        }
        (None, None, None) if config.model_updates.is_empty() => None,
        _ => return Err(invalid("policy runs require python, policy_worker, and model_manifest").into()),
    };

    let mut level_ids = HashSet::new();
    let mut world_ids = HashSet::new();
    let mut highest_squad_item_id = 0_i64;
    let mut source_levels = Vec::with_capacity(config.levels.len());
    let mut source_sides = Vec::with_capacity(config.levels.len());
    // Parse and validate an immutable authored scene/layout ONCE per
    // distinct source configuration. Every independent arena/episode clones
    // mutable game state from that validated template, while immutable
    // physical collider catalogs remain Arc-shared. This avoids repeating
    // JSON decoding and native layout construction at every episode reset.
    let mut source_scene_templates = Vec::with_capacity(config.levels.len());
    let mut source_documents: HashMap<PathBuf, (Arc<str>, String)> = HashMap::new();
    let mut source_templates: HashMap<(PathBuf, Option<String>), Arc<NativePhysicalScene>> =
        HashMap::new();
    let mut source_digests = Vec::with_capacity(config.levels.len());
    let mut source_template_parse_count = 0_u64;
    let mut source_template_parse_wall = std::time::Duration::ZERO;
    let mut source_template_clone_count = 0_u64;
    let mut source_template_clone_wall = std::time::Duration::ZERO;
    let mut recycled_template_clone_count = 0_u64;
    let mut recycled_template_clone_wall = std::time::Duration::ZERO;
    let mut saved_squad_sources = Vec::new();
    let single_level = config.levels.len() == 1;
    for level in &mut config.levels {
        if level.level_id <= 0 || level.world_id == 0 ||
            !level_ids.insert(level.level_id) ||
            !world_ids.insert(level.world_id) ||
            !level.model_slots.values().all(|slot| declared.contains(slot))
        {
            return Err(invalid("duplicate/invalid Level or missing real model slot").into());
        }
        let source_path = resolve(root, &level.scene).canonicalize()?;
        let (source_json, source_digest) =
            if let Some(cached) = source_documents.get(&source_path) {
                cached.clone()
            } else {
                let text: Arc<str> = fs::read_to_string(&source_path)?.into();
                let digest = format!("{:x}", Sha256::digest(text.as_bytes()));
                source_documents.insert(source_path.clone(), (Arc::clone(&text), digest.clone()));
                (text, digest)
            };
        source_digests.push(source_digest);
        // Layout is part of the physical source identity. Two arenas with
        // different layouts must never clone one another's colliders/squads.
        let key = (source_path, level.native_layout.as_ref()
            .map(serde_json::to_string).transpose()?);
        let template = if let Some(cached) = source_templates.get(&key) {
            Arc::clone(cached)
        } else {
            let started = Instant::now();
            let mut parsed = NativePhysicalScene::parse_scene_with_assets(&source_json, &assets)
                .map_err(|error| contextual("exported Level", error))?;
            if let Some(layout) = &level.native_layout {
                parsed.apply_native_layout(
                    layout, assets.box_catalog(), assets.polygon_catalog(),
                ).map_err(|error| contextual("native Level layout", error))?;
            }
            source_template_parse_count += 1;
            source_template_parse_wall += started.elapsed();
            let parsed = Arc::new(parsed);
            source_templates.insert(key, Arc::clone(&parsed));
            parsed
        };
        let started = Instant::now();
        let mut source = template.as_ref().clone();
        source_template_clone_count += 1;
        source_template_clone_wall += started.elapsed();
        source_scene_templates.push(template);
        if let Some(created) = mission.and_then(|mission| mission.created_squads) {
            source.install_created_squads(
                mission.expect("campaign squad creation owner").player_side, created,
            ).map_err(|error| contextual("saved native campaign squads", error))?;
        }
        if let Some(tactics) = mission.and_then(|mission| mission.tactics) {
            source.apply_saved_squad_tactics(
                mission.expect("campaign tactics owner").player_side, tactics,
            ).map_err(|error| contextual("restored SavedSquad tactics", error))?;
        }
        if let Some(assignments) = mission.and_then(|mission| mission.authored_roster) {
            let reassigned = source.apply_authored_fleet_roster(
                mission.expect("authored campaign owner").player_side, assignments,
            ).map_err(|error| contextual("saved authored FleetShip roster", error))?;
            if reassigned != 0 {
                println!("{}", json!({
                    "kind": "native_campaign_authored_roster_restored",
                    "level_id": level.level_id,
                    "original_hulls_reassigned_or_reserved": reassigned,
                }));
            }
        }
        if let Some(purchased) = mission.and_then(|mission| mission.purchased_ships) {
            let empty_casualties = HashSet::new();
            let installed = source.install_purchased_ships(
                mission.expect("campaign purchase owner").player_side, purchased,
                mission.and_then(|mission| mission.lost_fleet_ids)
                    .unwrap_or(&empty_casualties),
            ).map_err(|error| contextual("purchased campaign ships", error))?;
            if installed != 0 {
                println!("{}", json!({
                    "kind": "native_campaign_purchased_ships_installed",
                    "level_id": level.level_id,
                    "purchased_hulls_installed": installed,
                }));
            }
        }
        if let Some(dead_ids) = mission.and_then(|mission| mission.lost_fleet_ids) {
            let removed = source.omit_killed_fleet_ships(
                mission.expect("campaign owner").player_side, dead_ids,
            ).map_err(|error| contextual("saved campaign fleet", error))?;
            if removed != 0 {
                println!("{}", json!({
                    "kind": "native_campaign_fleet_restored",
                    "level_id": level.level_id,
                    "permanently_lost_ships_omitted": removed,
                }));
            }
        }
        // Speed matching must use the FINAL surviving and purchased roster.
        // Applying it to the unmodified scene would make a slow replacement
        // ship move faster than the source's MatchSpeed permits.
        if let Some(tactics) = mission.and_then(|mission| mission.tactics) {
            source.apply_saved_squad_matching_speeds(
                mission.expect("campaign matching-speed owner").player_side, tactics,
            ).map_err(|error| contextual("restored SavedSquad matching speed", error))?;
        }
        if source.stage_name != config.stage_name {
            return Err(invalid("exported Level belongs to a different Stage").into());
        }
        let sides = source.gameplay_sides();
        if config.hivemind.as_ref().is_some_and(|network| network.issue_source_commands) &&
            (source.schema_version < 27 ||
                source.activate_hivemind.is_none() ||
                source.activate_mining.is_none() ||
                source.hivemind_initial_command_delay_seconds.is_none() ||
                source.starting_positions.is_none() ||
                source.source_squads.iter().any(|squad| squad.hivemind.is_none()))
        {
            return Err(invalid(format!(
                "Level {} requires schema-27 Unity HiveMind activation, timing, home positions, mining and per-squad authority for source commands",
                level.level_id,
            )).into());
        }
        // Schema 16 carries authentic Unity Agent instance identities.
        // New scenes do not need operator-supplied group IDs; any manual
        // values must agree exactly with the recorded source membership.
        if let Some(exported) = &source.source_policy_group {
            if let Some(configured) = &level.groups {
                let mut supplied: Vec<_> = configured.participants.iter()
                    .map(|member| (member.side, member.agent_id)).collect();
                let mut actual: Vec<_> = exported.participants.iter()
                    .map(|member| (member.side, member.agent_id)).collect();
                supplied.sort_unstable();
                actual.sort_unstable();
                if configured.episode_number != exported.episode_number ||
                    supplied != actual
                {
                    return Err(invalid(
                        "explicit group identity does not match exported Unity MA-POCA participants",
                    ).into());
                }
            } else {
                level.groups = Some(GroupConfig {
                    episode_number: exported.episode_number,
                    participants: exported.participants.iter().map(|member|
                        GroupParticipantConfig {
                            side: member.side, agent_id: member.agent_id,
                        }
                    ).collect(),
                });
            }
        }
        if let Some(group) = &level.groups {
            // Old source scenes lack the source's per-team movement flags.
            // They may be evaluated once, but must not silently produce
            // unfaithful alternate-team training trajectories on replay.
            if source.source_policy_group.is_none() &&
                config.episodes_per_world > 1
            {
                return Err(invalid(
                    "MA-POCA episode replay requires schema-16 source group metadata",
                ).into());
            }
            if source.source_policy_bindings.is_empty() {
                return Err(invalid("group source has no bound policy controllers").into());
            }
            if group.episode_number == 0 ||
                group.episode_number.checked_add(config.episodes_per_world - 1)
                    .is_none()
            {
                return Err(invalid("configured group episode range is invalid").into());
            }
            let mut agents = HashSet::new();
            for participant in &group.participants {
                if !sides.contains(&participant.side) {
                    return Err(invalid("MA-POCA participant side does not belong to Level").into());
                }
                if participant.agent_id == 0 ||
                    !agents.insert((participant.side, participant.agent_id))
                {
                    return Err(invalid("MA-POCA participant ID is zero or repeated").into());
                }
            }
            if group.participants.is_empty() {
                return Err(invalid("MA-POCA group has no participating source agents").into());
            }
            // Check the exported initial controller team BEFORE any
            // per-episode permutation or output file creation.
            bind_group_routes(&mut source, group, 0, true, level.episode_seed(0))?;
            // Replayed self-play episodes flip each controlled side's
            // team ID. Only require the other slot when a replay can
            // actually occur; a one-sided/scripted episode may have just
            // one participating policy team.
            if config.episodes_per_world > 1 &&
                source.source_policy_bindings.values().any(|binding|
                    !level.model_slots.contains_key(&(1 - binding.team_id))
                )
            {
                return Err(invalid(
                    "recycled group Levels require real models for both alternating policy teams",
                ).into());
            }
        }
        for squad in &source.source_squads {
            highest_squad_item_id = highest_squad_item_id.max(squad.item_id);
        }
        if level.reinforcements.iter().flat_map(|wave| &wave.squad_item_ids)
            .any(|id| !source.source_squads.iter().any(|squad| squad.item_id == *id))
        {
            return Err(invalid("Reinforcements reference an unknown source squad item ID").into());
        }
        if mission.is_some_and(|mission| !source.source_squads.iter().any(|squad|
            squad.side == mission.player_side && squad.player_permissions.user_controlled &&
            !squad.members.is_empty()))
        {
            return Err(invalid("The campaign player side has no authored player squad").into());
        }
        // A mission side needs real command authority in either runtime:
        // human player squads during ordinary play and authenticated group
        // policy agents during training. Policy-owned squads deliberately
        // clear user_controlled when authored; requiring it here would
        // reject real extraction and survival episodes before simulation.
        // Persisted campaign missions still require human control and never
        // gain policy authority implicitly.
        let deferred_squads: HashSet<i64> = level.reinforcements.iter()
            .flat_map(|wave| wave.squad_item_ids.iter().copied()).collect();
        let objective_has_controller = |side| source.source_squads.iter().any(|squad|
            squad.side == side && !squad.members.is_empty() &&
            (squad.player_permissions.user_controlled ||
             (mission.is_none() && (
                 (level.groups.is_some() && squad.members.iter().any(|id|
                     source.source_policy_bindings.contains_key(id))) ||
                 (!deferred_squads.contains(&squad.item_id) &&
                  level.scripted_queues.iter().any(|queue|
                     queue.squad_item_id == squad.item_id &&
                     !queue.orders.is_empty() &&
                     matches!(queue.activation, ScriptedActivationConfig::Immediate)))
             )))
        );
        if let Some(zone) = &level.extraction {
            if !sides.contains(&zone.player_side) ||
                mission.is_some_and(|mission| mission.player_side != zone.player_side) ||
                !objective_has_controller(zone.player_side)
            {
                return Err(invalid("Extraction requires a deployed player, policy or scripted controller on its objective side").into());
            }
        }
        if let Some(objective) = &level.survival {
            if mission.is_some_and(|mission| mission.player_side != objective.defending_side) ||
                !objective_has_controller(objective.defending_side)
            {
                return Err(invalid("Survival requires a deployed player, policy or scripted controller on its defending side").into());
            }
            if mission.is_some() {
                // The shared survival controller wins only after
                // ceil(seconds / fixed_dt) completed physics ticks.
                // A campaign with fewer available rounds cannot win,
                // regardless of tactical decisions or remaining health.
                let required = (objective.seconds / source.fixed_dt_seconds).ceil();
                if required.is_finite() && required >= 1.0 &&
                    required < u64::MAX as f32 &&
                    required as u64 > config.max_rounds
                {
                    return Err(invalid(format!(
                        "Campaign defense requires at least {} rounds at the authored fixed step; max_rounds is {}",
                        required as u64, config.max_rounds,
                    )).into());
                }
            }
        }
        if let Some(objective) = level.demolition {
            if level.survival.is_some() || level.extraction.is_some() ||
                !sides.contains(&objective.attacking_side) ||
                mission.is_some_and(|mission| mission.player_side != objective.attacking_side) ||
                !objective_has_controller(objective.attacking_side) ||
                !source.entities.iter().any(|entity| matches!(
                    entity,
                    bees_host::scene_builder::NativeAuthoredEntity::MapObject { object, body }
                        if object.entity_id == objective.target_map_object_id &&
                        object.health > 0 && body.active
                ))
            {
                return Err(invalid("Demolition requires an existing live MapObject and an active attacking player, policy or scripted controller").into());
            }
            if mission.is_some() {
                let required = (objective.seconds / source.fixed_dt_seconds).ceil();
                if required.is_finite() && required >= 1.0 &&
                    required < u64::MAX as f32 &&
                    required as u64 > config.max_rounds
                {
                    return Err(invalid(format!(
                        "Campaign demolition needs at least {} rounds; max_rounds is {}",
                        required as u64, config.max_rounds,
                    )).into());
                }
            }
        }
        if let Some(objective) = level.escort {
            let target_squad = source.source_squads.iter().find(|squad|
                squad.members.contains(&objective.escorted_ship_id)
            );
            if level.survival.is_some() || level.demolition.is_some() ||
                !level.extraction.as_ref().is_some_and(|zone|
                    zone.player_side == objective.escorting_side) ||
                mission.is_some_and(|mission|
                    mission.player_side != objective.escorting_side) ||
                !sides.contains(&objective.escorting_side) ||
                !objective_has_controller(objective.escorting_side) ||
                !target_squad.is_some_and(|squad| squad.side == objective.escorting_side &&
                    !deferred_squads.contains(&squad.item_id)) ||
                !source.entities.iter().any(|entity| matches!(
                    entity,
                    NativeAuthoredEntity::Ship(ship)
                        if ship.entity_id == objective.escorted_ship_id &&
                            ship.side == objective.escorting_side &&
                            ship.motion.mobile && !ship.vitals.is_dead()
                ))
            {
                return Err(invalid("Escort requires an initial living mobile ship on its extraction side and an active player, policy or scripted controller").into());
            }
            if mission.is_some() {
                let required = (objective.seconds / source.fixed_dt_seconds).ceil();
                if required.is_finite() && required >= 1.0 &&
                    required < u64::MAX as f32 &&
                    required as u64 > config.max_rounds
                {
                    return Err(invalid(format!(
                        "Campaign escort needs at least {} fixed rounds; max_rounds is {}",
                        required as u64, config.max_rounds,
                    )).into());
                }
            }
        }
        if let Some(dialogue) = level.campaign_dialogue {
            let player_side = dialogue.player_side();
            if !single_level || !sides.contains(&player_side) ||
                mission.is_some_and(|mission| mission.player_side != player_side) ||
                !source.source_squads.iter().any(|squad|
                    squad.side == player_side && squad.player_permissions.user_controlled)
            {
                return Err(invalid("Campaign dialogue requires one Level and its authored player side").into());
            }
        }
        if model_source.is_none() && !source.source_policy_bindings.is_empty() {
            return Err(invalid("authored policy controllers require a model worker").into());
        }
        for binding in source.source_policy_bindings.values() {
            if !level.model_slots.contains_key(&binding.team_id) {
                return Err(invalid("Level has an unresolved source policy team").into());
            }
        }
        if mission.is_some_and(|mission| mission.record_fleet_stats) {
            let persistent_ships = source.entities.iter().filter_map(|entity| match entity {
                NativeAuthoredEntity::Ship(ship) => Some((ship.entity_id, ship)),
                _ => None,
            }).collect::<HashMap<_, _>>();
            let mut seen_saved_squads = HashSet::new();
            let mut saved_members = HashSet::new();
            for squad in &source.source_squads {
                // An empty owned SavedSquad is available to the editor,
                // not deployed in the physical Level or its career
                // receipt. Do not fabricate a zero-ship battle result.
                if squad.members.is_empty() { continue; }
                let Some(saved_squad_id) = squad.saved_squad_id else { continue };
                if !seen_saved_squads.insert(saved_squad_id) {
                    return Err(invalid("duplicate persistent SavedSquad ID").into());
                }
                let mut fleet_ship_ids = Vec::with_capacity(squad.members.len());
                for &id in &squad.members {
                    let ship = persistent_ships.get(&id).ok_or_else(||
                        invalid("saved squad has a missing authored member"))?;
                    let fleet = source.fleet.get(id).ok_or_else(||
                        invalid("saved squad has no FleetShip metadata"))?;
                    let fleet_id = ship.fleet_ship_id.ok_or_else(||
                        invalid("saved squad member has no persistent FleetShip identity"))?;
                    if !fleet.has_persistent_fleet_value || ship.side != squad.side ||
                        !saved_members.insert(fleet_id)
                    {
                        return Err(invalid("saved squad reuses a FleetShip or a transient minion").into());
                    }
                    fleet_ship_ids.push(fleet_id);
                }
                saved_squad_sources.push(CampaignSquadSource {
                    saved_squad_id, side: squad.side, fleet_ship_ids,
                });
            }
        }
        if mission.is_some_and(|mission| mission.record_fleet_stats) {
            source.fleet.enable_career_tracking();
        }
        source_levels.push(source);
        source_sides.push(sides);
    }
    let unique_source_documents = source_documents.len();
    let unique_source_templates = source_templates.len();
    // A retained reference per source Level is enough for all episode
    // resets. Release temporary JSON documents and the lookup table before
    // training so large jobs do not keep redundant source bytes alive.
    drop(source_documents);
    drop(source_templates);
    if config.next_squad_item_id <= highest_squad_item_id {
        return Err(invalid(
            "next_squad_item_id must be the real next Stage pool identity, above all source squads",
        ).into());
    }

    // Every world shares the one source Stage pool identity stream, even
    // when an opted-in physics worker admits a newly spawned child squad.
    let next_id = Arc::new(AtomicI64::new(config.next_squad_item_id));
    // Multiple independently driven arena instances may intentionally use
    // the same exported Level template, whose original Stage pool IDs are
    // duplicates. Keep the first source lifetime and allocate fresh IDs
    // for subsequent copies so session ownership remains unambiguous.
    let mut seen_squad_ids = HashSet::new();
    let mut remapped_squads_by_level = Vec::with_capacity(source_levels.len());
    for source in &mut source_levels {
        let mut remapped = HashMap::new();
        for squad in &mut source.source_squads {
            if !seen_squad_ids.insert(squad.item_id) {
                let item_id = take_stage_item_id(&next_id)
                    .ok_or_else(|| invalid("Stage squad identities exhausted"))?;
                remapped.insert(squad.item_id, item_id);
                squad.item_id = item_id;
                seen_squad_ids.insert(item_id);
            }
        }
        remapped_squads_by_level.push(remapped);
    }
    let source_fixed_dt_by_level: Vec<f32> =
        source_levels.iter().map(|source| source.fixed_dt_seconds).collect();
    // The remote headless host advances the *same* authored fixed step at
    // game time, rather than consuming the whole training rollout instantly.
    let remote_step_interval = if env::var_os("BEES_NATIVE_REMOTE_LISTEN").is_some() {
        Some(std::time::Duration::try_from_secs_f32(
            source_levels[0].fixed_dt_seconds / source_levels[0].time_scale,
        ).map_err(|_| invalid("remote Level time scale is not a valid wall-clock duration"))?)
    } else { None };
    #[cfg(feature = "client")]
    // Unity's Stage.TimeScale changes how often fixed ticks execute,
    // not the physics dt passed to the common CombatWorld. Headless
    // training and replayed world state remain authored fixed-tick work.
    #[cfg(feature = "client")]
    let client_step_interval_by_level: Vec<std::time::Duration> =
        source_levels.iter().map(|source|
            std::time::Duration::try_from_secs_f32(
                source.fixed_dt_seconds / source.time_scale,
            ).map_err(|_| invalid("source Stage time scale cannot be represented by the host clock"))
        ).collect::<io::Result<_>>()?;
    let client_bounds: Vec<_> = source_levels.iter().map(|scene| scene.bounds).collect();
    let remote_music_location = source_levels[0].music_location;
    #[cfg(feature = "client")]
    let client_zoom_limits: Vec<_> =
        source_levels.iter().map(|scene| scene.camera_zoom).collect();
    // Open the optional window before starting the model or creating durable
    // run outputs. A window setup failure leaves no live episode to abandon.
    #[cfg(feature = "client")]
    let mut client = if view {
        let mut client = bees_host::client::NativeClient::new(client_bounds[0])?;
        // Hot-seat is restricted to a single offline source Level whose
        // BOTH factions actually own selectable, input-enabled squads.
        // This is never enabled for a policy opponent, campaign replay or
        // authenticated multiplayer host. F9 changes only the player's
        // temporary viewer/command side, not CombatWorld or source AI.
        if replay_inputs.is_none() && remote_step_interval.is_none() &&
            source_levels.len() == 1 &&
            source_sides[0].iter().all(|&side| (1..=2).contains(&side)) &&
            source_sides[0].iter().all(|&side|
                source_levels[0].source_squads.iter().any(|squad|
                    squad.side == side && !squad.members.is_empty() &&
                    squad.player_permissions.user_controlled &&
                    squad.player_permissions.can_accept_input))
        {
            let sides = source_sides[0];
            let initial = source_levels[0].targeting_context.as_ref()
                .map_or(sides[1], |context| context.user_side);
            client.enable_hotseat(sides, initial);
        }
        client.set_source_zoom_limits(client_zoom_limits);
        client.set_music_locations(
            source_levels.iter().map(|source| source.music_location).collect(),
        );
        // Stage/user settings are common to these simultaneously captured
        // Levels, while an operator can override edge panning with F6.
        client.set_source_edge_scrolling(
            source_levels[0].camera_edge_scrolling,
        );
        // Unity StageTitania2HumanFleetAtCenter assigns this precise
        // Stage.DefaultCameraPosition before the Beenoculars briefing.
        // Keep this in the mission host; the reusable client only knows
        // about an optional authored camera focus, never campaign rules.
        if config.levels.len() == 1 && matches!(
            config.levels[0].campaign_dialogue,
            Some(bees_gameplay::campaign_dialogue::CampaignDialogueSpec::TitaniaBeenoculars { .. })
        ) {
            client.focus_camera(bees_gameplay::campaign_dialogue::TITANIA_II_CENTER);
        }
        if replay_inputs.is_some() { client.set_playback(); }
        Some(client)
    } else { None };
    let mut launches = Vec::with_capacity(source_levels.len());
    for (index, (source, level)) in source_levels.into_iter()
        .zip(&config.levels).enumerate()
    {
        launches.push((
            source,
            make_setup(
                &config, level, &assets, period,
                Arc::clone(&next_id), level.episode_seed(0), 0, source_sides[index], &remapped_squads_by_level[index],
            )?,
        ));
    }

    // Interactive play includes windowed, headless LAN, and replayed
    // player-controlled Levels. Record and verify the SAME gameplay
    // identity regardless of which presentation transport carries inputs;
    // otherwise a valid remote-player trace cannot be replayed offline.
    let gameplay_digest = gameplay_config_sha256(
        &config, &assets,
        play || view || remote_step_interval.is_some() || replay_inputs.is_some(),
    );
    let config_digest = format!("{:x}", Sha256::digest(&config_bytes));
    let trace_levels = config.levels.iter().zip(source_digests.iter()).map(|(level, digest)|
        NativeTraceLevel {
            world_id: level.world_id,
            level_id: level.level_id,
            scene_sha256: digest.clone(),
            seed: level.seed,
            episode_seeds: level.episode_seeds.clone(),
        }
    ).collect::<Vec<_>>();
    let mut playback = replay_inputs.map(|path|
        NativePlayerTrace::read(path, &config_digest, &gameplay_digest, &trace_levels,
            model_source.as_ref().map(|(_, _, _, digest)| digest.as_str()),
            config.hivemind.is_some())
    ).transpose()?;
    if playback.as_ref().is_some_and(|trace| trace.end_round > config.max_rounds) {
        return Err(invalid("player trace exceeds the configured round budget").into());
    }
    // Background path completion timing depends on operating-system
    // scheduling. Never claim a deterministic replayable player-input
    // trace for a run where asynchronous navigation can change route
    // installation ticks. Recorded gameplay can now checkpoint its synced
    // transcript together with its World rather than losing recording.
    let recording_allowed = (play || remote_step_interval.is_some()) &&
        replay_inputs.is_none() && navigation_workers.is_none() &&
        config.model_updates.is_empty();
    // Offline replay reads the exact original run bytes for its identity,
    // but cannot checkpoint an action playback file as if it were a live
    // resident policy. Playback always creates a distinct output World.
    if replay_inputs.is_some() {
        config.host_recovery_checkpoint = None;
    }
    if let Some(directory) = output {
        if directory.exists() || directory.is_symlink() {
            // Only the same original World/Level/journal transaction can
            // resume a prior gameplay output directory. New unrelated
            // sessions retain the create-only saved battle contract.
            if config.host_recovery_checkpoint.is_none() ||
                directory.is_symlink() || !directory.is_dir() ||
                !directory.join("native-host-checkpoint.json").is_file()
            {
                return Err(invalid(
                    "an existing native output directory requires its original durable host recovery checkpoint",
                ).into());
            }
        } else {
            fs::create_dir(directory)?;
        }
    }
    let host_checkpoint_file = config.host_recovery_checkpoint.as_ref().map(|path| {
        let path = output.map_or_else(
            || resolve(root, path), |dir| dir.join("native-host-checkpoint.json"),
        );
        if path == checkpoint || path == notifications ||
            policy_capture.as_ref().is_some_and(|capture| capture == &path) ||
            summary.as_ref().is_some_and(|summary| summary == &path)
        {
            return Err(bees_host::checkpoint_file::CheckpointFileError::InvalidPath);
        }
        NativeHostCheckpointFile::open(path)
    }).transpose().map_err(|error| contextual("native host checkpoint lease", error))?;
    let saved_host_checkpoint = host_checkpoint_file.as_ref()
        .map(|file| file.load()).transpose()
        .map_err(|error| contextual("native host checkpoint load", error))?
        .flatten();
    let recovered_existing_host = saved_host_checkpoint.is_some();
    let resume_cursor: Option<NativeBattleRecoveryCursor> =
        saved_host_checkpoint.as_ref().map(|snapshot|
            serde_json::from_value(snapshot.launcher().clone())
        ).transpose().map_err(|error| contextual("native launcher recovery cursor", error))?;
    if let Some(cursor) = &resume_cursor {
        if cursor.schema_version != 1 || cursor.run_id != config.run_id ||
            cursor.config_sha256 != config_digest ||
            cursor.gameplay_sha256 != gameplay_digest ||
            cursor.source_sha256 != source_digests ||
            cursor.rounds > config.max_rounds ||
            !cursor.elapsed_wall_seconds.is_finite() || cursor.elapsed_wall_seconds < 0.0 ||
            !cursor.elapsed_startup_seconds.is_finite() || cursor.elapsed_startup_seconds < 0.0 ||
            !cursor.elapsed_execution_seconds.is_finite() || cursor.elapsed_execution_seconds < 0.0 ||
            cursor.elapsed_startup_seconds + cursor.elapsed_execution_seconds >
                cursor.elapsed_wall_seconds + 0.001 ||
            cursor.next_model_update > config.model_updates.len() ||
            cursor.segment_generation != cursor.next_model_update as u64 ||
            cursor.segment_start_round > cursor.rounds ||
            cursor.completed_episodes.len() != config.levels.len() ||
            cursor.counted_revisions.len() != config.levels.len() ||
            cursor.completed_episodes.iter().any(|&count| count > config.episodes_per_world) ||
            cursor.next_squad_item_id < next_id.load(Ordering::Relaxed) ||
            cursor.network_schedule.is_some() != config.hivemind.is_some() ||
            cursor.network_game_id.is_some() != config.hivemind.is_some() ||
            cursor.remote_play.is_some() != remote_step_interval.is_some() ||
            cursor.recording.as_ref().is_some_and(|recording|
                !recording_allowed ||
                recording.policy_actions.is_some() != model_source.is_some() ||
                recording.last_physical_checkpoint_round
                    .is_some_and(|round| round > cursor.rounds) ||
                [recording.trace_checkpoint_sync_wall_seconds,
                 recording.trace_input_sync_wall_seconds,
                 recording.network_sync_wall_seconds].iter().any(|seconds|
                    !seconds.is_finite() || *seconds < 0.0)) ||
            config.hivemind.as_ref().is_some_and(|net|
                net.reconnect_game_id.is_some() &&
                net.reconnect_game_id != cursor.network_game_id)
        {
            return Err(invalid("native launcher cursor does not match the authored run or recoverable network ownership").into());
        }
    }

    // Historical host checkpoints predating a durable transcript recover
    // the original World without fabricating the lost beginning of a replay.
    let trace_output = output.filter(|_|
        recording_allowed && resume_cursor.as_ref().is_none_or(|cursor|
            cursor.recording.is_some()));
    let mut policy_prefix_hasher: Option<NativeRecordedPrefixHasher> = None;
    let mut model = RolloutModel::default();
    if let (Some(path), Some(trace), Some((_, _, _, manifest_digest))) =
        (replay_inputs, playback.as_ref(), model_source.as_ref())
    {
        let actions = PolicyActionPlayback::open(&path.with_file_name("policy-actions.bin"),
            trace.policy_actions_sha256.as_deref().expect("validated policy trace digest"))?;
        model.playback = Some((actions, manifest_digest.clone()));
    }
    // An offline recording restores only the initial connection allocator
    // snapshot, never the original live account's current checkpoint.
    // Every later request hash is then reallocated by the existing owner.
    if let Some(expected) = playback.as_ref()
        .and_then(|trace| trace.hivemind_start_checkpoint_sha256.as_ref())
    {
        let source = replay_inputs.expect("recorded HiveMind playback input")
            .with_file_name("hivemind-start-checkpoint.json");
        let bytes = fs::read(&source)?;
        if format!("{:x}", Sha256::digest(&bytes)) != *expected {
            return Err(invalid("recorded HiveMind starting checkpoint changed").into());
        }
        let mut file = fs::OpenOptions::new().write(true).create_new(true)
            .open(&checkpoint)?;
        file.write_all(&bytes)?;
        file.sync_all()?;
    }
    // Reconnecting to an existing server Game must also resume the original
    // hash allocator and pending StoreCommands ledger. A journal-free
    // reconnect is still recovery: creating a fresh checkpoint would lose
    // unresolved command credits while claiming the old Game identity.
    let restoring_connection =
        saved_host_checkpoint.is_some() ||
        !config.recover_notifications.is_empty() ||
        !config.recover_outcome_journals.is_empty() ||
        config.hivemind.as_ref().is_some_and(|network|
            network.reconnect_game_id.is_some());
    if saved_host_checkpoint.is_some() &&
        (!config.recover_notifications.is_empty() ||
         !config.recover_outcome_journals.is_empty())
    {
        return Err(invalid("native World continuation cannot also import independent outcome journals").into());
    }
    let mut connection = if restoring_connection {
        DurableHiveMindConnection::open_existing(&checkpoint)
    } else {
        DurableHiveMindConnection::open(&checkpoint)
    }.map_err(|error| contextual("HiveMind checkpoint", error))?;
    // Validate the independently durable network ledger BEFORE opening
    // either diagnostic stream. Only then may the sink discard frames
    // recorded after this committed World/Level checkpoint.
    if let Some(saved) = &saved_host_checkpoint {
        saved.validate_connection_for_recovery(&connection)
            .map_err(|error| contextual("native connection checkpoint boundary", error))?;
    }
    for previous in &config.recover_notifications {
        let path = resolve(root, previous);
        if path == notifications || path == checkpoint {
            return Err(invalid("recovery journals must be distinct from new outputs").into());
        }
        let recovered = recover_command_outcomes(&path, &mut connection)
            .map_err(|error| contextual("outcome journal recovery", error))?;
        println!("{}", json!({ "kind": "outcome_journal_recovered", "journal": path,
            "recovery": recovered }));
    }

    for previous in &config.recover_outcome_journals {
        let path = resolve(root, &previous.path);
        if path == notifications || path == checkpoint {
            return Err(invalid("recovery journals must be distinct from new outputs").into());
        }
        let recovered = bees_host::journal_recovery::replay_command_outcomes(&path, &previous.run_id,
            |recorded| connection.queue_journal_outcomes(recorded).map(|request| request.is_some()))
            .map_err(|error| contextual("schema1 outcome journal recovery", error))?;
        println!("{}", json!({"kind":"outcome_journal_recovered","journal":path,
            "newly_checkpointed":recovered.newly_checkpointed,"already_checkpointed":recovered.already_checkpointed}));
    }

    if policy_capture.is_some() && model_source.is_none() {
        return Err(invalid("policy capture requires a resident model worker").into());
    }
    if let Some((python, worker, manifest, expected_sha)) = model_source.filter(|_| replay_inputs.is_none()) {
        let active_manifest = resume_cursor.as_ref()
            .and_then(|cursor| cursor.next_model_update.checked_sub(1))
            .map(|index| resolve(root, &config.model_updates[index].manifest))
            .unwrap_or(manifest);
        let active_sha256 = if resume_cursor.as_ref().is_some_and(|cursor|
            cursor.next_model_update > 0)
        {
            let bytes = fs::read(&active_manifest)?;
            let data: Value = serde_json::from_slice(&bytes)?;
            let mut active_slots = HashSet::new();
            for item in data.get("models").and_then(Value::as_array)
                .ok_or_else(|| invalid("restored policy manifest has no models array"))?
            {
                let slot = item.get("slot").and_then(Value::as_u64)
                    .and_then(|slot| u32::try_from(slot).ok())
                    .ok_or_else(|| invalid("restored policy model slot is not uint32"))?;
                if !active_slots.insert(slot) {
                    return Err(invalid("restored policy manifest repeats a model slot").into());
                }
            }
            if active_slots != declared {
                return Err(invalid("restored policy manifest changed the originally authorized model slots").into());
            }
            format!("{:x}", Sha256::digest(bytes))
        } else { expected_sha };
        let mut resident = ResidentPolicyProcess::python_worker(
            python, worker, &active_manifest, policy_capture.is_some(),
        ).map_err(|error| contextual("model worker startup", error))?;
        if resident.model_manifest_sha256() != active_sha256 ||
            resume_cursor.as_ref().is_some_and(|cursor|
                cursor.segment_manifest_sha256.as_ref() != Some(&active_sha256))
        {
            return Err(invalid(
                "model manifest changed between route preflight and authenticated worker startup",
            ).into());
        }
        if let Some(cursor) = &resume_cursor {
            resident.bind_recovered_generation(cursor.segment_generation)
                .map_err(|error| contextual("recovered model generation", error))?;
        }
        model.resident = Some(resident);
        if let Some(directory) = trace_output {
            let path = directory.join("policy-actions.bin");
            if let Some(saved) = resume_cursor.as_ref()
                .and_then(|cursor| cursor.recording.as_ref())
            {
                let prefix = saved.policy_actions.as_ref().ok_or_else(||
                    invalid("recovered policy game lacks its committed action stream"))?;
                let (file, hasher) = NativeRecordedPrefixHasher::recover(&path, prefix)?;
                policy_prefix_hasher = Some(hasher);
                model.recorder = Some(PolicyActionRecorder::resume(file));
            } else {
                model.recorder = Some(PolicyActionRecorder::create(&path)?);
                policy_prefix_hasher = Some(NativeRecordedPrefixHasher::new());
            }
        }
    }
    let mut sink = if let Some(snapshot) = &saved_host_checkpoint {
        DurableDiagnosticNotifications::open_existing(
            &notifications, &config.run_id, snapshot.notifications(),
            policy_capture.as_deref(),
        )?
    } else {
        DurableDiagnosticNotifications::create_new(&notifications, config.run_id.clone())?
    };
    if let Some(path) = policy_capture.as_ref().filter(|_|
        saved_host_checkpoint.is_none())
    {
        sink.capture_policy_to(path)?;
    }
    let mut host = assets.build_imported_policy_runtime(
        launches, model, connection, sink,
    ).map_err(|error| contextual("native Level construction", error))?;
    if let Some(workers) = navigation_workers {
        for index in 0..config.levels.len() {
            host.edit_level(index, |state, _| {
                state.metadata.enable_navigation_workers(workers)
            }).map_err(|error| contextual("navigation Level setup", error))?
              .map_err(|error| contextual("navigation worker startup", error))?;
        }
    }
    if let Some(snapshot) = saved_host_checkpoint {
        host.restore_recovery_checkpoint(snapshot)
            .map_err(|error| contextual("native World/Level/journal recovery", error))?;
    } else {
        for (index, level) in config.levels.iter().enumerate() {
            bind_evaluation_episode(
                &mut host, index, level, level.episode_seed(0), &source_digests[index],
                &gameplay_digest, 0, config.decision_period,
            )?;
        }
    }
    host.set_timing_sample_period(timing);
    let recorded_inputs = trace_output.map(|directory| directory.join("player-inputs.jsonl"));
    let hivemind_start_checkpoint_sha256 = if recorded_inputs.is_some() &&
        config.hivemind.is_some() && resume_cursor.is_none()
    {
        let bytes = fs::read(&checkpoint)?;
        let digest = format!("{:x}", Sha256::digest(&bytes));
        let source = output.expect("recorded native battle output")
            .join("hivemind-start-checkpoint.json");
        let mut file = fs::OpenOptions::new().write(true).create_new(true)
            .open(source)?;
        file.write_all(&bytes)?;
        file.sync_all()?;
        Some(digest)
    } else { None };
    let mut trace_prefix_hasher: Option<NativeRecordedPrefixHasher> = None;
    let mut input_trace = if let Some(path) = &recorded_inputs {
        if let Some(saved) = resume_cursor.as_ref()
            .and_then(|cursor| cursor.recording.as_ref())
        {
            let (file, hasher) =
                NativeRecordedPrefixHasher::recover(path, &saved.input_trace)?;
            trace_prefix_hasher = Some(hasher);
            Some(file)
        } else {
            let mut trace = fs::OpenOptions::new().write(true).create_new(true)
                .open(path)?;
            writeln!(trace, "{}", json!({
                "kind": "player_input_trace",
                "schema_version": 5,
                "hivemind_start_checkpoint_sha256": hivemind_start_checkpoint_sha256,
                "run_id": config.run_id,
                "run_config_sha256": config_digest,
                "gameplay_config_sha256": gameplay_digest,
                "policy_manifest_sha256": host.model_mut().model_manifest_sha256(),
                "levels": trace_levels,
            }))?;
            trace_prefix_hasher = Some(NativeRecordedPrefixHasher::new());
            Some(trace)
        }
    } else { None };
    let mut replay_network = config.hivemind.as_ref()
        .filter(|_| playback.is_some())
        .map(|settings| RecordedNetwork::start(
            settings, &config.levels, &source_fixed_dt_by_level, &mut host,
        )).transpose()?;
    let mut network = config.hivemind.as_ref()
        .filter(|_| playback.is_none())
        .map(|settings| RunNetwork::start(
            settings, &config.levels, &source_fixed_dt_by_level, host.connection_mut(),
            resume_cursor.as_ref().and_then(|cursor| cursor.network_game_id),
        )).transpose()?;
    if let Some(cursor) = &resume_cursor {
        match (network.as_mut(), cursor.network_schedule.as_ref()) {
            (Some(network), Some(saved)) => network.scheduler
                .restore_recovery_checkpoint(saved.clone())?,
            (None, None) => {},
            _ => return Err(invalid("source HiveMind timer ownership differs from recovered native run").into()),
        }
        if let (Some(network), Some(saved)) = (network.as_mut(), cursor.recording.as_ref()) {
            network.recorded_network_events = saved.network_events;
            network.recorded_network_syncs = saved.network_syncs;
            network.recorded_network_sync_wall_seconds =
                saved.network_sync_wall_seconds;
        }
    }
    if remote_step_interval.is_some() && (config.levels.len() != 1 || playback.is_some()) {
        return Err(invalid("remote co-op requires one live Level, not multi-world rollout or replay").into());
    }
    let local_player_side = host.render_world(0)
        .and_then(|view| view.player_authority.player_viewer_side()).unwrap_or(0);
    // A dedicated authoritative host may have no local window/player side.
    // Explicit per-side tokens already select the authenticated remote
    // players, with each source squad verified below. Only the legacy
    // single-token cooperative mode needs an authored local player side.
    if remote_step_interval.is_some() && !(1..=2).contains(&local_player_side) &&
        env::var_os("BEES_NATIVE_REMOTE_SIDE_TOKENS").is_none()
    {
        return Err(invalid(
            "cooperative remote play requires an authored local player side; dedicated hosts must provide BEES_NATIVE_REMOTE_SIDE_TOKENS",
        ).into());
    }
    let mut remote = bees_host::remote_play::NativeRemotePlay::from_environment(
        local_player_side,!play,
    )?;
    // Dedicated hosted campaigns have no local window to advance the
    // opening story. Their authenticated campaign owner must be able to
    // receive the briefing before the first physical tick is released.
    if !play {
        if let (Some(server), Some(view)) = (remote.as_ref(),host.render_world(0)) {
            if let (Some(owner),Some((_,cue))) =
                (view.campaign_dialogue_side,view.campaign_dialogue)
            {
                if view.tick==0 && view.terminal_result.is_none() &&
                    cue.is_briefing() &&
                    !server.configured_sides().any(|side|side==owner) {
                    return Err(invalid(
                        "hosted campaign briefing requires an authenticated token for its authored player side",
                    ).into());
                }
            }
        }
    }
    if let Some(cursor) = &resume_cursor {
        match (remote.as_mut(), cursor.remote_play.as_ref()) {
            (Some(server), Some(saved)) => {
                let world = host.simulation().world(0)
                    .ok_or_else(|| invalid("recovered native multiplayer Level disappeared"))?;
                server.restore_recovery_checkpoint(
                    saved.clone(), world.id, world.episode_revision(),
                ).map_err(|error| contextual("native multiplayer session recovery", error))?;
            }
            (None, None) => {}
            _ => return Err(invalid(
                "recovered multiplayer side transport does not match the original host",
            ).into()),
        }
    }
    if let Some(server) = &mut remote {
        server.set_music_location(remote_music_location);
    }
    if let Some(server) = &remote {
        let world = host.render_world(0)
            .ok_or_else(|| invalid("remote player Level disappeared"))?;
        for side in server.configured_sides() {
            if !world.roster.active_lifetimes().any(|owner|
                world.roster.get(owner).is_some_and(|squad| squad.side == side) &&
                world.player_authority.player_permissions(owner)
                    .is_some_and(|permission| permission.user_controlled)
            ) {
                return Err(invalid(format!(
                    "remote player side {side} has no authored user-controlled squad in the live Level",
                )).into());
            }
        }
    }
    let mut remote_deadline = Instant::now();
    println!("{}", json!({
        "kind": "run_started",
        "run_id": config.run_id,
        "stage_name": config.stage_name,
        "worlds": config.levels.len(),
        "group_worlds": config.levels.iter()
            .filter(|level| level.groups.is_some()).count(),
        "authenticated_group_agents": config.levels.iter()
            .filter_map(|level| level.groups.as_ref())
            .map(|group| group.participants.len()).sum::<usize>(),
        "episodes_per_world": config.episodes_per_world,
        "scheduled_model_updates": config.model_updates.len(),
        "policy_generation": host.model_mut().model_generation(),
        "policy_manifest_sha256": host.model_mut().model_manifest_sha256(),
        "policy_behavior_capture": policy_capture.is_some(),
        "decision_period": config.decision_period,
        "delivery_every": config.delivery_every,
        "physics_workers": physical_workers.get(),
        "navigation_workers_per_level": navigation_workers.unwrap_or(0),
        "timing_sample_period": config.timing_sample_period,
        "interactive_view": view,
        "remote_play_enabled": remote.is_some(),
        "source_hivemind_commands": config.hivemind.as_ref()
            .is_some_and(|settings| settings.issue_source_commands),
        "fixed_dt_by_world": config.levels.iter()
            .zip(source_fixed_dt_by_level.iter())
            .map(|(level, &dt)| (level.world_id, dt))
            .collect::<Vec<_>>(),
    }));

    let execution_start = Instant::now();
    let prior_wall_seconds = resume_cursor.as_ref()
        .map_or(0.0, |cursor| cursor.elapsed_wall_seconds);
    let prior_startup_seconds = resume_cursor.as_ref()
        .map_or(0.0, |cursor| cursor.elapsed_startup_seconds);
    let prior_execution_seconds = resume_cursor.as_ref()
        .map_or(0.0, |cursor| cursor.elapsed_execution_seconds);
    let status_every_rounds = config.status_every_rounds.unwrap_or(u64::from(window.get()));
    let mut successful_world_steps = 0_u64;
    let mut successful_policy_rows = 0_u64;
    let mut admission_snapshot_rows = 0_u64;
    let mut admission_snapshot_frames = 0_u64;
    let mut retirement_snapshot_rows = 0_u64;
    let mut retirement_snapshot_frames = 0_u64;
    let mut policy_boundary_capture_nanos = 0_u128;
    let mut parallel_physics_rounds = 0_u64;
    let mut parallel_physics_direct_rounds = 0_u64;
    let mut stage_id_serialized_rounds = 0_u64;
    let mut stage_id_serialized_arenas = 0_u64;
    let mut peak_parallel_physics_workers = 0_usize;
    let mut parallel_physics_worker_nanos = 0_u128;
    let mut rounds = 0_u64;
    let mut failed_window = None;
    let mut segment_start_round = 0_u64;
    let mut segment_baseline = host.sink_mut().measurements().clone();
    let mut segment_generation = host.model_mut().model_generation();
    let mut segment_manifest_sha256 = host.model_mut().model_manifest_sha256();
    let mut completed_episodes = vec![0_u32; config.levels.len()];
    // Each completed episode has its own CombatWorld; accumulate source
    // MapBorder contacts at that boundary before a recycled world resets
    // its counters. Include every headless arena, not only the selected UI.
    let mut map_border_entries = 0_u64;
    let mut map_border_movement_stops = 0_u64;
    let mut map_border_override_skips = 0_u64;
    let mut map_border_lethal_hits = 0_u64;
    let mut map_border_lethal_kills = 0_u64;
    let mut map_border_confinement_corrections = 0_u64;
    let mut map_border_velocity_clamps = 0_u64;
    let mut map_border_unfittable = 0_u64;
    let mut map_border_missing_profiles = 0_u64;
    // Keep exactly one cumulative receipt over recycled training arenas.
    // The event processor owns per-episode admissions and resets with its
    // world; collect completed episode totals only at the reset boundary.
    let mut past_reinforcement_arrivals =
        bees_gameplay::level_events::NativeReinforcementArrivals::default();
    let mut past_reinforcement_idle_ticks_skipped = 0_u64;
    let mut past_reinforcement_wakeup_scans = 0_u64;
    let mut past_queen_controllers =
        bees_host::policy_only_metadata::NativeQueenControllerMeasurements::default();
    let mut next_status_round = status_every_rounds;
    #[cfg(feature = "client")]
    let mut user_closed = false;
    #[cfg(feature = "client")]
    let mut client_step_budget = 1_u32;
    #[cfg(not(feature = "client"))]
    let client_step_budget = 1_u32;
    #[cfg(not(feature = "client"))]
    let user_closed = false;
    // A world may finish before other arenas and remain paused at a
    // model boundary. Count each physical episode revision exactly once.
    let mut counted_revisions = vec![None::<u64>; config.levels.len()];
    let mut next_model_update = 0usize;
    if let Some(cursor) = &resume_cursor {
        // This allocator is shared by every physical World and all Queen /
        // Beacon minion admission callbacks; install it after host recovery,
        // before any further simulation or player command can allocate.
        next_id.store(cursor.next_squad_item_id, Ordering::Relaxed);
        rounds = cursor.rounds;
        completed_episodes = cursor.completed_episodes.clone();
        counted_revisions = cursor.counted_revisions.clone();
        next_model_update = cursor.next_model_update;
        segment_start_round = cursor.segment_start_round;
        segment_baseline = cursor.segment_baseline.clone();
        segment_generation = cursor.segment_generation;
        segment_manifest_sha256 = cursor.segment_manifest_sha256.clone();
        next_status_round = cursor.next_status_round;
        successful_world_steps = cursor.successful_world_steps;
        successful_policy_rows = cursor.successful_policy_rows;
        admission_snapshot_rows = cursor.admission_snapshot_rows;
        admission_snapshot_frames = cursor.admission_snapshot_frames;
        retirement_snapshot_rows = cursor.retirement_snapshot_rows;
        retirement_snapshot_frames = cursor.retirement_snapshot_frames;
        policy_boundary_capture_nanos = cursor.policy_boundary_capture_nanos;
        parallel_physics_rounds = cursor.parallel_physics_rounds;
        parallel_physics_direct_rounds = cursor.parallel_physics_direct_rounds;
        stage_id_serialized_rounds = cursor.stage_id_serialized_rounds;
        stage_id_serialized_arenas = cursor.stage_id_serialized_arenas;
        peak_parallel_physics_workers = cursor.peak_parallel_physics_workers;
        parallel_physics_worker_nanos = cursor.parallel_physics_worker_nanos;
        map_border_entries = cursor.map_border_entries;
        map_border_movement_stops = cursor.map_border_movement_stops;
        map_border_override_skips = cursor.map_border_override_skips;
        map_border_lethal_hits = cursor.map_border_lethal_hits;
        map_border_lethal_kills = cursor.map_border_lethal_kills;
        map_border_confinement_corrections = cursor.map_border_confinement_corrections;
        map_border_velocity_clamps = cursor.map_border_velocity_clamps;
        map_border_unfittable = cursor.map_border_unfittable;
        map_border_missing_profiles = cursor.map_border_missing_profiles;
        past_reinforcement_arrivals = cursor.past_reinforcement_arrivals;
        past_reinforcement_idle_ticks_skipped = cursor.past_reinforcement_idle_ticks_skipped;
        past_reinforcement_wakeup_scans = cursor.past_reinforcement_wakeup_scans;
        past_queen_controllers = cursor.past_queen_controllers;
        println!("{}", json!({
            "kind": "native_host_recovered",
            "run_id": config.run_id,
            "rounds": rounds,
            "next_squad_item_id": cursor.next_squad_item_id,
            "completed_episodes": completed_episodes,
            "policy_generation": segment_generation,
        }));
    }
    // Physical signatures are trace-only. Sample at 64-step intervals,
    // at the start of the next input boundary *after* any model reset,
    // never per physics step or on every idle graphical frame.
    let saved_recording = resume_cursor.as_ref()
        .and_then(|cursor| cursor.recording.as_ref());
    let mut last_physical_checkpoint_round = saved_recording
        .and_then(|recording| recording.last_physical_checkpoint_round);
    let mut recorded_physical_checkpoints = saved_recording
        .map_or(0, |recording| recording.recorded_physical_checkpoints);
    let mut recorded_player_inputs = saved_recording
        .map_or(0, |recording| recording.recorded_player_inputs);
    // Timed only for opt-in replay recording; headless training creates
    // no recorder, counters or storage barriers on its physics hot path.
    let mut trace_checkpoint_syncs = saved_recording
        .map_or(0, |recording| recording.trace_checkpoint_syncs);
    let mut trace_checkpoint_sync_wall_seconds = saved_recording
        .map_or(0.0, |recording| recording.trace_checkpoint_sync_wall_seconds);
    let mut trace_input_syncs = saved_recording
        .map_or(0, |recording| recording.trace_input_syncs);
    let mut trace_input_sync_wall_seconds = saved_recording
        .map_or(0.0, |recording| recording.trace_input_sync_wall_seconds);
    let mut verified_physical_checkpoints = 0_u64;
    let mut verified_gameplay_checkpoints = 0_u64;
    // Do not rehash or fsync a large journal while a window is paused and
    // polling UI/network with no authoritative simulation progress.
    let mut checkpointed_round = resume_cursor.as_ref().map(|cursor| cursor.rounds);
    // Native remote input replies are intentionally transient. A successful
    // command is acknowledged only AFTER the same World, authentic peer
    // leases and synced replay prefix have been durably checkpointed.
    // If the host crashes first, recovery discards both the uncommitted
    // World changes and these unsent replies. Batch one tick's commands
    // into one checkpoint instead of serializing a World per input.
    let mut pending_remote_successes = Vec::<(u64, u64, &'static str)>::new();
    // Local gameplay uses the same durable World/trace boundary. Its UI
    // feedback must not promise a recoverable command before the checkpoint.
    let mut pending_local_feedback: Option<&'static str> = None;
    // One typed source of every launcher-owned progress field, reused for
    // regular and terminal persistence. The World and network journal
    // themselves remain owned by the native host runtime.
    macro_rules! capture_native_progress {
        () => {{
            // The immutable host checkpoint owns the exact synced prefix
            // of both recordings. A process crash can leave extra bytes,
            // but recovery validates and truncates them before appending.
            let recording = if let (Some(trace), Some(path), Some(hasher)) = (
                input_trace.as_mut(), recorded_inputs.as_ref(),
                trace_prefix_hasher.as_mut(),
            ) {
                let started = Instant::now();
                trace.sync_data()?;
                trace_checkpoint_sync_wall_seconds += started.elapsed().as_secs_f64();
                trace_checkpoint_syncs += 1;
                let input_trace_prefix = hasher.capture(path, trace.stream_position()?)?;
                let policy_actions = if let Some(recorder) = host.model_mut().recorder.as_mut() {
                    let bytes = recorder.checkpoint_position()?;
                    let tracker = policy_prefix_hasher.as_mut().ok_or_else(||
                        invalid("policy recorder lost its original recovery cursor"))?;
                    Some(tracker.capture(&path.with_file_name("policy-actions.bin"), bytes)?)
                } else { None };
                Some(NativeBattleRecordingCursor {
                    input_trace: input_trace_prefix,
                    policy_actions,
                    last_physical_checkpoint_round,
                    recorded_physical_checkpoints,
                    recorded_player_inputs,
                    trace_checkpoint_syncs,
                    trace_checkpoint_sync_wall_seconds,
                    trace_input_syncs,
                    trace_input_sync_wall_seconds,
                    network_events: network.as_ref()
                        .map_or(0, |network| network.recorded_network_events),
                    network_syncs: network.as_ref()
                        .map_or(0, |network| network.recorded_network_syncs),
                    network_sync_wall_seconds: network.as_ref()
                        .map_or(0.0, |network| network.recorded_network_sync_wall_seconds),
                })
            } else { None };
            let cursor = NativeBattleRecoveryCursor {
                schema_version: 1,
                run_id: config.run_id.clone(),
                config_sha256: config_digest.clone(),
                gameplay_sha256: gameplay_digest.clone(),
                source_sha256: source_digests.clone(),
                rounds,
                elapsed_wall_seconds: prior_wall_seconds + run_start.elapsed().as_secs_f64(),
                elapsed_startup_seconds: prior_startup_seconds +
                    execution_start.duration_since(run_start).as_secs_f64(),
                elapsed_execution_seconds: prior_execution_seconds +
                    execution_start.elapsed().as_secs_f64(),
                next_squad_item_id: next_id.load(Ordering::Relaxed),
                completed_episodes: completed_episodes.clone(),
                counted_revisions: counted_revisions.clone(),
                next_model_update,
                network_schedule: network.as_ref().map(|network|
                    network.scheduler.recovery_checkpoint()),
                network_game_id: network.as_ref().and_then(|network| network.server_game_id),
                remote_play: remote.as_ref().map(|server| {
                    let world = host.simulation().world(0)
                        .expect("native remote checkpoint always has one live Level");
                    server.recovery_checkpoint(world.id, world.episode_revision())
                }),
                recording,
                segment_start_round,
                segment_baseline: segment_baseline.clone(),
                segment_generation,
                segment_manifest_sha256: segment_manifest_sha256.clone(),
                next_status_round,
                successful_world_steps, successful_policy_rows,
                admission_snapshot_rows, admission_snapshot_frames,
                retirement_snapshot_rows, retirement_snapshot_frames,
                policy_boundary_capture_nanos, parallel_physics_rounds,
                parallel_physics_direct_rounds, stage_id_serialized_rounds,
                stage_id_serialized_arenas, peak_parallel_physics_workers,
                parallel_physics_worker_nanos, map_border_entries,
                map_border_movement_stops, map_border_override_skips,
                map_border_lethal_hits, map_border_lethal_kills,
                map_border_confinement_corrections, map_border_velocity_clamps,
                map_border_unfittable, map_border_missing_profiles,
                past_reinforcement_arrivals, past_reinforcement_idle_ticks_skipped,
                past_reinforcement_wakeup_scans, past_queen_controllers,
            };
            serde_json::to_value(cursor)
                .map_err(|error| contextual("native run cursor encoding", error))
        }};
    }
    // Derived from the same committed physical/learner cursor. This is a
    // small dashboard projection, never an alternative recovery authority.
    macro_rules! checkpoint_dashboard_progress {
        () => { json!({
            "schema_version": 1,
            "kind": "native_host_checkpoint_progress",
            "run_id": config.run_id,
            "rounds": rounds,
            "successful_world_steps": successful_world_steps,
            "successful_policy_rows": successful_policy_rows,
            "completed_episodes": completed_episodes.iter().map(|&count| u64::from(count)).sum::<u64>(),
            "model_generation": segment_generation,
            "elapsed_wall_seconds": prior_wall_seconds + run_start.elapsed().as_secs_f64(),
        }) };
    }
    'battle: loop {
        let recovery_interval = if policy_capture.is_some() ||
            (!play && remote_step_interval.is_none())
        {
            TRAINING_RECOVERY_ROUND_INTERVAL
        } else { GAMEPLAY_RECOVERY_ROUND_INTERVAL };
        let recovery_due = checkpointed_round.is_none_or(|previous|
            previous != rounds &&
                rounds.saturating_sub(previous) >= recovery_interval);
        if host_checkpoint_file.is_some() &&
            (recovery_due || !pending_remote_successes.is_empty() ||
                pending_local_feedback.is_some()) &&
            network.as_ref().is_none_or(|session| session.server_game_id.is_some() &&
                session.next_level == session.levels.len()) &&
            host.connection_mut().connection().pending_request_count() == 0
        {
            if let Some(file) = &host_checkpoint_file {
                // A stable boundary follows the previous round's episode
                // accounting, model transition and journal ACK.
                if let Some(server) = &mut remote {
                    server.record_input_checkpoint(pending_remote_successes.len());
                }
                let saved = capture_native_progress!()?;
                if let Err(error) = host.persist_recovery_checkpoint_with_launcher(file, saved) {
                    failed_window = Some(format!(
                        "native host checkpoint could not be committed: {error:?}"
                    ));
                    break 'battle;
                }
                if let Err(error) = file.persist_progress(&checkpoint_dashboard_progress!()) {
                    failed_window = Some(format!(
                        "native Hub progress could not be persisted: {error:?}"
                    ));
                    break 'battle;
                }
                checkpointed_round = Some(rounds);
                // This is the first boundary at which a remote player may
                // be told its input took effect. A previously acknowledged
                // command cannot disappear when replay and the World are
                // restored from the same committed checkpoint.
                if let Some(server) = &mut remote {
                    for (peer, request, feedback) in pending_remote_successes.drain(..) {
                        server.reply(peer, request, Ok(feedback));
                    }
                }
                #[cfg(feature = "client")]
                if let Some(client) = &mut client {
                    if let Some(feedback) = pending_local_feedback.take() {
                        client.report_move(feedback);
                    }
                }
            }
        }
        if let Some(trace) = &mut input_trace {
            if (rounds == 0 || rounds % 64 == 0) &&
                last_physical_checkpoint_round != Some(rounds)
            {
                for index in 0..host.simulation().world_count() {
                    if let Err(error) = writeln!(trace, "{}",
                        replay_world_checkpoint(&host, index, rounds)) {
                        failed_window = Some(format!("recording native physical checkpoint: {error}"));
                        break 'battle;
                    }
                    recorded_physical_checkpoints += 1;
                }
                // These complete physical/gameplay signatures are the
                // durable replay recovery boundary. Commit the whole
                // sampled set before advancing another authoritative tick.
                // Only opt-in interactive recording pays for this sync.
                let started = Instant::now();
                let synced = trace.sync_data();
                trace_checkpoint_sync_wall_seconds += started.elapsed().as_secs_f64();
                trace_checkpoint_syncs += 1;
                if let Err(error) = synced {
                    failed_window = Some(format!(
                        "persisting native physical checkpoint at round {rounds}: {error}"
                    ));
                    break 'battle;
                }
                last_physical_checkpoint_round = Some(rounds);
            }
        }
        if let Some(trace) = &mut playback {
            if let Err(error) = trace.load_round(rounds) {
                failed_window = Some(format!(
                    "reading native player trace at round {rounds}: {error}"
                ));
                break 'battle;
            }
            while trace.checkpoints.front().is_some_and(|entry| entry.round == rounds) {
                let entry = trace.checkpoints.pop_front()
                    .expect("checked next physical checkpoint");
                let Some(world) = (0..host.simulation().world_count())
                    .filter_map(|index| host.simulation().world(index))
                    .find(|world| world.id == entry.world_id) else {
                        failed_window = Some(format!(
                            "physical replay checkpoint world {} missing at round {rounds}",
                            entry.world_id.0,
                        ));
                        break 'battle;
                    };
                if world.episode_revision() != entry.episode_revision ||
                    world.tick() != entry.tick ||
                    physical_world_sha256(
                        world.id, world.episode_revision(), world.tick(),
                        &world.state.combat,
                    ) != entry.sha256
                {
                    failed_window = Some(format!(
                        "native physical state diverged at round {rounds}, world {}, episode {}, tick {}",
                        entry.world_id.0, entry.episode_revision, entry.tick,
                    ));
                    break 'battle;
                }
                verified_physical_checkpoints += 1;
                if let Some(expected) = &entry.gameplay_sha256 {
                    let actual = gameplay_world_sha256(
                        world.id, world.episode_revision(), world.tick(),
                        &world.state.combat, world.state.events.roster(),
                        world.state.events.commands(), &world.state.metadata,
                    );
                    if actual != *expected {
                        failed_window = Some(format!(
                            "native gameplay control diverged at round {rounds}, world {}, episode {}, tick {}",
                            entry.world_id.0, entry.episode_revision, entry.tick,
                        ));
                        break 'battle;
                    }
                    verified_gameplay_checkpoints += 1;
                }
            }
            if trace.checkpoints.front().is_some_and(|entry| entry.round < rounds) {
                failed_window = Some(format!(
                    "physical replay checkpoint was skipped before round {rounds}",
                ));
                break 'battle;
            }
            // Network delivery and player input may interleave several
            // times without advancing a paused/local window. Replay their
            // original file order, not two grouped per-round queues.
            while trace.actions.front().is_some_and(|entry| entry.round() == rounds) {
                match trace.actions.pop_front().expect("checked next native action") {
                    NativeTraceAction::Network(event) => {
                        let Some(replayer) = &mut replay_network else {
                            failed_window = Some("recorded HiveMind event has no connection".into());
                            break 'battle;
                        };
                        if let Err(error) = replayer.accept(&mut host, event) {
                            failed_window = Some(format!("recorded HiveMind input: {error}"));
                            break 'battle;
                        }
                    }
                    NativeTraceAction::Input(entry) => {
                        let (id, episode_revision) = entry.action.episode();
                        let matching_world = (0..host.simulation().world_count()).any(|index| {
                            host.simulation().world(index).is_some_and(|world| world.id == id &&
                                world.episode_revision() == episode_revision && world.tick() == entry.tick)
                        });
                        if !matching_world {
                            failed_window = Some(format!(
                                "player trace diverged at round {rounds}, world {}", id.0,
                            ));
                            break 'battle;
                        }
                        let applied = if let Some(side) = entry.remote_side {
                            apply_remote_side_input(&mut host, entry.action, side)
                        } else {
                            apply_player_input(&mut host, entry.action)
                        };
                        if let Err(error) = applied {
                            failed_window = Some(error);
                            break 'battle;
                        }
                    }
                }
            }
            if rounds == trace.end_round {
                if !trace.checkpoints.is_empty() {
                    failed_window = Some("unconsumed physical replay checkpoints at final round".to_owned());
                }
                break;
            }
        }
        if rounds == config.max_rounds { break; }
        // Poll before view pacing/input continues, so idle graphical frames
        // cannot starve acknowledgement or setup delivery.
        if let Some(network) = &mut network {
            if let Err(error) = network.poll(
                &mut host, input_trace.as_mut().map(|trace| (trace, rounds)),
            ) {
                failed_window = Some(error.to_string());
                break;
            }
        }
        // Both graphical and dedicated LAN hosts must withhold orders
        // until the original campaign briefing has finished. Only a
        // dedicated host needs remote acknowledgments to advance time.
        let remote_briefing = if remote.is_some() {
            host.render_world(0).filter(|view|view.tick==0 &&
                view.terminal_result.is_none()).and_then(|view|
                view.campaign_dialogue
                    .filter(|(_,cue)|cue.is_briefing())
                    .and_then(|(sequence,_)|
                        view.campaign_dialogue_side.map(|side|(side,sequence))))
        } else { None };
        // Network co-op enters through precisely the same authoritative
        // command dispatcher as the local window and recorded input replay.
        // Process it at this fixed-tick boundary, never during physics.
        if remote.is_some() {
            let world = host.simulation().world(0).expect("remote play has one Level");
            let world_id = world.id;
            let revision = world.episode_revision();
            let live_held_controllers: Vec<_> =
                world.state.live_held_fire_controllers().collect();
            let orders = remote.as_mut().expect("checked remote listener").poll(
                world_id, revision, &live_held_controllers,
                if play { None } else { remote_briefing },
            );
            for order in orders {
                // A story briefing blocks physical orders from both player
                // sides until its authored viewer releases the real Level.
                // End still frees an existing peer-owned held-fire gesture.
                if remote_briefing.is_some() &&
                    !matches!(&order.action, NativePlayerInput::HeldFire(input)
                        if matches!(input.action,
                            bees_gameplay::player_inputs::NativeHeldFireAction::End)) {
                    remote.as_mut().expect("remote listener").reply(
                        order.peer, order.request_id,
                        Err("campaign briefing is still being presented"));
                    continue;
                }
                if !remote_side_owns_input(&host, &order.action, order.side) {
                    remote.as_mut().expect("remote listener").reply(
                        order.peer, order.request_id,
                        Err("stale world, unauthorized side, or unavailable squad"));
                    continue;
                }
                // HiveMind may keep a request outstanding for several
                // ticks, preventing an atomic host checkpoint. Do not
                // retain an unbounded backlog of successful yet uncommitted
                // player replies. The client may retry a busy command;
                // End must still release real weapons even when full.
                if host_checkpoint_file.is_some() &&
                    pending_remote_successes.len() >= 256 &&
                    !matches!(&order.action, NativePlayerInput::HeldFire(input)
                        if matches!(&input.action,
                            bees_gameplay::player_inputs::NativeHeldFireAction::End))
                {
                    let server = remote.as_mut().expect("remote listener");
                    server.record_checkpoint_backpressure();
                    server.reply(
                        order.peer, order.request_id,
                        Err("native host checkpoint pending; retry command"));
                    continue;
                }
                if let Some(trace) = &mut input_trace {
                    let tick = host.simulation().world(0).expect("checked remote World").tick();
                    let committed = writeln!(trace, "{}", json!({
                        "kind": "player_input", "round": rounds,
                        "tick": tick, "action": &order.action,
                        "remote_side": order.side,
                    }));
                    let committed = if committed.is_ok() {
                        let started = Instant::now();
                        let synced = trace.sync_data();
                        trace_input_sync_wall_seconds += started.elapsed().as_secs_f64();
                        trace_input_syncs += 1;
                        synced
                    } else { committed };
                    if let Err(error) = committed {
                        failed_window = Some(format!("persisting remote player input: {error}"));
                        break 'battle;
                    }
                    // Do not modify the actual Level or send success to a
                    // multiplayer peer before its authenticated command
                    // has become a durable replay event.
                    recorded_player_inputs += 1;
                }
                match apply_remote_side_input(&mut host, order.action, order.side) {
                    Ok(feedback) if feedback.accepted => {
                        if host_checkpoint_file.is_some() {
                            pending_remote_successes.push((
                                order.peer, order.request_id, feedback.message,
                            ));
                        } else {
                            remote.as_mut().expect("remote listener").reply(
                                order.peer, order.request_id, Ok(feedback.message),
                            );
                        }
                    }
                    Ok(feedback) => {
                        remote.as_mut().expect("remote listener").reply(
                            order.peer, order.request_id, Err(feedback.message),
                        );
                    }
                    Err(error) => {
                        remote.as_mut().expect("remote listener").reply(
                            order.peer, order.request_id, Err("authoritative input failed"),
                        );
                        failed_window = Some(error);
                        break 'battle;
                    }
                }
            }
            // The local window may still be displaying its own briefing;
            // deliver the initial paused state to newly authenticated LAN
            // peers without advancing physics to make a snapshot.
            if remote_briefing.is_some() {
                if let Some(view) = host.render_world(0) {
                    remote.as_mut().expect("remote listener")
                        .broadcast_initial_if_pending(&view, client_bounds[0]);
                }
            }
        }
        #[cfg(feature = "client")]
        if let Some(client) = &mut client {
            // Borrow the real native Level for rendering with precisely
            // this local commander's perspective. The override is cleared
            // BEFORE any world step, fingerprint or network delivery, so
            // UI-only hot-seat selection never changes game physics.
            let side = client.hotseat_side();
            if let Some(side) = side {
                if let Err(error) = host.edit_level(client.selected_world(), |state, _|
                    state.metadata.set_remote_player_side(Some(side))
                ) {
                    failed_window = Some(format!("native local viewer setup: {error:?}"));
                    break;
                }
            }
            let observed = host.render_world(client.selected_world()).map(|current| {
                let tick = current.tick;
                let action = client.poll(current, client_bounds[client.selected_world()],
                    host.simulation().world_count(),
                    client_step_interval_by_level[client.selected_world()]);
                (tick, action)
            });
            if side.is_some() {
                if let Err(error) = host.edit_level(client.selected_world(), |state, _|
                    state.metadata.set_remote_player_side(None)
                ) {
                    failed_window = Some(format!("native local viewer cleanup: {error:?}"));
                    break;
                }
            }
            let Some((tick, action)) = observed else {
                failed_window = Some("selected Level disappeared".to_owned());
                break;
            };
            // A window shows one status message. Coalesce uncommitted
            // success feedback without rejecting a held-fire transition:
            // its gestures are already owned by the native game window.
            if let (Some(trace), Ok(bees_host::client::NativeClientAction::Input { action: input, .. })) =
                (&mut input_trace, &action)
            {
                // The existing native trace format already stores a
                // per-input authenticated side for remote play. Reusing
                // that contract allows a local two-commander battle to
                // replay both players' commands without recording F9's
                // purely visual selection state.
                let mut entry = json!({
                    "kind": "player_input", "round": rounds,
                    "tick": tick, "action": input,
                });
                if let Some(side) = side { entry["remote_side"] = json!(side); }
                let committed = writeln!(trace, "{entry}");
                let committed = if committed.is_ok() {
                    let started = Instant::now();
                    let synced = trace.sync_data();
                    trace_input_sync_wall_seconds += started.elapsed().as_secs_f64();
                    trace_input_syncs += 1;
                    synced
                } else { committed };
                if let Err(error) = committed {
                    failed_window = Some(format!("persisting player input: {error}"));
                    break;
                }
                recorded_player_inputs += 1;
            }
            match action {
                Ok(bees_host::client::NativeClientAction::Wait |
                    bees_host::client::NativeClientAction::WorldChanged |
                    bees_host::client::NativeClientAction::SideChanged) => continue,
                Ok(bees_host::client::NativeClientAction::Step) => {
                    client_step_budget = client.pending_steps();
                },
                Ok(bees_host::client::NativeClientAction::Input { action: input, step }) => {
                    let result = if let Some(side) = side {
                        apply_remote_side_input(&mut host, input, side)
                    } else { apply_player_input(&mut host, input) };
                    match result {
                        Ok(feedback) if feedback.accepted && host_checkpoint_file.is_some() => {
                            pending_local_feedback = Some(feedback.message);
                        },
                        Ok(feedback) => client.report_move(feedback.message),
                        Err(error) => {
                            failed_window = Some(error);
                            break;
                        },
                    }
                    if !step { continue; }
                    client_step_budget = client.pending_steps();
                },
                Ok(bees_host::client::NativeClientAction::Quit) => { user_closed = true; break; },
                Err(error) => { failed_window = Some(format!("native window: {error}")); break; },
            }
        }
        // The dedicated LAN server has no local presentation tick.
        // While one or more connected story owners are reading the
        // briefing, keep polling its normal nonblocking network transport
        // but do not step a shadow World or change the fixed-step clock.
        if let (Some(server),Some((owner,sequence))) =
            (remote.as_mut().filter(|_| !play),remote_briefing)
        {
            let world=host.simulation().world(0).expect("hosted briefing Level");
            if server.briefing_waiting(world.id,world.episode_revision(),
                owner,sequence)
            {
                std::thread::sleep(std::time::Duration::from_millis(16));
                remote_deadline=Instant::now();
                continue 'battle;
            }
        }
        let until_update = config.model_updates.get(next_model_update)
            .filter(|item| item.at_round > rounds)
            .map_or(config.max_rounds, |item| item.at_round);
        // Treat at_round as the earliest eligibility point. Completing
        // the current episodes before reloading prevents mixed-model
        // evaluation outcomes, even if episodes have different lengths.
        let remaining = (config.max_rounds - rounds)
            .min(until_update - rounds);
        let source_pulse_limit = if let Some(network) = &mut network {
            let scheduling = network.issue_due_source_commands(&mut host)
                .and_then(|()| network.rounds_until_next_source_pulse(&host));
            match scheduling {
                Ok(limit) => limit,
                Err(error) => {
                    failed_window = Some(error.to_string());
                    break;
                }
            }
        } else if let Some(replayer) = &mut replay_network {
            match replayer.issue_due(&mut host) {
                Ok(limit) => limit,
                Err(error) => {
                    failed_window = Some(format!("recorded HiveMind command timer: {error}"));
                    break;
                }
            }
        } else { u64::MAX };
        // Player traces require their bitwise checkpoints at exact 64-round
        // boundaries. A catch-up batch must not skip across one. All other
        // interactive rounds still run the ordinary fixed-step host pipeline.
        let checkpoint_limit = if input_trace.is_some() { 64 - rounds % 64 } else { u64::MAX };
        let count = nonzero(remaining.min(source_pulse_limit).min(checkpoint_limit)
            .min(u64::from(if remote.is_some() { 1 }
                else if view || playback.is_some() { client_step_budget }
                else { window.get() })) as u32, "window")?;
        let physical_result = if !view && playback.is_none() &&
            physical_workers.get() > 1 && config.levels.len() > 1
        {
            host.run_window_parallel(count, delivery, physical_workers)
        } else {
            host.run_window(count, delivery)
        };
        let counts = match physical_result {
            Ok(counts) => counts,
            Err(error) => {
                // The partial world/trajectory is never counted as a
                // successful window. Retain the cause, then use the same
                // authored cancellation path as a finite-budget stop.
                failed_window = Some(format!("{error:?}"));
                break;
            }
        };
        rounds += u64::from(counts.rounds);
        if let Some(server) = &mut remote {
            if let Some(world) = host.render_world(0) {
                server.broadcast(&world, client_bounds[0]);
            }
        }
        // An interactive remote host is real-time. Ordinary headless PPO
        // remains unpaced and never constructs or polls this socket.
        if !view {
            if let Some(interval) = remote_step_interval {
                remote_deadline += interval;
                let now = Instant::now();
                if remote_deadline > now {
                    std::thread::sleep(remote_deadline - now);
                } else if now.duration_since(remote_deadline) > interval * 4 {
                    remote_deadline = now;
                }
            }
        }
        #[cfg(feature = "client")]
        if let Some(client) = &mut client {
            client.commit_steps(counts.rounds, client_step_interval_by_level[client.selected_world()]);
        }
        successful_world_steps += counts.world_steps as u64;
        successful_policy_rows += counts.policy_rows as u64;
        admission_snapshot_rows += counts.admission_snapshot_rows as u64;
        admission_snapshot_frames += counts.admission_snapshot_frames as u64;
        retirement_snapshot_rows += counts.retirement_snapshot_rows as u64;
        retirement_snapshot_frames += counts.retirement_snapshot_frames as u64;
        policy_boundary_capture_nanos += counts.policy_boundary_capture_nanos;
        parallel_physics_rounds += u64::from(counts.parallel_physics_rounds);
        parallel_physics_direct_rounds +=
            u64::from(counts.parallel_physics_direct_rounds);
        stage_id_serialized_rounds += u64::from(counts.parallel_stage_id_serialized_rounds);
        stage_id_serialized_arenas += counts.parallel_stage_id_serialized_arenas as u64;
        peak_parallel_physics_workers = peak_parallel_physics_workers
            .max(counts.parallel_physics_max_workers);
        parallel_physics_worker_nanos += counts.parallel_physics_worker_nanos;
        // Pause completed worlds while the slowest active arena reaches
        // the same model-change boundary. A physical episode must never
        // contribute a partially old/partially new benchmark result.
        let completion = (|| -> io::Result<bool> {
            let mut all_finished = true;
            for index in 0..config.levels.len() {
                let world = host.simulation().world(index)
                    .ok_or_else(|| invalid("registered Level disappeared"))?;
                if world.state.events.was_aborted() || world.is_failed() ||
                    world.state.events.is_failed()
                {
                    return Err(invalid("failed or aborted world cannot satisfy a model boundary"));
                }
                if !world.state.events.completed() {
                    all_finished = false;
                    continue;
                }
                let revision = world.episode_revision();
                if counted_revisions[index] != Some(revision) {
                    if completed_episodes[index] >= config.episodes_per_world {
                        return Err(invalid("world exceeded its configured episode budget"));
                    }
                    // Copy while the immutable World borrow is live.
                    // Host terminal capture below needs a mutable sink.
                    let borders = world.state.combat.map_border_measurements();
                    if policy_capture.is_some() {
                        let (id, tick) = (world.id, world.tick());
                        let observations = host.terminal_observations(index)
                            .map_err(|error| contextual("terminal policy observations", error))?;
                        host.sink_mut().capture_terminal_policy(id, revision, tick, &observations)?;
                    }
                    map_border_entries += borders.ship_entries;
                    map_border_movement_stops += borders.movement_stops;
                    map_border_override_skips += borders.override_skips;
                    map_border_lethal_hits += borders.lethal_hits;
                    map_border_lethal_kills += borders.lethal_kills;
                    map_border_confinement_corrections +=
                        borders.confinement_position_corrections;
                    map_border_velocity_clamps += borders.confinement_velocity_clamps;
                    map_border_unfittable += borders.confinement_unfittable_hulls;
                    map_border_missing_profiles += borders.confinement_missing_profiles;
                    completed_episodes[index] += 1;
                    counted_revisions[index] = Some(revision);
                }
            }
            Ok(all_finished)
        })();
        let all_finished = match completion {
            Ok(value) => value,
            Err(error) => {
                failed_window = Some(format!("episode accounting: {error}"));
                break;
            }
        };
        let update_due = config.model_updates.get(next_model_update)
            .is_some_and(|item| rounds >= item.at_round);
        if update_due && all_finished {
            if rounds == config.max_rounds {
                failed_window = Some(
                    "scheduled model change reached episode boundary only at the exhausted run budget".into(),
                );
                break;
            }
            if completed_episodes.iter().all(|&finished|
                finished >= config.episodes_per_world
            ) {
                failed_window = Some(format!(
                    "model update requested at round {rounds} but no future episodes remain",
                ));
                break;
            }
            // An overrun may have crossed another scheduled threshold
            // while slower worlds finished. Never claim an intermediate
            // checkpoint was meaningfully evaluated when it ran zero
            // simulated rounds.
            if config.model_updates.get(next_model_update + 1)
                .is_some_and(|item| rounds >= item.at_round)
            {
                failed_window = Some(format!(
                    "model schedule thresholds crossed before an episode boundary at round {rounds}",
                ));
                break;
            }
            let update = &config.model_updates[next_model_update];
            let previous_generation = host.model_mut().model_generation();
            let evaluation_before_update =
                host.sink_mut().measurements().clone();
            let completed_segment = match evaluation_before_update
                .delta_since(&segment_baseline)
            {
                Some(segment) => segment,
                None => {
                    failed_window = Some("durable evaluation counters regressed".into());
                    break;
                }
            };
            match host.model_mut().reload_manifest(
                &resolve(root, &update.manifest),
            ) {
                Ok(generation) => {
                    let manifest_sha256 =
                        host.model_mut().model_manifest_sha256();
                    let segment_mean =
                        completed_segment.mean_episode_seconds();
                    println!("{}", json!({
                        "kind": "policy_segment",
                        "run_id": config.run_id,
                        "policy_generation": segment_generation,
                        "policy_manifest_sha256": segment_manifest_sha256,
                        "from_round": segment_start_round,
                        "through_round": rounds,
                        "evaluation": completed_segment,
                        "mean_episode_seconds": segment_mean,
                    }));
                    println!("{}", json!({
                        "kind": "policy_updated",
                        "run_id": config.run_id,
                        "requested_round": update.at_round,
                        "rounds": rounds,
                        "previous_policy_generation": previous_generation,
                        "policy_generation": generation,
                        "policy_manifest_sha256": manifest_sha256,
                        "evaluation_before_update": evaluation_before_update,
                        "manifest": update.manifest,
                    }));
                    segment_baseline = evaluation_before_update;
                    segment_start_round = rounds;
                    segment_generation = generation;
                    segment_manifest_sha256 = manifest_sha256;
                    next_model_update += 1;
                }
                Err(error) => {
                    failed_window = Some(format!(
                        "scheduled policy update at episode boundary round {rounds}: {error:?}"
                    ));
                    break;
                }
            }
        }
        let holding_for_update = update_due && !all_finished;
        // The reset is independently guarded by the normal episode
        // delivery barrier. No completed world may be reset while its
        // peers are still finishing a checkpoint transition.
        let recycling = (|| -> io::Result<usize> {
            let mut recycled = 0usize;
            for (index, level) in config.levels.iter().enumerate() {
                let finished = host.simulation().world(index)
                    .ok_or_else(|| invalid("registered Level disappeared"))?
                    .state.events.completed();
                if !finished ||
                    holding_for_update ||
                    completed_episodes[index] >= config.episodes_per_world ||
                    rounds == config.max_rounds
                {
                    continue;
                }
                let started = Instant::now();
                let mut scene = source_scene_templates[index].as_ref().clone();
                recycled_template_clone_count += 1;
                recycled_template_clone_wall += started.elapsed();
                // Replaying an authored template creates new real Stage
                // squad lifetimes, not aliases of retired pooled wrappers.
                let mut remapped = HashMap::new();
                for squad in &mut scene.source_squads {
                    let item_id = take_stage_item_id(&next_id)
                        .ok_or_else(|| invalid("Stage squad identities exhausted"))?;
                    remapped.insert(squad.item_id, item_id);
                    squad.item_id = item_id;
                }
                let seed = level.episode_seed(completed_episodes[index]);
                if let Some(group) = &level.groups {
                    bind_group_routes(
                        &mut scene, group, completed_episodes[index], false,
                        seed,
                    )?;
                }
                let setup = make_setup(
                    &config, level, &assets, period, Arc::clone(&next_id), seed,
                    completed_episodes[index], source_sides[index], &remapped,
                )?;
                let authored = scene.into_exported_policy_only_level(setup)
                    .map_err(|error| contextual("replayed Level source", error))?;
                let mut replacement = assets.build_level(authored)
                    .map_err(|error| contextual("replayed Level assembly", error))?
                    .state;
                if let Some(workers) = navigation_workers {
                    replacement.metadata.enable_navigation_workers(workers)
                        .map_err(|error| contextual("episode navigation worker startup", error))?;
                }
                let old_world = host.simulation().world(index)
                    .ok_or_else(|| invalid("recycled world disappeared"))?;
                let prior_reinforcements = old_world.state.events.reinforcement_arrivals();
                let prior_idle_ticks = old_world.state.metadata.reinforcement_idle_ticks_skipped;
                let prior_wakeup_scans = old_world.state.metadata.reinforcement_wakeup_scans;
                let prior_queens = old_world.state.metadata.queen_controller_measurements;
                host.reset_world(index, seed, replacement)
                    .map_err(|error| contextual("guarded Level reset", error))?;
                // Count only a successful ownership transfer. If reset
                // fails, the original world remains the current snapshot;
                // merging it before reset would double-count at finalization.
                past_reinforcement_arrivals.merge(prior_reinforcements);
                past_reinforcement_idle_ticks_skipped += prior_idle_ticks;
                past_reinforcement_wakeup_scans += prior_wakeup_scans;
                past_queen_controllers.merge(prior_queens);
                bind_evaluation_episode(
                    &mut host, index, level, seed, &source_digests[index],
                    &gameplay_digest, completed_episodes[index], config.decision_period,
                )?;
                recycled += 1;
            }
            Ok(recycled)
        })();
        let recycled = match recycling {
            Ok(recycled) => recycled,
            Err(error) => {
                failed_window = Some(format!("episode turnover: {error}"));
                break;
            }
        };
        if rounds >= next_status_round || counts.stopped_with_no_live_worlds {
        next_status_round = rounds.saturating_add(status_every_rounds);
        let evaluation = host.sink_mut().measurements().clone();
        let mean_episode_seconds = evaluation.mean_episode_seconds();
        match host.sample_status() {
            Ok(Some(status)) => println!("{}", json!({
                "kind": "interval",
                "run_id": config.run_id,
                "rounds": rounds,
                "policy_generation": host.model_mut().model_generation(),
                "policy_manifest_sha256": host.model_mut().model_manifest_sha256(),
                "model_updates_applied": next_model_update,
                "next_model_update_at_round": config.model_updates
                    .get(next_model_update).map(|item| item.at_round),
                "awaiting_clean_episode_boundary": holding_for_update,
                "completed_episodes": completed_episodes.iter()
                    .map(|&count| u64::from(count)).sum::<u64>(),
                "evaluation": evaluation,
                "mean_episode_seconds": mean_episode_seconds,
                "metrics": status,
            })),
            Ok(None) => {},
            Err(error) => {
                failed_window = Some(format!(
                    "native host status after window: {error:?}"
                ));
                break;
            }
        }
        }
        if counts.stopped_with_no_live_worlds && holding_for_update {
            failed_window = Some(
                "model boundary has no active worlds but still lacks a completed episode".into(),
            );
            break;
        }
        if counts.stopped_with_no_live_worlds && recycled == 0 {
            // The final completed episode has no next loop iteration.
            // Commit that same terminal Level/journal/cursor boundary before
            // the immutable run receipt is assembled.
            if let Some(file) = &host_checkpoint_file {
                if host.connection_mut().connection().pending_request_count() == 0 {
                    if let Some(server) = &mut remote {
                        server.record_input_checkpoint(pending_remote_successes.len());
                    }
                    let saved = capture_native_progress!()?;
                    if let Err(error) = host.persist_recovery_checkpoint_with_launcher(file, saved) {
                        failed_window = Some(format!(
                            "native terminal host checkpoint could not be committed: {error:?}"
                        ));
                    } else if let Err(error) = file.persist_progress(&checkpoint_dashboard_progress!()) {
                        failed_window = Some(format!(
                            "native terminal Hub progress could not be persisted: {error:?}"
                        ));
                    } else {
                        checkpointed_round = Some(rounds);
                        // A completed Level has no next loop iteration.
                        // Its final, accepted remote player commands still
                        // need the same checkpoint-before-ACK guarantee.
                        if let Some(server) = &mut remote {
                            for (peer, request, feedback) in pending_remote_successes.drain(..) {
                                server.reply(peer, request, Ok(feedback));
                            }
                        }
                        #[cfg(feature = "client")]
                        if let Some(client) = &mut client {
                            if let Some(feedback) = pending_local_feedback.take() {
                                client.report_move(feedback);
                            }
                        }
                    }
                }
            }
            break;
        }
    }

    // The last physical world_state includes the source winner, objective
    // result and timeout. A headless multiplayer host stops ticking as soon
    // as that episode finishes, so explicitly drain the existing socket
    // queue before finalizing the immutable campaign/battle receipt.
    if failed_window.is_none() && !user_closed {
        if let Some(server) = &mut remote {
            if host.simulation().world(0)
                .is_some_and(|world| world.state.events.completed())
            {
                server.drain_terminal_output(std::time::Duration::from_millis(350));
            }
        }
    }

    if failed_window.is_none() && !user_closed && playback.as_ref().is_some_and(|trace|
        rounds != trace.end_round || !trace.actions.is_empty() ||
        !trace.checkpoints.is_empty()
    ) {
        failed_window = Some(format!("player trace ended at a different round than the battle ({rounds})"));
    }

    if failed_window.is_none() && next_model_update < config.model_updates.len() {
        failed_window = Some(format!(
            "{} scheduled policy updates were not reached before the run ended",
            config.model_updates.len() - next_model_update,
        ));
    }

    // A finite run budget is an intentional stop, NEVER a fake terminal
    // win or a completed PPO episode. Durable EpisodeAborted notifications
    // explicitly mark partial trajectories as unusable for learning.
    let count = host.simulation().world_count();
    // Fingerprint each Level once at the original execution boundary,
    // BEFORE finite-budget cancellation/abort notifications can alter
    // runtime state. This is opt-in summary output, not simulation work.
    // The exact same bitwise physical-world signature is used by replay.
    let final_gameplay_worlds = summary.as_ref().map(|_| {
        (0..count).filter_map(|index| {
            let world = host.simulation().world(index)?;
            Some(json!({
                "world_id": world.id.0,
                "episode_revision": world.episode_revision(),
                "tick": world.tick(),
                "sha256": gameplay_world_sha256(
                    world.id, world.episode_revision(), world.tick(),
                    &world.state.combat, world.state.events.roster(),
                    world.state.events.commands(), &world.state.metadata,
                ),
            }))
        }).collect::<Vec<_>>()
    });
    let final_physical_worlds = summary.as_ref().map(|_| {
        (0..count).filter_map(|index| {
            let world = host.simulation().world(index)?;
            Some(json!({
                "world_id": world.id.0,
                "episode_revision": world.episode_revision(),
                "tick": world.tick(),
                "sha256": physical_world_sha256(
                    world.id, world.episode_revision(), world.tick(),
                    &world.state.combat,
                ),
            }))
        }).collect::<Vec<_>>()
    });
    // A trace must cover the physical state of EVERY Level at its final
    // execution boundary, even when the game quits between the sampled
    // 64-round checkpoints. No gameplay owner is modified here.
    // Match the v4 reader contract before finite-budget cancellation.
    if let Some(trace) = &mut input_trace {
        if last_physical_checkpoint_round != Some(rounds) {
            for index in 0..count {
                if let Err(error) = writeln!(trace, "{}",
                    replay_world_checkpoint(&host, index, rounds)) {
                    failed_window.get_or_insert_with(||
                        format!("recording final native physical checkpoint: {error}")
                    );
                    break;
                }
                recorded_physical_checkpoints += 1;
            }
            // The final sample is useful even if later campaign, policy
            // recorder or notification finalization fails. Commit its
            // complete write before changing the Level's stop/abort state.
            let started = Instant::now();
            let synced = trace.sync_data();
            trace_checkpoint_sync_wall_seconds += started.elapsed().as_secs_f64();
            trace_checkpoint_syncs += 1;
            if let Err(error) = synced {
                failed_window.get_or_insert_with(||
                    format!("persisting final native physical checkpoint: {error}")
                );
            } else {
                last_physical_checkpoint_round = Some(rounds);
            }
        }
    }
    let finalization_start = Instant::now();
    let mut cleanup_errors = Vec::new();
    if failed_window.is_none() && !user_closed {
        if let Some((actions, _)) = &mut host.model_mut().playback {
            if let Err(error) = actions.finish() {
                failed_window = Some(format!("policy action playback: {error}"));
            }
        }
    }
    // Finish resident model actions before durable run finalization, but
    // do not certify the player trace yet. The replay library accepts a
    // final trace footer as proof of a complete battle: writing it before
    // notification/network cleanup or the campaign summary could publish
    // a replay for an unsuccessful or uncommitted session.
    let policy_actions_sha256 = if input_trace.is_some() {
        host.model_mut().recorder.take().and_then(|recorder| {
            match recorder.finish() {
                Ok(digest) => Some(digest),
                Err(error) => {
                    let message = format!("policy action trace: {error}");
                    failed_window.get_or_insert_with(|| message.clone());
                    cleanup_errors.push(message);
                    None
                }
            }
        })
    } else { None };
    if let Some(path) = &capture {
        // Captures are diagnostic output, never a replacement world or model
        // input. Failure joins cleanup reporting so live Levels still retire.
        let captured = (|| -> io::Result<()> {
            #[cfg(feature = "client")]
            let index = client.as_ref().map_or(0, |client| client.selected_world());
            #[cfg(not(feature = "client"))]
            let index = 0;
            let current = host.render_world(index)
                .ok_or_else(|| invalid("capture Level disappeared"))?;
            let mut renderer = NativeSoftwareRenderer::new(1100, 760, client_bounds[index])?;
            let counts = renderer.render(&current, client_bounds[index]);
            let mut file = fs::OpenOptions::new().write(true).create_new(true).open(path)?;
            renderer.write_ppm(&mut file)?;
            file.sync_all()?;
            println!("{}", json!({ "kind": "frame_capture", "run_id": config.run_id,
                "world_id": current.world_id.0, "episode_revision": current.episode_revision,
                "tick": current.tick, "path": path, "entities": counts }));
            Ok(())
        })();
        if let Err(error) = captured { cleanup_errors.push(format!("frame capture: {error}")); }
    }
    for index in 0..count {
        let Some(world) = host.simulation().world(index) else {
            cleanup_errors.push(format!("world {index}: disappeared"));
            continue;
        };
        if world.state.events.was_aborted() ||
            world.state.events.completed() {
            continue;
        }
        let kind = if world.is_failed() || world.state.events.is_failed() {
            NativeLevelStopKind::AbortFailed
        } else {
            NativeLevelStopKind::CancelLive
        };
        if let Err(error) = host.stop_world(index, kind) {
            cleanup_errors.push(format!(
                "world {index} final stop/delivery: {error:?}"
            ));
        }
    }
    if let Err(error) = host.sink_mut().sync() {
        cleanup_errors.push(format!("final notification sync: {error}"));
    }
    let mut socket_flush_timed_out = false;
    let mut socket_close_confirmed = false;
    if let Some(network) = &mut network {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(u64::from(network.flush_seconds));
        while failed_window.is_none() && cleanup_errors.is_empty() {
            let connection = host.connection_mut();
            if network.next_level == network.levels.len() &&
                connection.pending_store_hashes()
                    .map_err(|error| contextual("final pending outcomes", error))?.is_empty() &&
                connection.connection().pending_request_count() == 0
            {
                break;
            }
            if std::time::Instant::now() >= deadline { socket_flush_timed_out = true; break; }
            if let Err(error) = network.poll(&mut host, None) {
                cleanup_errors.push(error.to_string());
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(1));
        }
        // A bounded wait ending is not an acknowledgement. All remaining
        // original hashes stay in the checkpoint for a later connection.
        if failed_window.is_none() && cleanup_errors.is_empty() && !socket_flush_timed_out {
            match network.worker.request_close() {
                Ok(()) => {
                    while !network.worker.closed() && std::time::Instant::now() < deadline {
                        if let Err(error) = network.poll(&mut host, None) {
                            cleanup_errors.push(format!("HiveMind socket close: {error}"));
                            break;
                        }
                        if !network.worker.closed() {
                            std::thread::sleep(std::time::Duration::from_millis(1));
                        }
                    }
                    socket_close_confirmed = network.worker.closed();
                }
                Err(error) => cleanup_errors.push(format!("HiveMind socket close request: {error:?}")),
            }
        }
    }
    let status = host.runtime_status()
        .map_err(|error| contextual("final native host status", error))?;
    // A StoreCommands 409 commits its valid rows but retains the exact
    // stale reservations in the checkpoint for explicit reconciliation.
    // Surface that existing ledger in the durable run receipt so an
    // operator can identify the original Hash/OutcomeIds without replaying
    // the already-committed batch or guessing from a backlog count.
    let (pending_store_hashes, pending_store_reconciliation) = {
        let connection = host.connection_mut();
        // Retryable submissions and terminal 409 records are distinct.
        // Both sets of original request Hashes are machine-owned recovery
        // data; neither may be silently counted as successful settlement.
        let pending = connection.pending_store_hashes()
            .map_err(|error| contextual("final pending StoreCommands", error))?;
        let hashes = connection.reconciliation_hashes()
            .map_err(|error| contextual("final StoreCommands reconciliation", error))?;
        let mut records = Vec::with_capacity(hashes.len());
        for hash in hashes {
            let stale_ids = connection.stale_reconciliation_ids(hash)
                .map_err(|error| contextual("final stale reservations", error))?
                .ok_or_else(|| invalid("StoreCommands reconciliation lost its reservation IDs"))?;
            records.push(json!({
                "request_hash": hash,
                "stale_outcome_ids": stale_ids,
            }));
        }
        (pending, records)
    };
    if pending_store_hashes.len() != status.pending_store_commands ||
        pending_store_reconciliation.len() != status.pending_store_reconciliations
    {
        return Err(invalid("final StoreCommands gauges disagree with the durable connection ledger").into());
    }
    let evaluation = host.sink_mut().measurements().clone();
    let mean_episode_seconds = evaluation.mean_episode_seconds();
    let final_segment = evaluation.delta_since(&segment_baseline);
    let final_segment_mean = final_segment.as_ref()
        .and_then(|segment| segment.mean_episode_seconds());
    if final_segment.is_none() && failed_window.is_none() {
        failed_window = Some("durable evaluation counters regressed".into());
    }
    let mut captured_policy_rows = None;
    if failed_window.is_none() && cleanup_errors.is_empty()
        && completed_episodes.iter().all(|&finished| finished == config.episodes_per_world)
    {
        match host.sink_mut().finish_policy_capture(successful_policy_rows) {
            Ok(rows) => captured_policy_rows = rows,
            Err(error) => cleanup_errors.push(format!("policy capture finalization: {error}")),
        }
    }
    let policy_generation = host.model_mut().model_generation();
    let policy_manifest_sha256 = host.model_mut().model_manifest_sha256();
    let captured_checkpoints = recorded_physical_checkpoints;
    drop(host.model_mut().resident.take());
    let run_end = Instant::now();
    let wall_seconds = prior_wall_seconds + run_end.duration_since(run_start).as_secs_f64();
    let execution_wall_seconds = prior_execution_seconds +
        finalization_start.duration_since(execution_start).as_secs_f64();
    let rate = |count: u64, seconds: f64| {
        (seconds > 0.0).then(|| count as f64 / seconds)
    };
    let campaign_outcome = mission.filter(|_| replay_inputs.is_none() && !user_closed &&
        failed_window.is_none() && cleanup_errors.is_empty() && completed_episodes == [1])
        .and_then(|mission| {
            let finalized = host.simulation().world(0)?
                .state.events.latest_finalized_episode()?;
            let result = finalized.result;
            // The exact gameplay episode already identified the physical
            // mission outcome. Campaign progression must not reinterpret
            // a mere opponent elimination as a successful extraction.
            // Ordinary elimination battles retain their historical meaning.
            let mission_success = result.winner_side == mission.player_side &&
                finalized.mission.is_none_or(|objective|
                    objective.completed ==
                        (objective.objective_side == mission.player_side));
            Some(CampaignOutcome {
                campaign_id: mission.campaign_id.to_owned(), mission_id: mission.mission_id.to_owned(),
                player_side: mission.player_side, winner_side: result.winner_side,
                mission_success: Some(mission_success),
                awarded_ships: if mission_success {
                    mission.victory_grants.to_vec()
                } else { Vec::new() },
                awarded_squads: if mission_success {
                    mission.victory_squads.to_vec()
                } else { Vec::new() },
            })
        });
    // RecordStats and CollectMinedMineralsForPlayer are independent source
    // mission actions. Read both from the SAME Level-owned FleetShip mining
    // ledger, but never invent career combat statistics when RecordStats
    // is disabled. No training tick pays for this terminal-only projection.
    // Transient minions and unrelated factions never contribute account TSV.
    let record_fleet_stats = mission.is_some_and(|value| value.record_fleet_stats);
    let banking_side = mission.filter(|value|
        value.bank_player_minerals &&
        campaign_outcome.as_ref().is_some_and(CampaignOutcome::mission_victory)
    ).map(|value| value.player_side);
    let mut banked_minerals = 0_u64;
    let campaign_fleet = if campaign_outcome.is_some() &&
        mission.is_some_and(|value| value.record_fleet_stats || value.bank_player_minerals)
    {
        let state = &host.simulation().world(0)
            .ok_or_else(|| invalid("completed campaign World is unavailable"))?.state;
        let mut seen = HashSet::new();
        let mut fleet = Vec::new();
        for ship in state.combat.ships() {
            let Some(value) = state.metadata.fleet.get(ship.entity_id) else { continue };
            if !value.has_persistent_fleet_value { continue; }
            // A persistent FleetShip ID is not its transient combat entity ID.
            let fleet_ship_id = state.combat.ship_fleet_identity(ship.entity_id)
                .ok_or_else(|| invalid("persistent ship lacks its authored FleetShip identity"))?;
            if fleet_ship_id <= 0 || !seen.insert(fleet_ship_id) {
                return Err(invalid("duplicate or invalid persistent FleetShip in completed campaign").into());
            }
            let killed = state.metadata.fleet.was_killed(ship.entity_id);
            if banking_side == Some(ship.side) && !killed {
                banked_minerals = banked_minerals.checked_add(
                    u64::try_from(value.minerals_mined_this_level)
                        .map_err(|_| invalid("negative mined mineral balance"))?
                ).ok_or_else(|| invalid("banked campaign mineral overflow"))?;
            }
            if record_fleet_stats {
                fleet.push(CampaignFleetShipOutcome {
                    fleet_ship_id, side: ship.side,
                    minerals_mined_this_level: value.minerals_mined_this_level,
                    is_dead: Some(killed),
                    combat: state.metadata.fleet.combat_stats(ship.entity_id),
                });
            }
        }
        if record_fleet_stats {
            fleet.sort_unstable_by_key(|ship| ship.fleet_ship_id);
        }
        Some(fleet)
    } else if campaign_outcome.is_some() {
        // Explicitly empty: the authored campaign Stage did not record
        // persistent fleet statistics or bank minerals.
        Some(Vec::new())
    } else { None };
    // Saved-squad career stats are derived from exactly the same verified
    // FleetShip outcomes. This does not create a second damage, death or
    // mining ledger in the host, and never mistakes Stage ItemIds for
    // identities that survive the next mission.
    let campaign_squads = if let Some(fleet) = &campaign_fleet {
        let by_id = fleet.iter().map(|ship| (ship.fleet_ship_id, ship))
            .collect::<HashMap<_, _>>();
        let mut squads = Vec::with_capacity(saved_squad_sources.len());
        for source in &saved_squad_sources {
            let mut outcome = CampaignSquadOutcome {
                saved_squad_id: source.saved_squad_id,
                side: source.side,
                ships_deployed: source.fleet_ship_ids.len() as u64,
                ships_lost: 0, damage_done: 0, damage_received: 0, kills: 0,
            };
            for fleet_id in &source.fleet_ship_ids {
                let ship = by_id.get(fleet_id).ok_or_else(||
                    invalid("a recorded saved squad member lacks a finalized FleetShip outcome"))?;
                if ship.side != source.side {
                    return Err(invalid("saved squad side changed during battle").into());
                }
                if ship.is_dead == Some(true) {
                    outcome.ships_lost += 1;
                }
                if let Some(combat) = ship.combat {
                    outcome.damage_done = outcome.damage_done
                        .checked_add(combat.enemy_tsv_damage_done)
                        .ok_or_else(|| invalid("saved squad damage overflow"))?;
                    outcome.damage_received = outcome.damage_received
                        .checked_add(combat.tsv_damage_received)
                        .ok_or_else(|| invalid("saved squad damage overflow"))?;
                    outcome.kills = outcome.kills
                        .checked_add(combat.attributed_enemy_kills)
                        .ok_or_else(|| invalid("saved squad kill count overflow"))?;
                }
            }
            squads.push(outcome);
        }
        squads.sort_unstable_by_key(|row| row.saved_squad_id);
        Some(squads)
    } else { None };
    // CollectMinedMineralsForPlayer banks only after actual mission
    // victory, even when the source Stage opts out of RecordStats.
    // A completed defeat has an explicit zero-income receipt.
    let campaign_banked_minerals = if campaign_outcome.is_some() &&
        mission.is_some_and(|value| value.bank_player_minerals) {
        Some(banked_minerals)
    } else { None };
    // Include all current episode admissions as well as those from
    // previously recycled worlds. This covers independent multi-episode
    // training and fixed-seed evaluation without requiring hot-path logs.
    let mut reinforcement_arrivals = past_reinforcement_arrivals;
    let mut reinforcement_idle_ticks_skipped = past_reinforcement_idle_ticks_skipped;
    let mut reinforcement_wakeup_scans = past_reinforcement_wakeup_scans;
    let mut queen_controllers = past_queen_controllers;
    for index in 0..host.simulation().world_count() {
        if let Some(world) = host.simulation().world(index) {
            reinforcement_arrivals.merge(world.state.events.reinforcement_arrivals());
            reinforcement_idle_ticks_skipped +=
                world.state.metadata.reinforcement_idle_ticks_skipped;
            reinforcement_wakeup_scans += world.state.metadata.reinforcement_wakeup_scans;
            queen_controllers.merge(world.state.metadata.queen_controller_measurements);
        }
    }
    let mut final_summary = json!({
        "kind": "run_final",
        "source_scene_template_cache": {
            "distinct_source_documents": unique_source_documents,
            "distinct_parsed_layouts": unique_source_templates,
            "worlds_initialized": source_template_clone_count,
            "episodes_recycled": recycled_template_clone_count,
            "source_parse_count": source_template_parse_count,
            "source_parse_wall_seconds": source_template_parse_wall.as_secs_f64(),
            "initial_template_clone_wall_seconds": source_template_clone_wall.as_secs_f64(),
            "recycled_template_clone_wall_seconds": recycled_template_clone_wall.as_secs_f64(),
            // A historical reset reparsed the scene and reapplied its full
            // physical layout. This measures removed work, not claimed SPS.
            "recycle_source_parses_avoided": recycled_template_clone_count,
        },
        "reinforcement_arrivals": reinforcement_arrivals,
        "reinforcement_wakeup_work": {
            "idle_ticks_skipped": reinforcement_idle_ticks_skipped,
            "wakeup_scans": reinforcement_wakeup_scans,
        },
        "queen_minion_controllers": queen_controllers,
        "map_border_ships": {
            "entries": map_border_entries,
            "movement_stops": map_border_movement_stops,
            "override_skips": map_border_override_skips,
            "lethal_hits": map_border_lethal_hits,
            "lethal_kills": map_border_lethal_kills,
            "confinement_position_corrections": map_border_confinement_corrections,
            "confinement_velocity_clamps": map_border_velocity_clamps,
            "confinement_unfittable_hulls": map_border_unfittable,
            "confinement_missing_profiles": map_border_missing_profiles,
            "completed_episodes": completed_episodes.iter()
                .map(|&count| u64::from(count)).sum::<u64>(),
        },
        "policy_boundary_capture": {
            "admission_rows": admission_snapshot_rows,
            "admission_frames": admission_snapshot_frames,
            "retirement_rows": retirement_snapshot_rows,
            "retirement_frames": retirement_snapshot_frames,
            "observation_build_wall_seconds": policy_boundary_capture_nanos as f64 / 1e9,
        },
        "remote_play": remote.as_ref().map(|server| server.measurements()),
        "native_recording_durability": recorded_inputs.as_ref().map(|_| json!({
            "checkpoint_syncs": trace_checkpoint_syncs,
            "checkpoint_sync_wall_seconds": trace_checkpoint_sync_wall_seconds,
            "player_input_syncs": trace_input_syncs,
            "player_input_sync_wall_seconds": trace_input_sync_wall_seconds,
            "hivemind_ingress_syncs": network.as_ref()
                .map_or(0, |network| network.recorded_network_syncs),
            "hivemind_ingress_sync_wall_seconds": network.as_ref()
                .map_or(0.0, |network| network.recorded_network_sync_wall_seconds),
        })),
        "run_id": config.run_id,
        "rounds": rounds,
        "throughput": {
            "wall_seconds": wall_seconds,
            "startup_wall_seconds": prior_startup_seconds +
                execution_start.duration_since(run_start).as_secs_f64(),
            "execution_wall_seconds": execution_wall_seconds,
            "finalization_wall_seconds": run_end.duration_since(finalization_start).as_secs_f64(),
            "successful_world_steps": successful_world_steps,
            "successful_policy_rows": successful_policy_rows,
            "world_steps_per_wall_second": rate(successful_world_steps, wall_seconds),
            "policy_rows_per_wall_second": rate(successful_policy_rows, wall_seconds),
            "world_steps_per_execution_second": rate(successful_world_steps, execution_wall_seconds),
            "policy_rows_per_execution_second": rate(successful_policy_rows, execution_wall_seconds),
            "requested_physics_workers": physical_workers.get(),
            "requested_navigation_workers_per_level": navigation_workers.unwrap_or(0),
            "parallel_physics_rounds": parallel_physics_rounds,
            "parallel_physics_direct_rounds": parallel_physics_direct_rounds,
            "parallel_physics_queued_rounds":
                parallel_physics_rounds - parallel_physics_direct_rounds,
            "parallel_stage_id_serialized_rounds": stage_id_serialized_rounds,
            "parallel_stage_id_serialized_arenas": stage_id_serialized_arenas,
            "peak_parallel_physics_workers": peak_parallel_physics_workers,
            "parallel_worker_cpu_wall_seconds_sum": parallel_physics_worker_nanos as f64 / 1e9,
        },
        "policy_observations": {
            "rows_encoded": status.perception_work.observations,
            "native_mission_rows": status.perception_work.native_mission_rows,
            "native_mission_rows_by_kind": {
                "survival": status.perception_work.native_mission_rows_by_kind[0],
                "demolition": status.perception_work.native_mission_rows_by_kind[1],
                "escort": status.perception_work.native_mission_rows_by_kind[2],
                "extraction": status.perception_work.native_mission_rows_by_kind[3],
            },
            "native_mission_visible_target_rows":
                status.perception_work.native_mission_visible_target_rows,
            "native_mission_destination_rows":
                status.perception_work.native_mission_destination_rows,
            "native_mission_encoding_version": bees_sim::perception::NATIVE_MISSION_OBSERVATION_VERSION,
            "native_mission_objective_start": bees_sim::perception::OBJECTIVE_START,
            "native_mission_objective_width": bees_sim::perception::OBJECTIVE_LEN,
            "allies_encoded": status.perception_work.allies_encoded,
            "enemies_encoded": status.perception_work.enemies_encoded,
            "map_objects_encoded": status.perception_work.map_objects_encoded,
        },
        "sampled_model_timing": (status.inference.model_forward_timed_calls != 0).then(|| json!({
            "calls": status.inference.model_forward_timed_calls,
            "rows": status.inference.model_forward_timed_rows,
            "wall_seconds": status.inference.model_forward_nanos as f64 / 1e9,
        })),
        "policy_generation": policy_generation,
        "captured_policy_rows": captured_policy_rows,
        "policy_manifest_sha256": policy_manifest_sha256,
        "completed_episodes": completed_episodes.iter()
            .map(|&count| u64::from(count)).sum::<u64>(),
        "completed_worlds": status.completed_worlds,
        // The world-owned counters reset on episode turnover; the simulation
        // records completed fixed-step work separately across all episodes.
        "vision_current_episodes": status.vision,
        "vision_completed_step_totals": status.simulation.vision,
        "ship_slot_work": {
            "integrated_bodies": status.simulation.integrated_bodies,
            "inactive_ship_slots_skipped": status.simulation.inactive_ship_slots_skipped,
            "inactive_projectile_slots_skipped":
                status.simulation.inactive_projectile_slots_skipped,
            "inactive_ship_grid_slots_skipped":
                status.simulation.inactive_ship_grid_slots_skipped,
            "inactive_obstacle_slots_skipped":
                status.simulation.inactive_obstacle_slots_skipped,
            "inactive_obstacle_grid_slots_skipped":
                status.simulation.inactive_obstacle_grid_slots_skipped,
        },
        "navigation_current_episodes": status.navigation_workers,
        "navigation_raster_work_current_episodes": status.navigation_rasters,
        "scripted_command_work_current_episodes": status.scripted_queues,
        "scripted_command_plan": {
            "worlds_with_orders": config.levels.iter()
                .filter(|level| !level.scripted_queues.is_empty()).count(),
            "configured_queues": config.levels.iter()
                .map(|level| level.scripted_queues.len()).sum::<usize>(),
            "configured_orders": config.levels.iter()
                .flat_map(|level| level.scripted_queues.iter())
                .map(|queue| queue.orders.len()).sum::<usize>(),
            "configured_demolition_bombard_orders": config.levels.iter()
                .flat_map(|level| level.scripted_queues.iter())
                .flat_map(|queue| queue.orders.iter())
                .filter(|order| matches!(order,
                    ScriptedOrderConfig::BombardMapObject { .. }))
                .count(),
            "configured_tactical_maneuvers": config.levels.iter()
                .flat_map(|level| level.scripted_queues.iter())
                .flat_map(|queue| queue.orders.iter())
                .filter(|order| matches!(order,
                    ScriptedOrderConfig::CircleNearest |
                    ScriptedOrderConfig::RightSwipeNearest |
                    ScriptedOrderConfig::LeftSwipeNearest |
                    ScriptedOrderConfig::InAndOutNearest))
                .count(),
            "min_queues_per_world": config.levels.iter()
                .map(|level| level.scripted_queues.len()).min().unwrap_or(0),
        },
        "beehive_healing_cascade_kills_current_episodes":
            status.game_healing_cascade_kills,
        "beehive_healing_reserved_ships": status.game_healing_reserved_ships,
        "beehive_healing_active_ships": status.game_healing_active_ships,
        "campaign_outcome": campaign_outcome,
        "campaign_fleet": campaign_fleet,
        "campaign_squads": campaign_squads,
        "campaign_banked_minerals": campaign_banked_minerals,
        "aborted_worlds": status.aborted_worlds,
        "failed_worlds": status.failed_worlds,
        "running_worlds": status.running_worlds,
        "pending_notifications": status.queued_notifications,
        "pending_store_commands": status.pending_store_commands,
        "pending_store_hashes": pending_store_hashes,
        "pending_store_reconciliations": status.pending_store_reconciliations,
        // These IDs remain owned by the checkpoint until an explicit
        // settlement or review decision; a 409 is never a successful
        // complete-batch acknowledgement.
        "store_reconciliation": pending_store_reconciliation,
        "socket_flush_timed_out": socket_flush_timed_out,
        "pending_hivemind_requests": status.pending_hivemind_requests,
        "socket_close_confirmed": socket_close_confirmed,
        "network": network.as_ref().map(|network| json!({
            "measurements": network.worker.measurements(),
            "queue_backpressure": network.worker.queue_backpressure(),
            "transient_store_retries": network.worker.transient_store_retries(),
            "recorded_hivemind_events": network.recorded_network_events,
            "setups_remaining": network.levels.len() - network.next_level,
            "source_commands": {
                "eligible": network.scheduler.measurements().eligible,
                "issued": network.scheduler.measurements().issued,
                "out_of_bounds": network.scheduler.measurements().out_of_bounds,
                "home_moves": network.scheduler.measurements().home_moves,
                "home_unreachable": network.scheduler.measurements().home_unreachable,
                "unauthored_minions": network.scheduler.measurements().unauthored_minions,
                "enemy_type_scans": network.scheduler.measurements().enemy_type_scans,
                "enemy_type_scan_reuses": network.scheduler.measurements().enemy_type_scan_reuses,
            },
            "source_command_timer": network.scheduler.schedule_measurements(),
        })),
        "model_updates_applied": next_model_update,
        "model_updates_remaining": config.model_updates.len() - next_model_update,
        "evaluation": evaluation,
        "mean_episode_seconds": mean_episode_seconds,
        "active_policy_segment": {
            "policy_generation": segment_generation,
            "policy_manifest_sha256": segment_manifest_sha256,
            "from_round": segment_start_round,
            "through_round": rounds,
            "evaluation": final_segment,
            "mean_episode_seconds": final_segment_mean,
        },
        "failed_window": failed_window,
        "cleanup_errors": cleanup_errors,
        "user_closed": user_closed,
        "player_input_playback": playback.is_some(),
        "player_input_playback_complete": playback.as_ref().map(|trace|
            rounds == trace.end_round && trace.actions.is_empty() &&
            trace.checkpoints.is_empty() && failed_window.is_none()),
        "recorded_physical_checkpoints": captured_checkpoints,
        "recorded_player_inputs": recorded_player_inputs,
        "verified_physical_checkpoints": verified_physical_checkpoints,
        "verified_gameplay_checkpoints": verified_gameplay_checkpoints,
        "player_trace_stream": playback.as_ref().map(|trace| trace.measurements()),
        "final_physical_worlds": final_physical_worlds,
        "final_gameplay_worlds": final_gameplay_worlds,
    });
    if config.levels.iter().any(|level| level.native_layout.is_some()) {
        final_summary["native_layouts"] = json!(config.levels.iter().filter_map(|level|
            level.native_layout.as_ref().map(|layout| json!({
                "world_id": level.world_id,
                "removed_static": layout.remove_static_ids.len(),
                "placed_boxes": layout.add_static_boxes.len(),
                "placed_polygons": layout.add_static_polygons.len(),
                "translated_squads": layout.translate_squads.len(),
                "cloned_squads": layout.clone_squads.len(),
                "cloned_ships": layout.clone_squads.iter()
                    .map(|entry| entry.ship_ids.len()).sum::<usize>(),
                "removed_squads": layout.remove_squads.len(),
            }))
        ).collect::<Vec<_>>());
    }

    println!("{final_summary}");
    #[cfg(feature = "client")]
    if let Some(client) = &client {
        println!("{}", json!({ "kind": "presentation_final", "run_id": config.run_id,
            "rendered_frames": client.rendered_frames,
            "hotseat_switches": client.hotseat_switches,
            "hotseat_final_side": client.hotseat_side(),
            "audio": client.audio_measurements(),
            "fixed_steps_executed": client.fixed_steps_executed,
            "multi_step_frames": client.multi_step_frames,
            "max_steps_per_frame": client.max_steps_per_frame,
            "pacing_lag_clamps": client.pacing_lag_clamps,
            "rendered_pixels": client.rendered_pixels,
            "render_wall_seconds": client.render_wall_seconds,
            "ui_wall_seconds": client.ui_wall_seconds,
            "window_update_wall_seconds": client.window_update_wall_seconds,
            "viewport_resizes": client.viewport_resizes,
            "minimap_markers_drawn": client.minimap_markers_drawn,
            "numbered_squad_rows_drawn": client.numbered_squad_rows_drawn,
            "striker_bomb_indicators_drawn": client.striker_bomb_indicators_drawn,
            "minimap_camera_moves": client.minimap_camera_moves,
            "camera_pan_frames": client.camera_pan_frames,
            "camera_wheel_pans": client.camera_wheel_pans,
            "camera_boundary_clamps": client.camera_boundary_clamps,
            "camera_zoom_clamps": client.camera_zoom_clamps,
            "minimap_move_orders_submitted": client.minimap_move_orders_submitted,
            "tactical_button_clicks": client.tactical_button_clicks,
            "squad_tab_clicks": client.squad_tab_clicks,
            "shooting_priority_requests_submitted": client.shooting_priority_requests_submitted,
            "selected_command_rows_drawn": client.selected_command_rows_drawn,
            "command_target_markers_drawn": client.command_target_markers_drawn,
            "numbered_shortcut_selections": client.numbered_shortcut_selections,
            "cycled_shortcut_selections": client.cycled_shortcut_selections,
            "final_viewport_pixels": client.viewport_size().0 * client.viewport_size().1,
            "culled_ship_draws": client.culled_ship_draws,
            "ship_sprite_draws": client.ship_sprite_draws,
            "combat_impacts_observed": client.combat_impacts_observed,
            "combat_impact_visual_draws": client.combat_impact_visual_draws,
            "combat_impact_visuals_dropped": client.combat_impact_visuals_dropped,
            "custom_ship_color_draws": client.custom_ship_color_draws,
            "ship_color_cache_misses": client.ship_color_cache_misses,
            "ship_color_cache_variants": client.ship_color_cache_variants,
            "sprite_raster_candidate_pixels": client.sprite_raster_candidate_pixels,
            "ship_fallback_hulls": client.ship_fallback_hulls,
            "ship_art_types_loaded": client.ship_art_types_loaded,
            "asteroid_sprite_draws": client.asteroid_sprite_draws,
            "asteroid_piece_sprite_draws": client.asteroid_piece_sprite_draws,
            "asteroid_fallback_hulls": client.asteroid_fallback_hulls,
            "asteroid_art_types_loaded": client.asteroid_art_types_loaded,
            "projectile_sprite_draws": client.projectile_sprite_draws,
            "projectile_explosion_sprite_draws": client.projectile_explosion_sprite_draws,
            "projectile_fallback_hulls": client.projectile_fallback_hulls,
            "projectile_art_types_loaded": client.projectile_art_types_loaded,
            "culled_obstacle_draws": client.culled_obstacle_draws,
            "culled_projectile_draws": client.culled_projectile_draws,
            "culled_piece_draws": client.culled_piece_draws,
            "weapon_geometry_queries": client.weapon_geometry_queries,
            "weapon_range_candidates_culled": client.weapon_range_candidates_culled }));
    }
    if failed_window.is_some() || !cleanup_errors.is_empty() {
        // A failed session has no committed success summary or completed
        // replay footer. Its authenticated peers must not infer victory
        // from a last, possibly stale world snapshot.
        publish_failed_multiplayer_delivery(&mut remote, &config.run_id);
        return Err(invalid(
            "headless rollout failed; run_final identifies the original failure and unresolved obligations",
        ).into());
    }
    if let Some(summary_path) = summary {
        // Crash-safe for ordinary native rollouts and campaigns alike.
        // A terminal checkpoint may already be durable, but no unfinished
        // run_final is allowed to block its authenticated continuation.
        let commit: Result<(), Box<dyn Error>> =
            if summary_path.exists() || summary_path.is_symlink() {
                (|| -> Result<(), Box<dyn Error>> {
                    // A process can terminate after committing the exact
                    // battle/career receipt but before returning to its
                    // caller. Never duplicate campaign grants, and never
                    // overwrite a different battle's immutable receipt.
                    if !recovered_existing_host ||
                        !fs::symlink_metadata(&summary_path)?.file_type().is_file() ||
                        fs::metadata(&summary_path)?.len() > 16 * 1024 * 1024
                    {
                        return Err(invalid("native terminal receipt already belongs to another session").into());
                    }
                    let committed: Value = serde_json::from_slice(&fs::read(&summary_path)?)?;
                    const FIELDS: &[&str] = &[
                        "kind", "run_id", "rounds", "completed_episodes",
                        "policy_generation", "policy_manifest_sha256",
                        "final_physical_worlds", "final_gameplay_worlds",
                        "campaign_outcome", "campaign_fleet", "campaign_squads",
                        "campaign_banked_minerals",
                    ];
                    if FIELDS.iter().any(|&field|
                        committed.get(field) != final_summary.get(field)) ||
                        committed["kind"] != "run_final" ||
                        !committed["failed_window"].is_null() ||
                        committed["cleanup_errors"] != json!([]) ||
                        committed["user_closed"] != false
                    {
                        return Err(invalid("native terminal receipt differs from the recovered authoritative battle").into());
                    }
                    println!("{}", json!({
                        "kind": "native_terminal_receipt_reused",
                        "run_id": config.run_id,
                        "rounds": rounds,
                        "campaign": campaign_outcome.is_some(),
                    }));
                    Ok(())
                })()
            } else {
                persist_new_json(&summary_path, &final_summary)
                    .map_err(Into::into)
            };
        if let Err(error) = commit {
            // The original session cannot claim completed progress if its
            // final summary was not durably committed. The same terminal
            // channel informs remote players without awarding anything.
            publish_failed_multiplayer_delivery(&mut remote, &config.run_id);
            return Err(error);
        }
        // The campaign ledger consumes ONLY this finalized immutable
        // summary. Tell authenticated multiplayer campaign owners about
        // their saved progress after the same durable commit, never when
        // physics merely reports an episode victory.
        if let (Some(server), Some(outcome)) = (&mut remote, campaign_outcome.as_ref()) {
            server.publish_campaign_receipt(
                outcome.player_side, &final_summary["campaign_outcome"],
                campaign_banked_minerals,
            );
        }
    }
    // A completed game result must not depend on the replaceable state
    // snapshot surviving the network drain. Send a small, reliable terminal
    // receipt from the same authoritative Level only after the durable
    // finalization/summary boundary, including non-campaign battles.
    if let Some(server) = &mut remote {
        if let Some(world) = host.render_world(0) {
            if world.terminal_result.is_some() {
                server.publish_battle_result(&world);
            } else {
                server.publish_interrupted_battle();
            }
        } else {
            server.publish_interrupted_battle();
        }
        server.drain_terminal_output(Duration::from_millis(350));
        // Final delivery occurs after the immutable run summary was
        // committed. Report the actual post-drain counters separately:
        // the earlier run_final snapshot cannot truthfully include bytes,
        // client receipts or stalls that happened after its commit.
        println!("{}", json!({
            "kind": "native_remote_terminal_delivery",
            "run_id": config.run_id,
            "measurements": server.measurements(),
        }));
    }
    // Publish replay eligibility last. Every prior error, including
    // final sink/capture cleanup and the atomic campaign summary commit,
    // must prevent the recording from appearing as a finished game.
    if let Some(mut trace) = input_trace {
        writeln!(trace, "{}", json!({
            "kind": "player_input_trace_end",
            "rounds": rounds,
            "recorded_inputs": recorded_player_inputs,
            "user_closed": user_closed,
            "failed_window": failed_window,
            "policy_actions_sha256": policy_actions_sha256,
        }))?;
        trace.sync_all()?;
    }
    if play && !user_closed && (playback.is_some() ||
        completed_episodes.iter().all(|&count| count == config.episodes_per_world)) {
        #[cfg(feature = "client")]
        if let Some(client) = &mut client {
            use bees_host::client::{NativeResultAction, NativeResultControls};
            // A fresh campaign battle must reload its newly committed
            // fleet and mission progress. Never restart a rematch using
            // the pre-battle casualty snapshot still held by this session.
            let controls = match (mission, replay_inputs, recorded_inputs.as_ref(), output) {
                (Some(_), _, Some(_), _) => NativeResultControls::WatchAgain,
                (Some(_), _, None, _) => NativeResultControls::Close,
                (None, Some(_), _, _) => NativeResultControls::WatchAgain,
                (None, None, Some(_), _) => NativeResultControls::PlayAgainOrWatch,
                (None, None, None, Some(_)) => NativeResultControls::PlayAgain,
                (None, None, None, None) => NativeResultControls::Close,
            };
            client.show_result(controls);
            loop {
                let index = client.selected_world();
                let current = host.render_world(index)
                    .ok_or_else(|| invalid("completed Level disappeared"))?;
                if matches!(client.poll(current, client_bounds[index], host.simulation().world_count(),
                    client_step_interval_by_level[index])?, bees_host::client::NativeClientAction::Quit) {
                    break;
                }
                if let Some(action) = client.result_action() {
                    let replay_inputs = match action {
                        NativeResultAction::PlayAgain => None,
                        NativeResultAction::WatchRecording => replay_inputs.map(Path::to_path_buf).or(recorded_inputs),
                    };
                    return Ok(Some(BattleRestart { replay_inputs }));
                }
            }
        }
    }
    Ok(None)
}
